Ceviri.ekle("ka","olay",{
"OLAYLAR_EK5:1354-03-02:0":{"b": ["გალიპოლის აღება — მუდმივი პლაცდარმი რუმელიაში", "ba51a160"], "d": ["ოსმალებმა, რომლებიც 1349-1352 წლებში კანტაკუზენოსის მოკავშირის სტატუსით გალიპოლის მიდამოებს გაეცნენ, ის 1354 წელს ხელში ჩაიგდეს; ქალაქის გალავნის დამანგრეველმა დიდმა მიწისძვრამ ხელსაყრელი შემთხვევა შექმნა. ამგვარად ჩიმპეს ვიწრო პლაცდარმი ბოსფორის რუმელიის ნაპირზე ნამდვილ ბაზად იქცა და თრაკიისკენ გამავალი კარი ფართოდ გაიღო. გალიპოლი 1366 წელს სავოიური ჯვაროსნული ლაშქრობისას ხელიდან გავიდოდა, მაგრამ 1376 წლის მეორე აღებით საბოლოოდ ოსმალთა ბატონობაში შევიდოდა. იმავე თარიღს შემოერთებული სხვა ადგილები: ქილითბაჰირი.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["რუმელიის დამპყრობლის, სულეიმან-ფაშას, სიკვდილი", "2dc98228"], "d": ["ორჰან ბეის უფროსი ვაჟი და რუმელიის დაპყრობების არქიტექტორი სულეიმან-ფაშა, წყაროებში მოცემული 758 (1357), 759 და 760 (1359) თარიღებიდან ყველაზე მიღებული თარიღის, 1357 წლის შემოდგომაზე, ნადირობისას ცხენიდან გადმოვარდნით გარდაიცვალა. 1352-1354 წლებში გადასვლებით რუმელიაში მუდმივი ოსმალური ყოფნის დამაარსებელი უფლისწულის სიკვდილმა ტახტის მემკვიდრეობის რიგი მის ძმას მურადს დაუტოვა. ბოლაირში დაკრძალული სულეიმან-ფაშას აკლდამა ოსმალეთის ევროპაში უძველეს დინასტიურ ძეგლად დარჩა.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["ფენჯიქის კანონი — იანიჩართა კორპუსის საფუძვლის ჩაყრა", "e5877c2d"], "d": ["რუმელიის დაპყრობების შემდეგ ულემადან ყარამანელი ყარა რუსთემის რჩევით ძალაში შევიდა ფენჯიქის სისტემა, რომელიც ითვალისწინებდა ომის ტყვეების მეხუთედის ან მისი ფულადი ეკვივალენტის სახელმწიფოსთვის გამოყოფას. ამ ტყვეებიდან შერჩეულთა თურქულ ოჯახებში აღზრდითა და ჯარში გაწვევით შეიქმნა უშუალოდ ფადიშაჰზე დამოკიდებული მუდმივი ქვეითი ძალის — იანიჩართა კორპუსის — ბირთვი. ამ მოწესრიგებით დაიწყო ტომობრივ ცხენოსანზე დაყრდნობილი სასაზღვრო საბეილიქოს ცენტრალიზებული ჯარის მქონე სახელმწიფოდ გადაქცევა.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["დასავლეთ თრაკიაში ჩასვლა: გუმულჯინეს აღება", "9ef69221"], "d": ["ედირნეს აღების შემდეგ მარიცას დასავლეთისკენ გამართულმა სასაზღვრო ძალებმა ღაზი ევრენოს ბეის სარდლობით დასავლეთ თრაკიის ცენტრი გუმულჯინე ხელში ჩაიგდეს. ქალაქი წინა საბანაკო შტაბად იქცა, საიდანაც ევრენოს ბეი თავის თავდასხმებს მაკედონიაში გადაიტანდა. ამგვარად თრაკიის ეგეოსის სანაპირომდე გაჭიმული ნაწილი ოსმალურ კონტროლში მოექცა და სალონიკისკენ გზა გაიხსნა.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["ვარნა დობრუჯის სამთავროს გადაეცა და დედაქალაქი გახდა", "2bfe73f9"], "d": ["ბულგარეთის სამეფოს დაშლის პროცესში შავი ზღვის სანაპიროზე მდებარე ვარნა დობროტიჩის მიერ დაარსებულ დობრუჯის სამთავროს შეუერთდა და ამ პატარა სახელმწიფოს დედაქალაქად იქცა.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["ფილიბეს დასავლეთი: თათარფაზარჯიღისა და იჰთიმანის შემოერთება", "1664d0e1"], "d": ["1372 წელს ფილიბეს აღების შემდეგ მარიცას ხეობის ზემო ბოლოში მდებარე თათარფაზარჯიღი და სოფიისკენ გამავალი გადასასვლელის მფლობელი იჰთიმანი ოსმალურ მმართველობას დაუკავშირდა. ჩირმენის ბრძოლის შემდეგ ვასალად ქცეული ადგილობრივი მმართველების ხელში მყოფი ეს ხაზი უშუალო მმართველობაში გადავიდა, რითაც ფილიბე-სოფიის მარშრუტი უწყვეტი გახდა. ეს წინსვლა თორმეტი წლის შემდეგ სოფიის აღებისკენ მიმავალი გზის მომზადებაა.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["სავჯი ბეის აჯანყება — უფლისწულისა და ბიზანტიელი მემკვიდრის ერთობლივი ამბოხი", "75198c33"], "d": ["მურად I-ის ვაჟი სავჯი ბეი და ბიზანტიის იმპერატორ იოანე V-ის ვაჟი ანდრონიკე პალეოლოგოსი 1373 წლის მაისის დასაწყისში ბურსასა და სტამბოლში ერთდროულად აჯანყდნენ მამების წინააღმდეგ. ორი დინასტიის მემკვიდრეების გამაერთიანებელი ეს კავშირი სწრაფად ჩაახშეს; სავჯი ბეი შეპყრობილ იქნა, თვალები დასთხარეს და სიკვდილით დასაჯეს. ოსმალური გადმოცემის მიერ აჯანყებისთვის მოცემული 787 (1385) თარიღი მცდარია; მოვლენა ბიზანტიის ოსმალთა ვასალობაში შესვლის წლების მომდევნო ხანაზე მოდის და აჩვენებს, რამდენად იყო ორი სასახლე ერთმანეთში გადახლართული.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["სტრუმასა და მესტას ხეობები: ქოსთენდილის, პეტრიჩის, ნევროკოპისა და დრამას შემოერთება", "8c0980c4"], "d": ["ჩირმენის გამარჯვების შემდეგ ოსმალეთისთვის ხარაჯის გადახდის დამწყები სერბი და ბულგარელი ადგილობრივი მმართველების ხელში მყოფი სტრუმასა და მესტას ხეობები სასაზღვრო ბეების წინსვლით უშუალო ოსმალურ მმართველობაში აიღეს. ქოსთენდილის, პეტრიჩის, ნევროკოპისა და დრამას შემოერთებით მაკედონიის აღმოსავლეთი ნახევარი გაიხსნა და სალონიკი და სერეზი ალყის რკალში მოექცა. რუკაზე რუმელიის სამხრეთ-დასავლეთით გაფართოება ამ ოპერაციის შედეგია.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["ერეთნას საბეილიქოს დასასრული და ყადი ბურჰანედდინის სახელმწიფოს დაარსება", "60dcaf57"], "d": ["1335 წელს ილხანთა ვალობიდან წარმოშობილი და სივასისა და კაისერის ცენტრის მქონე ცენტრალური ანატოლიის ორმოცდაექვსი წლის მმართველი ერეთნიდები სასახლის შიდა დაპირისპირებებით დაიშალნენ. 1378 წლის მაისში ვეზირად დანიშნულმა ყადი ბურჰანედდინმა მეტოქეების, ქილიჯარსლანისა და ჰაჯი შადგელდის, ჩამოშორების შემდეგ 1381 წლის შემოდგომაზე თავი სულთნად გამოაცხადა, საბეილიქოს ბოლო მოუღო და საკუთარი სახელობის სახელმწიფო დააარსა. ამგვარად ოსმალეთის აღმოსავლეთის მეზობელი შეიცვალა; სივას-კაისერის ხაზი ამიერიდან ჩვიდმეტი წელი ყადი ბურჰანედდინის ხელში დარჩებოდა.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["თემურმა ჰერათი აიღო: ქერთების დინასტიის დასასრული და ხორასანის თემურიდებზე გადასვლა", "15f6019e"], "d": ["ხორასანი 1380 წელს სერბედარებს, ქერთებსა და მუზაფარიდებს შორის ბრძოლით დანაწევრებული იყო. თემურმა ვაჟი მირან შაჰი მხარეში გაგზავნის შემდეგ თავად ჰერათისკენ გაემართა და გარკვეული ხნის ალყის შემდეგ ქალაქი ქერთ მელიქ ღიას ად-დინ ფირ ალისგან ჩაიბარა. მისი წასვლის შემდეგ ატეხილი აჯანყება მირან შაჰმა სისხლში ჩაახშო და 1255 წლიდან ჰერათში მმართველ ქერთების დინასტიას ბოლო მოუღო. მაშჰადიდან ნიშაფურამდე მთელი ხორასანი ამ თარიღში თემურიდულ მმართველობაში შევიდა.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["მაკედონიის სიღრმეში წინსვლა: მონასტირისა და ოჰრიდის აღება", "63bb7838"], "d": ["ვია ეგნატიაზე მდებარე მონასტირი და ტბის ნაპირას მდებარე ოჰრიდი ალბანეთის მიმართულებით თავდასხმებისას ოსმალურ მმართველობაში გადავიდა. ორივე ადრიატიკისკენ მიმავალი გზის საკვანძო წერტილი იყო; ოჰრიდი ამასთან ბალკანეთის უძველესი მართლმადიდებლური მთავარეპისკოპოსობის ცენტრიც იყო. TDV აღნიშნავს, რომ ოჰრიდის აღების თარიღის შესახებ ზუსტი ცნობა არ არსებობს და გამოთქმულია 787 (1385) წელი და კრალიევიჩ მარკოს სიკვდილის შემდგომი 797 (1395) წელი; აქ საფუძვლად 1385 წელია აღებული. მონასტირი მომდევნო საუკუნეებში რუმელიის ერთ-ერთი უმნიშვნელოვანესი სამხედრო ცენტრი გახდებოდა.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["სავრას ბრძოლა — ალბანეთის კარის გახსნა", "dda6671b"], "d": ["ბალშების დინასტიის წინააღმდეგ შევიწროებული ალბანელი ბეის, კარლო თოფიას, დახმარების მოწოდებით ოსმალურმა ძალებმა სავრას ველზე ბალშა II-ის ჯარი დაამარცხა; ბალშა ბრძოლის ველზე დაიღუპა. ადგილობრივი ბეის მიწვევით დაწყებულმა ამ ომმა ოსმალებს ადრიატიკის სანაპიროებამდე გაჭიმულ ალბანურ მიწებზე პირველი მუდმივი გავლენა მოუტანა. მხარის ბეების ერთმანეთთან დაპირისპირების ხელსაყრელ შემთხვევად ქცევის ეს პოლიტიკა მომდევნო საუკუნის განმავლობაში ბალკანეთის დაპყრობების უცვლელი მეთოდი გახდებოდა.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["თემურის „სამწლიანი ლაშქრობა“: აზერბაიჯანისა და ჩრდილოეთ ირანის აღება", "2a98ec51"], "d": ["ხორასანის ლაშქრობებისას ირანის დაქსაქსული მდგომარეობა ახლოდან ნანახმა თემურმა 788 წელს (1386) დასავლეთისკენ გაილაშქრა. „სამწლიანი ლაშქრობის“ სახელით ცნობილ 1386-1388 წლების ოპერაციაში მან მაზანდარანის, ლურისტანისა და საქართველოს გავლით აზერბაიჯანში გადაინაცვლა და ყარაბაღს მიაღწია; თავრიზი, არდაბილი, ურმია და ნახიჭევანი თემურიდულ მმართველობაში შევიდა. ჩრდილოეთ ირანისა და აზერბაიჯანის ხელში ჩაგდება, ისევე როგორც ოდესღაც ჯუჩის ულუსსა და ილხანებს შორის, ოქროს ურდოსთან ხანგრძლივი დაპირისპირების დასაწყისიც გახდა.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["ფრენქიაზის ბრძოლა და კონიის ალყა — პირველი ყარამანის ლაშქრობა", "af4e5d77"], "d": ["სიძეობის მიუხედავად დასავლეთ ანატოლიაში ოსმალეთის გაფართოებით შეწუხებული ყარამანიდ ალაედდინ ალი ბეის წინააღმდეგ მურად I პირადად გავიდა ლაშქრობაში; ფრენქიაზის სახელით ცნობილ ადგილას გამართულ ბრძოლაში გაწვრთნილმა და გამოცდილმა ოსმალურმა ჯარმა ყარამანული ძალები დაამარცხა. შემდეგ კონიის ციხეს ალყა შემოარტყეს, მაგრამ ალაედდინ ბეის შეწყალებით საბეილიქო მთლიანად არ მოუსპიათ. ეს ლაშქრობა ოსმალეთსა და ყარამანს შორის ხანგრძლივი ანგარიშსწორების საწყისი ფარდაა, რომელიც ერთ საუკუნეს გაგრძელდებოდა და მხოლოდ 1468 წელს საბოლოო ანექსიით დასრულდებოდა.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["მუში ყარა-ყოიუნლუს მმართველობიდან თემურის მმართველობაში გადავიდა (789/1387)", "ed2e7a11"], "d": ["მონღოლთა ხანის შემდეგ ყარა-ყოიუნლუს მმართველობაში გადასული მუში ჰიჯრით 789 (1387) წელს ყარა-ყოიუნლუს მიწების მფლობელი თემურის მმართველობაში მოექცა. ატლასში მუში ამ წელს ყარა-ყოიუნლუდან თემურიანებზეა გადაწერილი.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["გალიპოლის გემთსაშენის დაარსება — ოსმალური ფლოტის დაბადება", "47546241"], "d": ["ოსმალეთის სახელმწიფოს პირველი სრულფასოვანი გემთსაშენი 1390 წელს იილდირიმ ბაიაზიდმა გალიპოლში, ბიზანტიისგან დარჩენილი გემთსაშენის ადგილზე, დააარსა. დასავლეთ ანატოლიის საბეილიქოების საზღვაო მემკვიდრეობის მიმღები ოსმალეთი ამგვარად პირველად იქცა საზღვაო ძალად, რომელიც საკუთარ გემს თავად აშენებს. დარდანელის სრუტის საკვანძო წერტილში მდებარე გემთსაშენი ერთ-ნახევარი საუკუნის განმავლობაში, სტამბოლის ალყიდან ეგეოსის ლაშქრობებამდე, ოსმალური ფლოტის მთავარ ბაზად მსახურობდა.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["ჰამიდის მხარე ოსმალეთს შეუერთდა: ისფარტა, ბურდური, ულუბორლუ, ეღირდირი", "e3da7de5"], "d": ["ყარამანიდ ალაედდინ ბეის მიერ ჰამიდის მხარეზე თავდასხმისა და ხალხის საჩივრის გამო ლაშქრობაში გასულმა იილდირიმ ბაიაზიდმა ჰამიდიდების დარჩენილი მიწები მთლიანად ხელში ჩაიგდო და მათი მმართველობა ვაჟ ისა ჩელების მისცა.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["მუზაფარიდების დინასტიის დასასრული: შაჰ მანსურის მარცხი შირაზთან", "5fd14eb8"], "d": ["1318 წლიდან იეზდში, ფარსში, ისფაჰანსა და ქირმანში მმართველი მუზაფარიდების უკანასკნელმა ძლიერმა მმართველმა შაჰ მანსურმა ნათესავებთან შეკავშირებით თემურის წინააღმდეგ ამოქმედდა. შირაზის მახლობლად ბრძოლაში ერთ-ერთი ამირის მოწინააღმდეგის მხარეს გადასვლით მან ძალების უმეტესობა დაკარგა, დამარცხდა და მოკლეს. თემურმა შემდეგ დინასტიის ყველა წევრი დაახოცინა, რითაც მუზაფარიდების ბატონობა დასრულდა და ფარსი და ქირმანი თემურიდულ მმართველობას შეუერთდა.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["ამასიის ოსმალურ მიწებთან შეერთება", "fe2860cf"], "d": ["იილდირიმ ბაიაზიდის ცენტრალური ანატოლიის ოპერაციისას ალყაშემორტყმულმა ამასიის ამირამ ქალაქი ოსმალებს ჩააბარა და ბაიაზიდი 1393 წელს ქალაქში შევიდა. სულთანმა მისი მმართველობა თავის ვაჟს, მეჰმედ ჩელებს, დაუტოვა; უფლისწულის სანჯაყის სახით ამასია ამიერიდან ოსმალთა დინასტიის ერთ-ერთ უმნიშვნელოვანეს აღმზრდელ ცენტრად იქცა. იმავე თარიღს ხელიდან გასული სხვა დასახლებები: ლადიქი (ამასია), მერზიფონი, ოსმანჯიქი, ჩორუმი. ეს არჩევანი მომავალ ინტერეგნუმის ხანაში გადამწყვეტი აღმოჩნდებოდა; ჩელები მეჰმედი სახელმწიფოს ხელახლა გაერთიანებისთვის ბრძოლას სწორედ ამ ამასიის ბაზიდან წარმართავდა.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["თემურმა ბაღდადი დაიპყრო — ჯალაირიდები ანატოლიაში გაიქცნენ", "4d5602b3"], "d": ["თემურმა ხანგრძლივი ალყის შემდეგ ბაღდადი ხელში ჩაიგდო; ქალაქის მფლობელი ჯალაირიდი სულთან აჰმედი დასავლეთისკენ გაიქცა და ჯერ მამლუქებს, შემდეგ კი ოსმალურ სასახლეს შეაფარა თავი. ამგვარად თემურის დასავლეთისკენ გაფართოება პირველად უშუალოდ შეეხო ოსმალური გავლენის სფეროს. ორ მმართველს შორის მტრობის პირველი რგოლი აქედან იწყება.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["შავი ზღვის სანაპიროზე ვარნის აღება", "a84b2abf"], "d": ["ბულგარეთის სამეფოს დუნაისა და შავ ზღვას შორის მდებარე მიწების შევიწროებისას სანაპიროზე ყველაზე დიდი პორტი ვარნა ოსმალურ მმართველობაში გადავიდა. პორტის აღებამ დობრუჯის მიმართულებით წინსვლის გზა გახსნა და შავი ზღვის დასავლეთ სანაპიროზე ოსმალეთს პირველი დიდი ნავმისადგომი მოუტანა. ვარნა ორმოცდათერთმეტი წლის შემდეგ 1444 წლის გამარჯვების, ჯვაროსნული ჯარის განადგურების, სცენაც გახდება.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["ნევშეჰირისა და ურგუფის მხარე ყარამანიდებიდან ოსმალთა ხელში გადავიდა", "06ff59e8"], "d": ["ილდირიმ ბაიაზიდის ყარამანიდების წინააღმდეგ ლაშქრობებისას ნევშეჰირის (მუშქარა) და ურგუფის მხარე ჰიჯრით 800/1398 წელს ოსმალური მმართველობის ქვეშ გადავიდა; 1402 წელს ანკარის ბრძოლის შემდეგ თემურმა რეგიონი ყარამანიდებს დაუბრუნა.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["ყადი ბურჰანედდინის სახელმწიფოს დამხობა", "b13391e3"], "d": ["აყ-ყოიუნლუს მმართველ ყარაიულუქ ოსმან ბეის ტყვეობაში მოხვედრილმა ყადი ბურჰანედდინმა სივასის ჩაბარების სანაცვლოდ გათავისუფლება შესთავაზა, მაგრამ ქალაქის მოსახლეობამ წინააღმდეგობა გასწია და სულთანი გალავნის წინ სიკვდილით დასაჯეს. სივასის წარჩინებულებმა მისი ვაჟი ალაედდინ ალი ჩელები სათავეში დააყენეს, მაგრამ აყ-ყოიუნლუს ზეწოლის წინაშე იილდირიმ ბაიაზიდს დახმარება სთხოვეს; სულეიმან ჩელების სარდლობით ოსმალურმა ძალებმა ყარაიულუქი დაამარცხა და ქალაქზე გაბატონდა. ამგვარად ყადი ბურჰანედდინის სახელმწიფო ისტორიას ჩაბარდა და სივასი, თოქათი, ნიქსარი და კაისერი ოსმალურ მიწებს შეუერთდა. იმავე თარიღს შემოერთებული სხვა ადგილები: ქირშეჰირი, ჩორუმი.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["თემურის გამოწვევა: ლტოლვილების გადაცემაზე უარი", "33790bc8"], "d": ["თემურის ზეწოლის გამო ჯალაირიდმა სულთან აჰმედმა და ყარა-ყოიუნლუს ლიდერმა ყარა იუსუფმა ოსმალურ მიწებს შეაფარეს თავი; თემურმა ამ ორი ლტოლვილის გადაცემა მოითხოვა, იილდირიმ ბაიაზიდმა უარყო. ამის შემდეგ ორ მმართველს შორის ურთიერთმძიმე შეურაცხყოფებით სავსე წერილების გაცვლა დაიწყო. ომის იდეოლოგიური ნიადაგი ამ მიმოწერით, ჯერ ერთი ჯარისკაციც არ ამოძრავებულიყო, ისე შეიქმნა.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["ბურსაში იილდირიმის საავადმყოფო (დარუშშიფა) — პირველი ოსმალური ჰოსპიტალი", "5f0dc59a"], "d": ["ბურსაში ბრწყინვალე ულუ ჯამის აშენების წლებში იილდირიმ ბაიაზიდმა ქალაქს ერთი დარუშშიფაც შესძინა; იმარეთის, მედრესეს, ქარვასლისა და ხიდისგან შემდგარი ფართო საქველმოქმედო პროგრამის მედიცინისთვის გამოყოფილი რგოლი ეს იყო. სახელმწიფოს მიერ დაარსებული ეს პირველი საავადმყოფო ექიმების აღმზრდელი სამედიცინო სკოლის ფუნქციასაც ასრულებდა და ამით ოსმალური ჯანდაცვის დაწესებულებების ნიმუში განსაზღვრა. ანკარის კატასტროფამდე მხოლოდ ორი წლით ადრე დასრულებული ეს ნაგებობა იილდირიმის ბურსის საიმპერიო დედაქალაქად გადაქცევის ჩანაფიქრის ერთ-ერთი უკანასკნელი რგოლია.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["თემურმა სივასი მიწასთან გაასწორა", "f4d79de6"], "d": ["აყ-ყოიუნლუელი ყარაიულუქ ოსმან ბეისა და ერზინჯანის ამირა მუთაჰარტენის გზამკვლევობით სივასისკენ დაძრულმა თემურმა ქალაქს თვრამეტი დღე ალყა შემოარტყა და, არავის სისხლის არდაღვრის დაპირებით ჩაბარების შემდეგ, დიდი ხოცვა-ჟლეტა მოაწყო; დამცველები ორმოებში ჩაყარეს და ცოცხლად დაამარხეს. ქალაქის, უპირველესად გალავნის, მნიშვნელოვანი ნაგებობები დაანგრიეს, სივასი დემოგრაფიულად გაცამტვერდა. ეს ანკარის ბრძოლამდე ორი წლით ადრე თემურის მიერ ოსმალურ მიწებზე მიყენებული პირველი დიდი დარტყმაა.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["იილდირიმ ბაიაზიდმა ერზინჯანი და ქემაჰი უკან დაიბრუნა", "7047ca08"], "d": ["თემურის სირიის ლაშქრობაში გასვლით ისარგებლა იილდირიმ ბაიაზიდმა და თემურის ვასალ ერზინჯანის ამირა მუთაჰარტენს ერზინჯანი და ქემაჰი წაართვა. მიუხედავად იმისა, რომ სივასის ნგრევაში არ ჩარეულა, ეს ნაბიჯი აღმოსავლეთ ანატოლიაში თემურის გავლენის სფეროს პირდაპირ გამოწვევას ნიშნავდა. ამის შემდეგ ორ მმართველს შორის ურთიერთობა გამოუსწორებელი გახდა.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["თემურის თავრიზიდან გაგზავნილი ულტიმატუმი — ოთხი პირობა", "3e1ac50e"], "d": ["თემურმა თავრიზიდან გაგზავნილი ელჩის პირით ოთხი პირობა გადასცა: ქემაჰის მუთაჰარტენისთვის დაბრუნება, ანატოლიელი ბეებისგან წართმეული მიწების მფლობელებისთვის დაბრუნება, ერთი ოსმალო უფლისწულის მძევლად გაგზავნა და ქუდისა და ქამრის ვასალობის ნიშნად მიღება, ასევე ყარა იუსუფის გადაცემა. ბაიაზიდმა არცერთი არ მიიღო; სახელმწიფო მოხელეთა დაჟინებისა და მუთაჰარტენის შუამავლობის მიუხედავად მოლაპარაკებები ჩაიშალა. თემური გადაწყვეტილი იყო, ჩინეთის ლაშქრობაში გასვლამდე ანატოლიის საკითხი საბოლოოდ დაეხურა.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["სარუხანიდები ხელახლა აღდგნენ — მანისა ოსმალეთს გამოეყო", "ac747b05"], "d": ["ანკარის მარცხიდან სამი კვირის შემდეგ თემურის მხარდაჭერით ორჰან ბეი საბეილიქოს სათავეში მოვიდა და სარუხანის მხარე კვლავ დამოუკიდებელი გახდა. მანისას ცენტრის მქონე მხარე 1390 წლის ოსმალური ანექსიიდან თორმეტი წლის შემდეგ რუკიდან გაქრა. ეს თემურის საბეილიქოების აღდგენის პოლიტიკის ერთ-ერთი პირველი განხორციელებაა, რომლის თარიღი ზუსტად არის ცნობილი.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["ამირ სულეიმანი სახელმწიფო ხაზინით რუმელიაში გაიქცა", "0a2b7363"], "d": ["ბურსის სახელმწიფო ხაზინის, არქივების, ოჯახისა და ძმების წამყვანმა ამირ სულეიმანმა გემლიქიდან გემით გიუზელჯეჰისარში (ანადოლუ ჰისარი) გადაცურა, იქიდან გალიპოლში ჩავიდა და ედირნეში თავისი მმართველობა გამოაცხადა. სახელმწიფო არქივისა და ხაზინის რუმელიაში გადატანა ოსმალური სიმძიმის ცენტრის ერთი თაობის განმავლობაში ბალკანეთში გადანაცვლების დასაწყისია. რუკაზე რუმელია ამ თარიღიდან ამირ სულეიმანის საკუთარი ფერით იხაზება.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["თემურმა ანატოლიის საბეილიქოები ხელახლა აღადგინა — თურქული ერთიანობა დაიშალა", "15187774"], "d": ["ანკარის გამარჯვების შემდეგ თემურმა მასთან მყოფი ბეები ძველ მიწებს დაუბრუნა. ყარამანიდ მეჰმედ და ალი ბეებს ყარამანის მხარე, კაისერთან, ქირშეჰირთან, სივრიჰისარსა და ბეიშეჰირთან ერთად; გერმიანიდ იაყუბ II ბეის ქუთაჰია და გერმიანის მხარე; ჯანდარიდ ისფენდიარ ბეის ქასთამონუ-სინოპის ხაზს გარდა ჩანქირი და ქალეჯიქი მიეცა. აიდინის, მენთეშესა და თექეს მხარეებიც ძველ დინასტიებს დაუბრუნდა. იილდირიმ ბაიაზიდის მიერ ათ წელიწადში აგებული ანატოლიის თურქული ერთიანობა ერთ ზაფხულში დაიშალა; რუკაზე ეს საბეილიქოები კვლავ საკუთარი ფერებით ჩნდება. იმავე პროცესში ხელი შეიცვალა სხვა დასახლებებმაც: აქსარაი, დენიზლი, ერეღლი (კონია), ერმენექი, ილღინი, ქარაფინარი, კაისერი, კონია, ქირშეჰირი, ქუთაჰია, სივრიჰისარი, სოქე.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["თემურმა იზმირი წმინდა იოანეს რაინდებს წაართვა", "66dd1dd4"], "d": ["ქუთაჰიას, დენიზლის, აიდინის, აიასულუქისა და თირეს გავლით დასავლეთისკენ ჩასულმა თემურმა ალყა შემოარტყა და აიღო სანაპირო იზმირი, რომელიც 1344 წლიდან ქრისტიანთა ხელში იყო. ციხის, რომელიც იილდირიმ ბაიაზიდმა წლების განმავლობაში ვერ აიღო, თემურმა მოკლე დროში დაიპყრო; მიმდებარე ციხეების ხელში ჩაგდების შემდეგ აიდინის მხარე ძველ მფლობელებს დაუტოვა და აღმოსავლეთით დაბრუნდა. ამის შემდეგ ქალაქი აიდინიდ ჯუნეიდ ბეის მმართველობაში შევიდა.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["ისა ჩელებიმ ბურსა ხელში ჩაიგდო — ანატოლიური წილი გაჩნდა", "955128c1"], "d": ["ანკარის მარცხის შემდეგ ყარესის მხარეში გაქცეულმა ისა ჩელებიმ, როცა თემური იზმირში იყო, ბურსა ხელში ჩაიგდო. თემურის ჯარისკაცების მიერ გაძარცულ და დამწვარ ძველ დედაქალაქში მან თავისი მმართველობა გამოაცხადა და საკუთარ სახელზე მონეტა მოჭრა; 1403 წლის იანვარში ანატოლიაში მას „თურქების მმართველად“ ცნობდნენ. რუკაზე მარმარილოს აზიური სანაპიროს გასწვრივ გაჭიმული ეს წილი ისა ჩელების საკუთარი ფერით ჩანს.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["თემურის ანატოლიიდან გასვლა", "93a98839"], "d": ["იილდირიმ ბაიაზიდის აქშეჰირში გარდაცვალების ამბის მიმღებმა თემურმა ანატოლიაში თავისი საქმე დასრულებულად ჩათვალა და აღმოსავლეთისკენ გაემართა. უკან მისდამი ერთგულების გამომცხადებელი საბეილიქოები და ერთმანეთს დაპირისპირებული ოსმალო უფლისწულები დარჩნენ; ზოგიერთი ქალაქი, მაგალითად სივასი, თემურის ვასალ ისეთი ამირების ხელში დატოვეს, როგორიც მეზიდ ბეი იყო. თემური ანატოლიაში აღარ დაბრუნებულა, მაგრამ მის მიერ შექმნილი დანაწევრებული წყობა ათი წელი გაგრძელდა.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["ამირ სულეიმანი ანატოლიაში გადავიდა: ბურსა მის ხელში გადავიდა", "9b27aa5f"], "d": ["ისა ჩელების მარცხის გამგონმა ამირ სულეიმანმა ჩანდარლი ალი-ფაშასთან ერთად ძლიერი ჯარით ანატოლიაში გადავიდა და ბურსა ხელში ჩაიგდო; 1404 წლის მარტის ჩანაწერები აჩვენებს, რომ შავი ზღვის ერეღლიც მის მმართველობაში იყო. მოკლე დროში როგორც რუმელიაზე, ისე ანატოლიის დიდ ნაწილზე გაბატონებული სულეიმანის წინაშე ჩელები მეჰმედმა წინააღმდეგობა ვერ გასწია. იმავე პროცესში ჩელები მეჰმედისგან ამირ სულეიმანზე გადასული სხვა დასახლებები: აქიაზი, ანადოლუ ჰისარი, აბსუ (ჰიპსუ), ადრანოსი (ორჰანელი), აქჰისარი (ფამუქოვა), არმუთლუ, აიდოსის ციხე, აივალიქი, ბალიქესირი, ბეჰრამქალე (ასოსი), ბერგამა, ბეიქოზი, ბიღა. რუკაზე ამ თარიღიდან ჩელები მეჰმედის მიერ ბურსის ხელახლა აღებამდე (1410) ორივე ნაპირი ერთ ფერში, ამირ სულეიმანის წილში ჩანს.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["იენიშეჰირის ველის ბრძოლა — ჩელები მეჰმედი ამასიაში გაიქცა", "f1568288"], "d": ["ბურსისა და ანკარის დამკარგველი ჩელები მეჰმედი იენიშეჰირის ველზე ამირ სულეიმანთან დამარცხდა, დასავლეთ ანატოლიაში ყველა შენაძენი დაკარგა და თოქათ-ამასიის ბაზაში გაიქცა. ამ მარცხის შემდეგ ის უშუალო შეტაკებას ერიდებოდა და ანატოლიის შიდა მხარეებში ავტორიტეტის განმტკიცებისკენ გადაერთო. ასე დაიწყო ინტერეგნუმის ყველაზე ხანგრძლივი ჩუმი ფაზა.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["ამირ სულეიმანმა ანკარა ჩელები მეჰმედს წაართვა", "d6a2acd6"], "d": ["თემურის ანატოლიიდან გასვლის შემდეგ ჩელები მეჰმედის ხელში დარჩენილ ანკარას 1406 წელს ამირ სულეიმანმა ალყა შემოარტყა. ციხის უფროსმა იაყუბ ბეიმ გარკვეულ ხანს გაუძლო, მაგრამ დიდი ვეზირის, ჩანდარლი ალი-ფაშას, ხრიკით ციხე სულეიმანს ჩააბარა. ამის შემდეგ ჩელები მეჰმედი ყარამანიდ მეჰმედ ბეის შეუთანხმდა და სულეიმანის წინააღმდეგ ამოქმედდა.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["ჩელები მეჰმედმა სივასი თემურიდ მეზიდ ბეის უკან წაართვა", "90079b0c"], "d": ["თემურის შემოსევის შემდეგ სივასის მმართველობა თემურის ვასალ მეზიდ ბეის ჰქონდა მიტოვებული. ამასიაში მყოფმა ჩელები მეჰმედმა ქალაქის ასაღებად თავისი სარდალი ბაიაზიდ-ფაშა გაგზავნა და სასტიკი წინააღმდეგობის შემდეგ სივასი მეორედ ოსმალთა დინასტიის ხელში გადავიდა. ამგვარად მეჰმედის წილმა ანკარის ბრძოლიდან ექვსი წლის შემდეგ აღმოსავლეთში ძველ საზღვარს მიაღწია.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["არტუქიდების დინასტიის დასასრული: მარდინის ყარა-ყოიუნლუებისთვის ჩაბარება", "15b06f33"], "d": ["1106 წლიდან მარდინში მმართველი და დინასტიის ყველაზე ხანგრძლივად არსებული შტო არტუქიდები აყ-ყოიუნლუს ზეწოლის წინაშე ვერ გაძლნენ. ქალაქის დაცვა რომ ვერ შეძლებდა, ამის მიმხვდარმა მელიქ აჰმედმა ყარა-ყოიუნლუს მმართველ ყარა იუსუფთან შეთანხმებით მარდინი მას ჩააბარა. ამგვარად სამ საუკუნეზე მეტხნიანი არტუქიდების ბატონობა დასრულდა; მარდინი და მისი მიდამოები ერთი საუკუნის შემდეგ ოსმალეთზე გადასვლამდე ყარა-ყოიუნლუ-აყ-ყოიუნლუს ბრძოლის ასპარეზი იყო.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["იამბოლის ბრძოლა — მუსა ჩელები ედირნეში შევიდა", "8f978408"], "d": ["ვლახეთის გავლით რუმელიაში გადასულმა მუსა ჩელებიმ ვლახური და სერბული მხარდაჭერით იამბოლში ამირ სულეიმანის ძალები დაამარცხა და ედირნეში შევიდა. ინტერეგნუმის ხანაში რუმელია პირველად გავიდა ამირ სულეიმანის ხელიდან. მაგრამ მისი ბატონობა მუდმივი არ აღმოჩნდა; ოთხი თვის შემდეგ კოსმიდიონთან დამარცხებული ის ბალკანეთის სიღრმეში უკან დაიხევდა.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["ინჯეღიზის ბრძოლა — ჩელები მეჰმედის პირველი მარცხი რუმელიაში", "3c35cd43"], "d": ["ბიზანტიის გემებით რუმელიაში გადასული ჩელები მეჰმედი ინჯეღიზთან მუსა ჩელების შეებრძოლა; მუსამ თავისი ხელქვეითი შვიდი ათასი იანიჩრით მეჰმედი დაამარცხა და მეჰმედი ანატოლიაში დაბრუნება აიძულეს. ამ მარცხმა მეჰმედი უშუალო ბრძოლის ნაცვლად რუმელიელი სასაზღვრო ბეებისა და სერბეთის დესპოტატის თავის მხარეზე მიზიდვის სტრატეგიისკენ მიმართა. ცხრა თვის შემდეგ ჩამურლუს გამარჯვების ნიადაგი ამ დიპლომატიით მომზადდა.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["კონიის ალყა და ყარამანიდებთან ხელშეკრულება — ჰამიდის მხარე, საიდის მხარე, ბეიშეჰირი, სეიდიშეჰირი და აქშეჰირი უკან დაიბრუნეს", "0996257e"], "d": ["ინტერეგნუმის ხანაში ოსმალურ მიწებზე თავდამსხმელი და ბურსის ალყაშემომრტყმელი და დამწვავი ყარამანიდების წინააღმდეგ ჩელები მეჰმედმა დიდი ლაშქრობა მოაწყო და 818 წლის მუჰარამში კონიას ალყა შემოარტყა. ყარამანიდი მეჰმედ II ბეი იძულებული გახდა ზავი ეთხოვა; ხელშეკრულების შედეგად ჰამიდის მხარე (ისფარტას მხარე) და საიდის მხარე კვლავ ოსმალურ მიწებს შეუერთდა, ბეიშეჰირი, სეიდიშეჰირი და აქშეჰირიც დააბრუნეს; 1402 წელს თემურის მიერ ყარამანიდებისთვის მიცემული სივრიჰისარიც ოსმალებს დაუბრუნდა. ანკარის ბრძოლით დაშლილი ანატოლიის ერთიანობის შეკეთების დასაწყისი ეს ლაშქრობა ჩელები მეჰმედის „მეორე დამაარსებლად“ მიჩნევის კონკრეტული საფუძვლებიდან ერთ-ერთია.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["იზმირის აიდინიდ ჯუნეიდ ბეისგან აღება", "2377ca51"], "d": ["ინტერეგნუმის განმავლობაში უფლისწულებს შორის მუდმივად მხარის შემცვლელი აიდინიდ ჯუნეიდ ბეის ცენტრი იზმირი ათდღიანი ალყის შემდეგ ჩელები მეჰმედმა აიღო; ჯუნეიდი შეიწყალეს და ნიკოპოლის სანჯაყბეობაზე გაგზავნეს. ამგვარად 1402 წელს თემურის მიერ აიდინიდებისთვის დაბრუნებული ქალაქი ცამეტი წლის შემდეგ ოსმალეთს დაუბრუნდა. 1422 წელს ჯუნეიდი ქალაქს ხელახლა ჩაიგდებს ხელში; საკითხი მხოლოდ 1424-1426 წლებში მურად II-ის მიერ დაიხურება.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["თორლაქ ქემალის სიკვდილით დასჯა — სარუხანი საბოლოოდ ოსმალთა", "8a09dbf1"], "d": ["შეიხ ბედრედინის მოძრაობის დასავლეთ ანატოლიური ფრთის წარმმართველი თორლაქ ქემალი მანისის მხარეში დაამარცხეს და სიკვდილით დასაჯეს. ამ თარიღის შემდეგ სარუხანის მხარე საბოლოოდ ოსმალურ კონტროლში მოექცა და 1402 წელს თემურის აღდგენილი საბეილიქო ისტორიას ჩაბარდა. ამგვარად ინტერეგნუმის ხანის დასავლეთ ანატოლიაში უკანასკნელი პოლიტიკური ნაშთები გაიწმინდა.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["ვლორას, ბერატისა და კანინას აღება", "1e1949b8"], "d": ["ოსმალებმა 1417 წელს ადრიატიკის სანაპიროზე მდებარე ვლორა, ქვეყნის შიდა ნაწილში მდებარე ქალაქ ბერატთან და კანინას ციხესთან ერთად, თავიანთ ბატონობაში მოაქციეს. ერთი წლის შემდეგ ვენეციის მიერ ქალაქის დაბრუნების მცდელობა წარუმატებელი აღმოჩნდა; აქ სანჯაყის ორგანიზაცია შეიქმნა და ოსმალური ხელისუფლება მუდმივი გახდა. ვლორას აღებამ ოსმალეთი პირველად აქცია ადრიატიკაზე უშუალოდ პორტის მფლობელად და იტალიის წინააღმდეგ ზღვისიქითა ტრამპლინი მისცა.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["ცენტრალური ანატოლიის უკან დაბრუნება: კაისერი და ქირშეჰირი", "204eacb3"], "d": ["ინტერეგნუმის ხანაში ყარამანიდების ხელში გადასული ცენტრალური ანატოლიის ქალაქები ჩელები მეჰმედის სახელმწიფოს ხელახლა შეკრების ლაშქრობებისას ოსმალურ მმართველობას დაუბრუნდა. კაისერისა და ქირშეჰირის შემოერთებით ანკარის ბრძოლაში დაკარგული ყიზილირმაქის აუზი დიდწილად დაბრუნდა. ეს წინსვლა ოთხი წლის წინანდელი კონიის ალყით დაწყებული აღმოსავლეთისკენ მიმართვის პოლიტიკის გაგრძელებაა.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["მამლუქებმა კაისერი დულყადირიდ ნასირუდდინ მუჰამადს მისცეს", "aad4b00c"], "d": ["ყარამანიდ მეჰმედ ბეის წინააღმდეგ ლაშქრობაში გასულმა მამლუქთა ჯარმა კაისერი დაიკავა; მამლუქმა სარდალმა ქალაქი და მისი მიდამოები დულყადირიდ ნასირუდდინ მუჰამადს დაუტოვა და საკუთარ ქვეყანაში დაბრუნდა.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["მეჰმედ I-ის გარდაცვალება და მურად II-ის გამეფება", "98acac77"], "d": ["მეჰმედ I, რომელმაც ინტერრეგნუმის ხანა დაასრულა და ოსმალეთის ქვეყანა ხელახლა ერთ ხელში გააერთიანა, 1421 წლის 25 ივნისს ედირნეში გარდაიცვალა, მისი ვაჟი მურადი კი ბურსაში ავიდა ტახტზე. გარდაცვალებამდე ბიზანტიასთან მიღწეული შეთანხმებით, მისი უმცროსი ვაჟები მძევლებად იმპერატორთან უნდა გაეგზავნათ, იმპერატორი კი ხელში მყოფ ტახტის პრეტენდენტ მუსტაფა ჩელების არ გაათავისუფლებდა; მურად II-მ ძმების იმპერატორთან გაგზავნაზე უარი თქვა.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["თექეიდების საბოლოო ლიკვიდაცია: ანტალიის აღება", "e65565b2"], "d": ["ანკარის ბრძოლის შემდეგ თემურის აღდგენით ხელახლა შექმნილი თექეიდების საბეილიქო ჰამზა ბეის სარდლობით ოსმალური ძალების მიერ ანტალიის ალყით დასრულდა; საბეილიქოს უკანასკნელი მნიშვნელოვანი კაცი ოსმან ჩელები გაანადგურეს. ამგვარად ხმელთაშუა ზღვის სანაპიროზე თექეს მხარე ოცდაერთწლიანი განშორების შემდეგ საბოლოოდ ოსმალეთს შეუერთდა. საბეილიქო, როგორც ჰამიდიდებისგან გამოყოფილი შტო, 1321 წლიდან ანტალიაში მმართველობდა.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["ტურაჰან ბეის მორეას ლაშქრობა და ჰექსამილიონის გალავნის დანგრევა", "c6c2706d"], "d": ["ბიზანტიის მიერ ტახტის მეტოქე პრეტენდენტის, მუსტაფა ჩელების, მხარდაჭერის გამო მურად II-მ ტურაჰან ბეი მორეას წინააღმდეგ გაგზავნა. ტურაჰან ბეიმ კორინთის ყელის თავიდან ბოლომდე ჩამკეტავი ჰექსამილიონის კედელი დაანგრია, ნახევარკუნძულში შევიდა და დიდი ნგრევა გამოიწვია. მშვიდობა კედლის აღარ აშენებისა და ყოველწლიური გადასახადის გადახდის პირობით დამყარდა; ამგვარად მორეას დესპოტატი სამხედრო თვალსაზრისით დაუცველი დარჩა და 1460 წლის საბოლოო დაპყრობის ნიადაგი ოცდაჩვიდმეტი წლით ადრე მომზადდა.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["ათონის მონასტრების ოსმალთა მფარველობაში შესვლა", "562de5ea"], "d": ["სალონიკის ალყის წლებში ხალკიდიკის აღმოსავლეთ თითზე მდებარე ათონის სამონასტრო რესპუბლიკამ მურად II-ს მიმართა, მფარველობა სთხოვა და ოსმალთა ბატონობა აღიარა. ბერების საკუთრებისა და ღვთისმსახურების უფლებები უზრუნველყოფილ იქნა; მონასტრებს გადასახადის სანაცვლოდ შიდა საქმეებში თავისუფლება დარჩა. ეს წყობა ოსმალეთის მართლმადიდებლურ ინსტიტუტებთან დამყარებული მფარველობითი ურთიერთობის ყველაზე ხანგრძლივი ნიმუში გახდა და ხუთი საუკუნე გაგრძელდა.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["თაჯედდინიდების საბეილიქოს ანექსია: ნიქსარი", "370ffd47"], "d": ["ამასიის ბეგლარბეგის, იორგუჩ-ფაშას, ზეწოლის გამო თაჯედდინიდმა ჰუსამედდინ ჰასან ბეიმ თავისი ქვეყნის, რომლის ცენტრი ნიქსარი იყო, გასაღებები 830 (1427) წელს ჩააბარა; მას რუმელიაში ერთი სანჯაყი მისცეს. ამგვარად XIV საუკუნის მეორე ნახევარში დაარსებული და ზოგჯერ ქელქითამდე, ამასიამდე, სამსუნამდე, ორდუმდე და გირესუნამდე გაჭიმული საზღვრების მქონე საბეილიქო დასრულდა. იმავე წელს ჰაჯი ემირიდების კუთვნილი მიწებიც აღიწერა და ჯანიქის სანჯაყს დაუკავშირდა; შუა შავიზღვისპირეთში საბეილიქოების ხანა დაიხურა.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["ბელგრადის უნგრეთისთვის დათმობა — ტატას ხელშეკრულება", "62481183"], "d": ["სერბი დესპოტის სტეფან ლაზარევიჩის გარდაცვალების შემდეგ უნგრეთის მეფე სიგიზმუნდსა და მის მემკვიდრე გეორგ ბრანკოვიჩს შორის დადებული ტატას ხელშეკრულების თანახმად ბელგრადის ციხე უნგრეთს გადაეცა. დუნაისა და სავას შესართავთან მდგარი ციხე მანამდე სერბული სადესპოტოს ხელში იყო და ოსმალებისთვის ცენტრალურ ევროპაში გასასვლელი კარის საკეტი იყო. ამ გადაცემამ ბელგრადი ასი წლის განმავლობაში ოსმალთა წინსვლის წინაშე ყველაზე მტკიცე დაბრკოლებად აქცია: 1440 და 1456 წლების ალყები წარუმატებელი იქნებოდა და ციხე მხოლოდ 1521 წელს დაეცემოდა.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["მარდინი ყარა-ყოიუნლუელი მცველისგან აყ-ყოიუნლუელ ყარაიულუქ ოსმან ბეის გადაეცა", "d82bc97f"], "d": ["1409 წელს ყარა იუსუფის აღებულ მარდინს ყარა-ყოიუნლუელები ვალების მეშვეობით მართავდნენ; ციხისთავად დატოვებულმა ამირა ნასირმა ქალაქი 835 (1432) წელს აყ-ყოიუნლუელ ყარაიულუქ ოსმან ბეის ჩააბარა. აყ-ყოიუნლუს მმართველობა XVI საუკუნის დასაწყისამდე გაგრძელდა.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["ყარამანიდებმა კაისერი დულყადირიდებს წაართვეს", "2b09e8e8"], "d": ["ყარამანის ბეიმ დულყადირიდებზე მოპოვებული გამარჯვებით კაისერი, ურგიუფი, დეველის ყარაჰისარი და უჩჰისარი თავის ქვეყანას შეუერთა.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["ბუჩუქთეფეს ინციდენტი — იანიჩართა პირველი აჯანყება და მურად II-ის ტახტზე დაბრუნება", "6388dda1"], "d": ["ედირნეში ატეხილი ბუჩუქთეფეს ინციდენტი, ისტორიაში ცნობილი იანიჩართა პირველი აჯანყება, ჯამაგირის ნახევარი ახჩით გაზრდის მოთხოვნით დაიწყო და ახალგაზრდა მეჰმედ II-ის ტახტიდან ჩამოგდებით დასრულდა. მურად II-მ 850 წლის 8 საფარს მანისადან სასწრაფოდ გამოეშურა და მეორე მმართველობა დაიწყო. ეს მოვლენა პირველი ნიშანი იყო იმისა, რომ ყაფუყულუს ოჯაღი უკვე ტახტზე სიტყვის მქონე ძალად იქცა, და ფატიჰის იანიჩართა მიმართ მთელი სიცოცხლის განმავლობაში გაგრძელებული სიფრთხილე ჩამოაყალიბა.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["ეპირის სანაპიროს შემოერთება: არტა და პრევეზა", "796f7ecf"], "d": ["1430 წელს იოანინას ჩაბარებიდან ცხრამეტი წლის შემდეგ ეპირის დესპოტატის სანაპირო ნაწილში მდებარე არტა და პრევეზაც ოსმალურ მმართველობაში შევიდა. ამგვარად იონიის ზღვაზე გამავალი ამბრაკიის ყურე კონტროლში მოექცა და იოანინას საზღვაო კავშირი დასრულდა. პრევეზა იმ ყურის საკვანძო წერტილია, რომელიც ოთხმოცდაათი წლის შემდეგ ბარბაროსას ისტორიაში შესულ გამარჯვებას სახელს მისცემდა.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["მურად II-ის გარდაცვალება და მეჰმედ II-ის მეორედ ტახტზე ასვლა", "8f8256ad"], "d": ["ვაჟის ქორწილის შემდეგ დაავადებული მურად II 855 წლის 1 მუჰარამს (1451 წლის 3 თებერვალი) ედირნეში გარდაიცვალა. ცხრამეტი წლის მეჰმედ II 855 წლის 16 მუჰარამს (1451 წლის 18 თებერვალი) მეორედ ავიდა ოსმალეთის ტახტზე — ამჯერად სამუდამოდ. ხუთი წლის წინ ბუჩუქთეფესთან ტახტიდან ჩამოგდებული ახალგაზრდა მმართველის დაბრუნება იმ მმართველობის დასაწყისია, რომელიც ორი წლის შემდეგ სტამბოლის აღებით დაგვირგვინდებოდა და ოსმალურ საბეილიქოს მსოფლიო იმპერიად აქცევდა.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["ოსმალურ-ყირიმული გაერთიანებული ძალების კაფის პირველი ალყა", "e346d163"], "d": ["1454 წლის ივნისში ფატიჰ სულთან მეჰმედთან შეთანხმებულმა ყირიმის ხან ჰაჯი გირაიმ 7000 მხედრით კაფას ხმელეთიდან ალყა შემოარტყა; ორმოცდაათ-სამოცი ნიჩბიანი გალერისგან შემდგარი ოსმალური ფლოტიც ღია ზღვაში განლაგდა. გენუელთა კაფამ ალყა ხარკის გადახდით მოახსნევინა და საბოლოო აღება ოცდაერთი წლის შემდეგ, 1475 წელს, დარჩა. ეს პირველი ერთობლივი ოპერაცია ოსმალურ-ყირიმული სამხედრო თანამშრომლობის პირველი ნიმუში იყო, რომელიც მომავალში კაფის საბოლოო აღებისას განმეორდებოდა.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["ჩრდილო ეგეოსის კუნძულების აღება: ბოზჯაადა (ტენედოსი), იმროზი და თასოსი", "76575895"], "d": ["სტამბოლის აღებისთანავე ფატიჰ სულთან მეჰმედი ახალი დედაქალაქის საზღვაო გზის უზრუნველსაყოფად დარდანელის სრუტის ეგეოსისკენ გამავალ შესართავთან მდებარე კუნძულებს მიმართა; ბოზჯაადა და იმროზი ბიზანტიისგან, თასოსი კი გენუური წარმოშობის გატილუზიოს ოჯახისგან აიღო. სრუტის ორივე ნაპირის ჩამკეტი ეს კუნძულები ამიერიდან სტამბოლის მომარაგებისა და თავდაცვის ხაზის პირველი რგოლი გახდა. პაპობისა და ვენეციის ფლოტების ჩარევით ბატონობა გარკვეული დრო ხელიდან ხელში გადადიოდა და მხოლოდ 1459 წელს დამკვიდრდა.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["კოსოვოს დაპყრობა: პრიშტინისა და იენიპაზარის აღება", "d7ed2345"], "d": ["სერბეთის დესპოტატის წინააღმდეგ დაძრულმა ოსმალურმა ჯარმა კოსოვოს ველზე მდებარე პრიშტინა და რაშკის მხარის ცენტრი იენიპაზარი ხელში ჩაიგდო; იმავე ოპერაციისას ვერცხლის საბადოებით ცნობილი ნოვო-ბრდოც აიღეს. ამგვარად სერბეთის სამხრეთ ნახევარი უშუალო ოსმალურ მმართველობას დაუკავშირდა და სმედერევოში მყოფი დესპოტატი ცენტრალური მიწებისგან მოწყდა. ეს დაპყრობა ოთხი წლის შემდეგ სერბეთის სრული ანექსიისკენ მიმავალი გზის გადამწყვეტი ნაბიჯი იყო.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["პეჩი (İpek) ოსმალურ მმართველობაში შევიდა — დუკაგინის სანჯაყის ერთ-ერთი ცენტრი", "19511588"], "d": ["1455 წელს ფატიჰ სულთან მეჰმედის სერბეთის ლაშქრობისთანავე სერბეთის საპატრიარქოს ცენტრი პეჩი ოსმალურ მმართველობაში გადავიდა; ოსმალურ წყაროებში ამ გადასვლის შესახებ ჩანაწერი არ არის. ქალაქი დროთა განმავლობაში პატარა მუსლიმურ ქალაქად იქცა და დუკაგინის სანჯაყში სანჯაყბეის ერთ-ერთ რეზიდენციად გახდა.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["ენოსისა და სამოთრაკის აღება — დასავლეთ თრაკიის სანაპიროს დასრულება", "106e723b"], "d": ["მარიცას ზღვასთან შესართავზე მდებარე ენოსი აიღეს გენუური წარმოშობის გატილუზიოს ოჯახისგან, რომელიც მას ოთხმოცი წელი ფლობდა; აქ დაქვემდებარებული კუნძული სამოთრაკიც იმავე ოპერაციისას ხელში ჩაიგდეს. ენოსის დაცემით დასავლეთ თრაკიის სანაპირო ზოლი სალონიკიდან გალიპოლამდე უწყვეტ ოსმალურ მიწად იქცა. გატილუზიოს ოჯახის ხელში მხოლოდ ლესბოსი დარჩა; ისიც ექვსი წლის შემდეგ აიღებოდა.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["ბელგრადის ალყის წარუმატებლობა", "3d53a604"], "d": ["ფატიჰ სულთან მეჰმედმა სტამბოლის აღების შემდეგ ცენტრალური ევროპის საკეტად მიჩნეულ ბელგრადს ალყა შემოარტყა; მაგრამ იან ჰუნიადის მიერ დუნაიდან მოყვანილმა დამხმარე ძალამ და ჯვაროსანთა მქადაგებლის, კაპისტრანოს, შეკრებილმა მოხალისეებმა ციხის დაცემა თავიდან აიცილეს. ფადიშაჰი, ალყის წინ ნაჩვენები პირადი გმირობის მიუხედავად, დაიჭრა და იძულებული გახდა უკან დაეხია. ეს წარუმატებლობა უნგრეთის საზღვარს სამოცდახუთი წლის განმავლობაში ოსმალთა წინსვლისთვის ჩაკეტავდა; ბელგრადის აღება მხოლოდ 1521 წელს კანუნიმ შეძლებდა.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["ჩრდილოეთ მორეას აღება: ბალიაბადრა (პატრა)", "c08a8509"], "d": ["სერბეთის ანექსიის იმავე წლებში მორეას დესპოტატისკენ მიმართულმა ფატიჰ სულთან მეჰმედის ძალებმა ნახევარკუნძულის ჩრდილო-დასავლეთით მდებარე ბალიაბადრა ხელში ჩაიგდეს. კორინთის ყურის შესასვლელის მფლობელი ეს პორტი მორეაში ხმელეთით შესვლის საკეტია; მისმა აღებამ ორი წლის შემდეგ საბოლოო დაპყრობის ნიადაგი მოამზადა. ქალაქი ბიზანტიელი დესპოტებისთვის ლათინურ სამყაროსთან კავშირის უკანასკნელი დიდი ნავმისადგომი იყო.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["დასავლეთ შავიზღვისპირეთის სანაპიროს აღება: ამასრა", "f43608fc"], "d": ["დასავლეთ შავ ზღვაზე გენუელთა გამაგრებული კოლონია ამასრა ფატიჰ სულთან მეჰმედის ფლოტისა და სახმელეთო ძალების ერთობლივი ზეწოლით წინააღმდეგობის გარეშე დანებდა. ბართინ-ზონგულდაქის სანაპიროზე მდებარე ეს პორტი ჯანდარიდებისა და ოსმალურ მიწებს შორის ლათინურ ჯიბედ იდგა; მისი აღებით სანაპირო გამთლიანდა. ამასრას დაცემა ორი წლის შემდეგ (1461) სინოპისა და ტრაპიზონისკენ მიმართული დიდი შავიზღვისპირული ლაშქრობის პირველი ნაბიჯია.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["ლესბოსის კუნძულის დაპყრობა", "fe17aeba"], "d": ["ფატიჰ სულთან მეჰმედის სარდლობით ოსმალურმა ჯარმა 866 წლის ზულ-ჰიჯაში ლესბოსი მოკლე, მაგრამ სასტიკი ალყის შემდეგ გენუური წარმოშობის გატილუზიოს ოჯახს წაართვა და შეიერთა. ჩრდილო ეგეოსის უდიდესი კუნძულის დაცემამ გენუელთა მხარეში უკანასკნელი მნიშვნელოვანი ბაზაც ლიკვიდირა. კუნძული, ანატოლიის სანაპიროსთან სიახლოვის წყალობით, ამიერიდან ოსმალური ფლოტის წინა საგუშაგოს ფუნქციას შეასრულებდა, ამავე დროს კი, როგორც ბარბაროსა ძმების აღზრდის ადგილი, ზღვაოსნობის ისტორიაში შევიდოდა.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["თექვსმეტწლიანი ოსმალურ-ვენეციური ომის დაწყება", "563ddb68"], "d": ["ვენეციელებმა მორეასა და ეგეოსში ოსმალთა წინსვლის შესაჩერებლად ყარამანისა და აყ-ყოიუნლუს მმართველებთან კავშირი დადეს და 1463 წელს ომი დაიწყეს. აღმოსავლეთში უზუნ ჰასანთან, დასავლეთში ვენეციასთან და შუაში ყარამანთან შექმნილმა ამ ალყის სტრატეგიამ ფატიჰი აიძულა, ერთდროულად რამდენიმე ფრონტზე ებრძოლა. თექვსმეტი წლის ბრძოლა ოთლუქბელიდან ალბანეთის ლაშქრობებამდე ხანის ყველა დიდ ოპერაციას მოიცავდა და მხოლოდ 1479 წლის სტამბოლის ზავით დასრულდებოდა.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["ჰერცეგოვინის დიდი ნაწილის დაპყრობა: ტრებინიე და მოსტარი", "f54c0100"], "d": ["ბოსნიისგან ცალკე მმართველობის დამაარსებელი ჰერცეგოვინის ჰერცოგ სტიეპან ვუკჩიჩ-კოსაჩას მიწები ბოსნიის სამეფოს დამხობიდან სამი წლის შემდეგ დიდწილად ოსმალურ მმართველობაში გადავიდა: სამხრეთით ტრებინიე 1466 წელს „თითქმის მთელ ჰერცეგოვინის მხარესთან ერთად“ ჩაიგდეს ხელში. ნერეტვას ხიდის ორი პატარა ციხის ირგვლივ დაარსებული მოსტარიც, სავარაუდოდ, 1466-1468 წლებში ჰერცეგოვინის ცენტრის, ბლაგაის, დაპყრობამდე ცოტა ხნით ადრე იქნა აღებული; 1468-1469 წლებით დათარიღებულ ბოსნიის შემაჯამებელ აღწერაში ის „ქოფრულუ ჰისარის“ სახელით არის ჩაწერილი. საჰერცოგოს დარჩენილი ციხეებით ჰერცეგოვინის დაპყრობა 1483 წელს დასრულდა.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["ალბანეთის მეორე ლაშქრობა — ფატიჰის პირადი ლაშქრობა სკანდერბეგის წინააღმდეგ", "9cdd2bfa"], "d": ["სკანდერბეგის მეოთხედ საუკუნეზე მეტხნიანი წინააღმდეგობის გასატეხად ფატიჰ სულთან მეჰმედმა 1466-1467 წლებში პირადი სარდლობით დიდი ლაშქრობები მოაწყო. ოსმალურმა ჯარმა კრუიას (აქჩაჰისარს) ალყა შემოარტყა და მხარის კონტროლში მოსაქცევად ელბასანის ციხე ააშენა. ლაშქრობამ, მართალია, ალბანურ წინააღმდეგობას ხერხემალი გადაუტეხა, მაგრამ ციხის აღება ვერ მოახერხა; მხარის სრული დამორჩილება სკანდერბეგის სიკვდილის შემდეგ ათ წელს გაგრძელდებოდა.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["აყ-ყოიუნლუს ავანგარდულმა ძალებმა ბინგოლის ციხე ყარა-ყოიუნლუს წაართვეს", "51b94cbc"], "d": ["ჯეჰან-შაჰის უზუნ ჰასანის წინააღმდეგ ლაშქრობის ბოლო კვირებში აყ-ყოიუნლუს ავანგარდულმა ძალებმა ბინგოლის ციხე დაიპყრეს; 1467 წლის 10 ნოემბერს ჯეჰან-შაჰის მოკვლით რეგიონში ყარა-ყოიუნლუს ბატონობა დასრულდა.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["ყარა-ყოიუნლუს სახელმწიფოს დაცემა: ჯაჰან შაჰის მკვლელობა", "30bc6358"], "d": ["უზუნ ჰასანის წინააღმდეგ დაწყებული ლაშქრობიდან ზამთრის დადგომის გამო უკან დაბრუნებისას თავდასხმაში მოქცეული ყარა-ყოიუნლუს მმართველი ჯაჰან შაჰი ბინგოლსა და ქიღის შორის გაქცევისას მოკლეს. ამ დარტყმის შემდეგ სახელმწიფომ ვერ აღიდგინა ძალა; უკანასკნელი მმართველი ჰასან ალი 1469 წელს უზუნ ჰასანის ვაჟმა უღურლუ მეჰმედმა ტყვედ აიყვანა და მოკლა. ამგვარად აღმოსავლეთ ანატოლიაში, აზერბაიჯანსა და ერაყში დაახლოებით ერთი საუკუნის განმავლობაში მმართველი ყარა-ყოიუნლუს ბატონობა აყ-ყოიუნლუებს გადაეცა.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["სკანდერბეგის გარდაცვალება — ალბანური წინააღმდეგობის ჩაქრობა", "9158c35f"], "d": ["ოსმალურ სასახლეში აღზრდილი, 1444 წელს იზლადის მარცხის შემდეგ აჯანყებული და მეოთხედ საუკუნეზე მეტხანს ალბანეთში წინააღმდეგობის გამწევი სკანდერბეგი ლეჟეში, სადაც თავი შეაფარა, გარდაიცვალა. მურად II-ისა და ფატიჰის ხანაში ოსმალური ჯარების მრავალჯერ შემაყოვნებელმა ამ წინააღმდეგობამ მისი სიკვდილით ცენტრალური ხელმძღვანელობა დაკარგა. პაპობისა და ვენეციის მიერ გამოკვებილი ალბანური ფრონტის ჩამონგრევით ოსმალებმა ათ წელიწადში კრუია და შკოდრა აიღეს და მხარე საბოლოოდ თავიანთ მიწებს შეუერთეს.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["ქაისერიში ოსმალური მმართველობა დამყარდა: გედიქ აჰმედ-ფაშამ ყარამანიდებს ბოლო მოუღო", "33cf35fc"], "d": ["1474 წელს გედიქ აჰმედ-ფაშამ ყარამანიდებს ბოლო მოუღო, რის შედეგადაც ქაისერი ოსმალური მმართველობის ქვეშ მოექცა; XV საუკუნის განმავლობაში ქალაქი დულკადირიდებს, რამაზანიდებსა და ყარამანიდებს შორის გადადიოდა ხელიდან ხელში. ოსმალური მმართველობით ქაისერი ყარამანის საბეგლარბეგოს სანჯაყის ცენტრი გახდა.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["სამოსი მიატოვეს: გენუური (მაონას) საკუთრება დასრულდა", "5bdc380c"], "d": ["TDV-ის თანახმად, 1475 წლის შემდეგ კუნძული მიტოვებული იყო; 1479 წელს სულთანმა მეჰმედ ფათიჰმა კუნძული დაიპყრო და ციხე ააგებინა.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["რაკოვას (ვასლუის) მარცხი მოლდოვაში", "a1a74bf7"], "d": ["მოლდოვის ვოევოდამ შტეფან დიდმა (Ștefan cel Mare) რუმელიის ბეგლარბეგის, ჰადიმ სულეიმან-ფაშას, სარდლობით ოსმალური ძალები ჭაობიან ადგილზე შეიტყუა და მძიმედ დაამარცხა. ფატიჰის ხანის ერთ-ერთმა ყველაზე მძიმე სახმელეთო მარცხმა ევროპაში დიდი გამოხმაურება გამოიწვია და შტეფანს ჯვაროსნულ სამყაროში სახელი მოუტანა. ფადიშაჰი მომდევნო წელს საპასუხოდ პირადად გავიდოდა ლაშქრობაში.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["აქდერეს (Valea Albă) გამარჯვება — მოლდოვის ლაშქრობა", "45a66791"], "d": ["ერთი წლის წინანდელი რაკოვას მარცხისთვის შურისძიების მიზნით პირადად ლაშქრობაში გასულმა ფატიჰ სულთან მეჰმედმა ოსმალური ჯარით მოლდოვური ნაწილები აქდერეს ადგილზე დიდ კატასტროფამდე მიიყვანა და სამთავროს ცენტრ სუჩავაში შევიდა. მაგრამ ციხეები ვერ აიღეს; სურსათის სიმცირის, იანიჩართა შორის გაჩენილი შავი ჭირისა და უნგრული მზადების გამო ჯარი იძულებული გახდა უკან დაეხია. მოლდოვის საბოლოო დამორჩილება მხოლოდ მომდევნო წლებში და 1484 წელს ქილიისა და აქქერმანის აღებით შეიძლებოდა.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["კრუიას (აქჩაჰისარის) აღება და ალბანეთის დაპყრობის დასრულება", "559a79b4"], "d": ["სკანდერბეგის სიკვდილიდან ათი წლის შემდეგ, 1478 წელს, კრუიას, დრივასტოს, ლეჟესა და ჟაბლიაკის ხელში ჩაგდებით ალბანეთის დაპყრობა დიდწილად დასრულდა. წლების განმავლობაში ოსმალური ჯარებისთვის წინააღმდეგობის გამწევი და სკანდერბეგის წინააღმდეგობის სიმბოლო კრუიას ციხის დაცემა მხარეში ვენეციურ-ალბანური კავშირის დასასრულს ნიშნავდა. დარჩენილი შკოდრა კი მომდევნო წელს ხელმოსაწერი სტამბოლის ზავით ოსმალეთს დაეთმობოდა.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["ტამანის ნახევარკუნძულის შემოერთება", "4ef917b8"], "d": ["1475 წელს კაფასა და ქერჩის აღების შემდეგ ფატიჰ სულთან მეჰმედის მიერ კავკასიის სანაპიროებზე გაგზავნილმა ფლოტმა ანაპასა და ქოფასთან ერთად ტამანის ნახევარკუნძულზე გენუური მატრეგა (თმუტარაკანი) დაიპყრო. ამგვარად სრუტის ორივე ნაპირი კონტროლში მოექცა და აზოვის ზღვაში შესასვლელი სრულად საკონტროლებელი გახდა. ტამანი, როგორც ჩრდილოეთ კავკასიისკენ გახსნილი კარი, კაფის სანჯაყს დაუკავშირდა.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["სამოსის ოსმალური მმართველობის ქვეშ გადასვლა (ფათიჰი)", "c877bc14"], "d": ["სულთანმა მეჰმედ ფათიჰმა სამოსი დაიპყრო, ციხე ააგებინა და აღწერა ხელახლა მოაწესრიგა; ციხე ბაიაზიდ II-მ 1483 წელს პოლიტიკური მიზეზებით დაანგრევინა.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["როდოსის ალყის წარუმატებლობა", "35a85c28"], "d": ["ფატიჰ სულთან მეჰმედის ბრძანებით მესიჰ-ფაშას სარდლობით 160 ერთეულისგან შემდგარმა ფლოტმა 885 (1480) წლის გაზაფხულზე როდოსს ალყა შემოარტყა და კუნძული სამი თვე ბლოკადაში დარჩა. დიდი მაგისტრის, პიერ დ'ობიუსონის, წინამძღოლობით წმინდა იოანეს რაინდებმა მძიმე დანაკარგების მიუხედავად სასტიკი წინააღმდეგობა გასწიეს; 885 წლის 20 ჯუმადა ალ-ულას უკანასკნელი დიდი იერიშიც რომ მოიგერიეს, ფლოტმა 3 აგვისტოს უკან დაიხია. ამ წარუმატებლობის შემდეგ ქალაქის გალავანი თავიდან განაახლეს და ევროპის უძლიერეს სიმაგრედ აქციეს; კუნძულის აღება მხოლოდ 1522 წელს კანუნიმ შეძლო.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["ნიკარია (იკარია) როდოსის წმინდა იოანეს რაინდების მმართველობაში გადავიდა", "5cbc2669"], "d": ["სამოსსა და ქიოსს შორის მდებარე ნიკარია 1481 წლიდან 1521 წლამდე როდოსის წმინდა იოანეს რაინდების მმართველობაში იყო.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["იენიშეჰირის ბრძოლა — ჯემ სულთნის მარცხი", "c35abee2"], "d": ["ფატიჰის გარდაცვალების შემდეგ ტახტისთვის ამოქმედებული ორი ძმა იენიშეჰირის ველზე ერთმანეთს დაუპირისპირდა და ჯემ სულთანმა გადამწყვეტი მარცხი განიცადა. ბურსაში თვრამეტი დღის მმართველი და თავის სახელზე ხუთბას წამკითხავი უფლისწული მარცხის შემდეგ იძულებული გახდა ჯერ კონიას, იქიდან კი მამლუქთა მიწებს შეეფარებინა თავი. იენიშეჰირმა ოსმალეთის ისტორიაში ყველაზე ხანგრძლივი დინასტიური კრიზისი დაიწყო: ჯემის საკითხი თოთხმეტი წლის განმავლობაში ოსმალეთის საგარეო პოლიტიკას ევროპის წინაშე პარალიზებას უქმნიდა.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["ჰერცეგოვინის ანექსია", "bf247891"], "d": ["1463 წელს ბოსნიის აღების შემდეგ ფეხზე დარჩენილი ჰერცეგოვინის საჰერცოგოს მიწები ეტაპობრივად ოსმალურ მმართველობაში გადავიდა: ტრებინიე და მოსტარი 1466 წელს იქნა აღებული, ჰერცეგოვინის სანჯაყი 1470 წელს შეიქმნა, საჰერცოგოს ადრიატიკის სანაპიროზე უკანასკნელი მიწებიც ჰერცეგ-ნოვისთან ერთად 1482 წლის დასაწყისში დაიპყრეს და სანჯაყს შეუერთეს. ამგვარად ადრიატიკის უკან მდებარე მთიანი მხარე მთლიანად ოსმალური გახდა და ბოსნია და ჰერცეგოვინა ერთ ადმინისტრაციულ გეოგრაფიად იქცა. უკანასკნელი ჰერცოგის ოსმალურ სასახლეში შესული ვაჟი არის ჰერსეკზადე აჰმედ-ფაშა, რომელიც მომავალში დიდი ვეზირობამდე ამაღლდა.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["ზაკინთოსის (Zakynthos) ყოველწლიური ხარკის სანაცვლოდ ვენეციისთვის დათმობა", "268a691a"], "d": ["ფათიჰის ეპოქის ბოლოს ტოკოს ოჯახისგან წართმეული იონიის კუნძულებიდან ზაკინთოსი ჯემ სულთნის საქმით დაკავებულმა ახალმა ფადიშაჰმა დასავლეთში სიმშვიდის ძიებისას ვენეციას დაუთმო. კუნძული ოსმალური სუზერენიტეტის აღიარებელ და ყოველწლიურად ხუთასი დუკატის ხარკის გადამხდელ ვენეციურ მმართველობას გადაეცა. ამგვარად, იონიის ზღვაში ოსმალთა პირდაპირი მმართველობა მხოლოდ ლეფკადაზე (აია-მავრაზე) დარჩა.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["ჯემ სულთნის როდოსზე თავის შეფარება", "2228d6da"], "d": ["კონიის ალყის მცდელობაც რომ უშედეგო დარჩა, ჯემ სულთანი ოცდაათიოდე კაცით ანატოლიიდან გაიქცა, როდოსს მიაღწია და წმინდა იოანეს რაინდებმა ცერემონიით მიიღეს. მაგრამ სტუმრობა მალე ტყვეობად იქცა; უფლისწული ჯერ საფრანგეთს, შემდეგ პაპობას გადასცეს და ევროპული პოლიტიკის ხელში კოზირად იქცა. ბაიაზიდ II იძულებული გახდა ძმის დაკავების სანაცვლოდ ყოველწლიური საზღაური გადაეხადა და დასავლეთისკენ მიმართული ოსმალური სამხედრო ნაბიჯები ჯემის სიკვდილამდე შეჩერდა.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["ოსმალურ-მამლუქური ომის დაწყება (ჩუქუროვის ფრონტი)", "3fe3f0c7"], "d": ["დულყადირიდებზე გავლენისთვის ბრძოლამ და ჯემ სულთნის მამლუქთა მიწებზე თავის შეფარების დატოვებულმა მტრობამ 1485 წელს ორ დიდ სუნიტურ ძალას შორის ექვსწლიანი ომი დაიწყო. ჩუქუროვაში, ადანისა და ტარსუსის მიდამოებში გამართულ შეტაკებებში მხარეებმა ერთმანეთზე უპირატესობა ვერ მოიპოვეს; ოსმალურმა ჯარებმა რამდენიმე მძიმე დარტყმა მიიღეს. ეს ომი ოსმალურ-მამლუქური ურთიერთობების გარღვევის პირველი ფაზა და იმ პროცესის გახსნაა, რომელიც ოცდაათი წლის შემდეგ იავუზის მარჯ-დაბიყისა და რიდანიას ლაშქრობებით დასრულდებოდა.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["ოსმალურ-მამლუქური ზავი — ტუნისის შუამავლობა", "60dd6719"], "d": ["1485 წელს დაწყებულ ოსმალურ-მამლუქურ ომში მხარეებმა გადამწყვეტი გამარჯვება ვერ მოიპოვეს; ტუნისის მმართველ ოსმან ჰაფსელის შუამავლობით 1491 წელს შეთანხმება მიღწეულ იქნა. ხელშეკრულებამ საზღვრები დიდწილად ომამდელ მდგომარეობას დაუბრუნა და ორ ისლამურ სახელმწიფოს შორის ანგარიშსწორება ერთი თაობით გადაიდო. ექვსწლიანი გამაჩანაგებელი ბრძოლა ბაიაზიდ II-ის ფრთხილი საგარეო პოლიტიკისა და აღმოსავლეთისკენ მიმართვის ნაცვლად შიდა მოწესრიგებისთვის უპირატესობის მინიჭების ერთ-ერთი მთავარი მიზეზია.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["ესპანეთიდან განდევნილი სეფარდი ებრაელების ოსმალეთში მიღება", "5c2b5c24"], "d": ["გრანადის დაცემის შემდეგ ესპანეთში ინკვიზიციის სისასტიკეს გამორიდებული ებრაელების ნაწილმა ოსმალურ მიწებზე შეაფარა თავი და სხვადასხვა ქალაქში დაასახლეს. ოსმალურ მმართველობაში ამ სეფარდულმა თემებმა მანამდე არნახული თავისუფლება მოიპოვეს: სასურველ ადგილას დასახლება, რწმენის აღსრულება, საგანმანათლებლო დაწესებულებების გახსნა და ახალი სინაგოგების აშენება. თან მოტანილი სტამბის, მედიცინისა და ფინანსების ცოდნით სალონიკისა და სტამბოლის ეკონომიკური ცხოვრების გარდამქმნელი ეს მიგრაცია ოსმალური შემწყნარებლობის წყობის ევროპაში ყველაზე მეტად განხილული ნიმუში გახდა.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["ჯემ სულთნის გარდაცვალება — თოთხმეტწლიანი მძევლობის დასასრული", "f6588b70"], "d": ["პაპის ხელიდან საფრანგეთის მეფე შარლ VIII-სთვის გადაცემული ჯემ სულთანი, რომელიც 1495 წლის 27 იანვარს რომიდან გაემგზავრა, გარდაიცვალა ადგილას, რომელსაც კასტელ კაპუანა ერქვა; წყაროები აღნიშნავენ, რომ ის შესაძლოა პაპის კარის წრეებმა მოწამლეს. თოთხმეტი წლის განმავლობაში ევროპული სახელმწიფოების ხელში ოსმალეთის წინააღმდეგ მუქარის ბანქოდ შენახული შაჰზადეს სიკვდილმა ბოლოს ხელები გაუხსნა ბაიაზიდ II-ს. მართლაც, ამის შემდეგ ფადიშაჰი ომს გამოუცხადებს ვენეციას და თავის ფლოტს პირველ დიდ გამარჯვებამდე მიიყვანს.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["საპიენცის (ზონკიოს) საზღვაო გამარჯვება — ფლოტის პირველი დიდი წარმატება ხმელთაშუა ზღვაში", "9754aaef"], "d": ["ჯემის საქმის დასრულებით ხელებგახსნილმა ბაიაზიდ II-მ 1499 წელს ვენეციას ომი გამოუცხადა; ოსმალურმა ფლოტმა საპიენცის (ზონკიოს) სანაპიროებთან ვენეციური ესკადრა დაამარცხა და ხმელთაშუა ზღვაში პირველი დიდი საზღვაო გამარჯვება მოიპოვა. ამ გამარჯვებით ფლოტმა განაცხადა, რომ ამიერიდან ვენეციისთვის ზღვაზე წინააღმდეგობის გაწევა შეეძლო.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["კეფალონიისა და ითაკის დაკარგვა", "60f0f687"], "d": ["მოდონისა და კორონის აღებით შერყეული ვენეცია ესპანეთთან გაერთიანებით კონტრშეტევაზე გადავიდა და 1479 წლიდან ოსმალთა ხელში მყოფ კეფალონიას ალყა შემოარტყა. ორმოცდაშვიდდღიანი წინააღმდეგობის შემდეგ ციხე დაეცა, კუნძული ითაკასთან ერთად ვენეციაზე გადავიდა და სამასი წელი ოსმალურ მმართველობას აღარ დაბრუნებია. ამ დანაკარგმა ისეთი ბალანსი შექმნა, რომ მორეაში მოპოვებული იონიაში დაბრუნდა.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["ოქროს ურდოს სახანოს დაცემა და ყირიმის აღზევება", "0d1dc515"], "d": ["მისმა უკანასკნელმა მმართველმა შეიხ აჰმედ ხანმა (1481-1502) ვერ შეძლო ქვეყნის იმ კრიზისიდან გამოყვანა, რომელშიც ის ჩავარდა, და ოქროს ურდოს სახანო 1502 წელს ყირიმის ხან მენგლი გირაის დარტყმით ისტორიას ჩაბარდა. ტახტისთვის ბრძოლებისა და დაქუცმაცების შედეგად ოქროს ურდოს ყოფილ მიწებზე გაჩნდა ყირიმის, ყაზანის, ნოღაის, ასტრახანისა და ციმბირის სახანოები. ოსმალეთის მფარველობაში მყოფი ყირიმის ამ გამარჯვებამ შავი ზღვის ჩრდილოეთით ოსმალური გავლენა უდავო გახადა, ხოლო რეგიონში წარმოქმნილ სიცარიელეს მომდევნო საუკუნეში მოსკოვი შეავსებს.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["ოსმალეთ-ვენეციის ომის დასრულება და ზავი", "125b1526"], "d": ["1499 წელს დაწყებული ომი, რომელმაც ვენეცია საპიენცის ბრძოლითა და ლეპანტოს, მოდონისა და კორონის დაკარგვით შეარყია, 1502 წელს ზავით დასრულდა. მორეაში უმნიშვნელოვანესი ბაზების დაკარგვის შემდეგ ვენეცია იძულებული გახდა, აღმოსავლეთ ხმელთაშუა ზღვაში სავაჭრო პრივილეგიების შენარჩუნების სანაცვლოდ ოსმალეთის უპირატესობა ეღიარებინა. ბაიაზიდ II-ის ფრთხილად მიჩნეულმა მმართველობამ ამ ომით ოსმალეთი ხმელთაშუა ზღვაში პირველად აიყვანა სერიოზული საზღვაო ძალის დონეზე.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["შაჰკულუს აჯანყება — ყიზილბაშების გამოსვლა თექეს მხარიდან სივასამდე", "3beadca7"], "d": ["ანატოლიაში სეფიანთა პროპაგანდის გავლენით 1510 წელს აშკარად აჯანყებულმა შაჰკულუ ბაბა თექელიმ 1511 წლის მარტში ანტალიის ბაზარი დაარბია, აპრილში კი ქუთაჰიასა და მის შემოგარენში ოსმალური ძალები დაამარცხა. სივასის მახლობლად დიდ ვეზირ ხადიმ ალი-ფაშასთან გამართულ უკანასკნელ შეტაკებაში ორივე მხარემ მძიმე დანაკარგები განიცადა; დაიღუპა როგორც დიდი ვეზირი, ისე აჯანყების ლიდერი. ამ აჯანყებამ, რომელმაც ანატოლიაში სახელმწიფოს ავტორიტეტი შეარყია, გამოაშკარავა ძალაუფლების ვაკუუმი ბაიაზიდ II-ის მმართველობის ბოლო წლებში და შაჰზადე სელიმის ტახტისკენ სვლის ყველაზე ძლიერ საბაბად იქცა.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["ბაიაზიდ II-ის ტახტიდან გადადგომა და იავუზ სულთან სელიმის გამეფება", "c4cfab69"], "d": ["ძმებთან ტახტისთვის ბრძოლაში იანიჩრების მხარდაჭერით გაძლიერებული შაჰზადე სელიმის ზეწოლით ბაიაზიდ II 1512 წლის 24 აპრილს ტახტიდან გადადგა, და სელიმ I იმავე დღეს ტახტზე ავიდა როგორც მეცხრე ოსმალო მმართველი. მოხუცი ფადიშაჰი მშობლიურ დიმეტოკაში მიმავალ გზაზე, ჩორლუს მახლობლად, სოფელ აბალარში გარდაიცვალა ჰიჯრის 918 წლის 25 რაბი ალ-ავალს (1512 წლის 10 ივნისს). ოცდათერთმეტწლიანი ფრთხილი და საკუთარ თავში ჩაკეტილი მმართველობა შეცვალა იავუზის ეპოქამ, რომელიც რვა წელიწადში იმპერიის საზღვრებს გააორმაგებს.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["სინის (Sinj) ციხის აღება", "83271ea5"], "d": ["ბოსნიის საზღვარზე მყოფმა ოსმალურმა აკინჯების ძალებმა დალმაციის სიღრმეში გადაჭიმული სინის (Sinj) ციხე უნგრეთის სამეფოს წაართვეს. ეს დალმაციის სასაზღვრო ხაზის ადრეული რგოლი იყო, რომელიც ცხრა წლის შემდეგ გაზი ჰუსრევ ბეის მიერ კნინისა და მისი შემოგარენის აღებით გაფართოვდებოდა; ციხე 1686 წელს ვენეციის სასარგებლოდ დაიკარგებოდა.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["იენიშეჰირის ბრძოლა და შაჰზადე აჰმედის ჩამოშორება", "e2ed15dd"], "d": ["იავუზ სულთან სელიმმა ტახტის ყველაზე ძლიერი მეტოქე, უფროსი ძმა შაჰზადე აჰმედი, ბურსის მახლობლად იენიშეჰირის ველზე გაანადგურა, ტყვედ აიყვანა და მოიშორა. ამგვარად, 1511 წლიდან მიმდინარე ძმათა შუღლი დასრულდა და ანატოლიაში შიდა განხეთქილებას ბოლო მოეღო. სელიმმა ზურგი უზრუნველყო და მოიპოვა თავისუფლება, რომ სეფიანთა საკითხისთვის მიემართა ძალისხმევა.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["იავუზ სულთან სელიმის შესვლა თავრიზში", "dad2e227"], "d": ["ჩალდირანის გამარჯვების შემდეგ ოსმალური ჯარი სეფიანთა დედაქალაქ თავრიზში შევიდა და ქალაქში ხუტბა ფადიშაჰის სახელით წაიკითხეს. სელიმი აქ ერთი კვირა დარჩა და თავრიზელი ხელოვანებისა და ულემების ნაწილი სტამბოლში გადაასახლებინა; ეს გადაყვანა ოსმალთა სასახლის ხელოვნებაზე ღრმა გავლენას მოახდენდა. ზამთრის მოახლოებისა და იანიჩართა უკმაყოფილების გამო ქალაქი დატოვეს, მაგრამ აღმოსავლეთში სეფიანთა უპირატესობა უკვე გატეხილი იყო. რუკაზე ამ დღეს ოსმალებზე გადასული ადგილები ერთმანეთს არ ემიჯნება, და ეს სწორია: თავრიზი ჯარის ცხრადღიანი ოკუპაციაა; ერზინჯანის ველი ლაშქრობისას უბრძოლველად დანებდა, მის შუაგულში მდებარე ქემახის ციხე კი 1515 წლის 19 მაისამდე სეფიანთა ხელში წინააღმდეგობას უწევდა; სიირთი სეფიანებს უკან წაართვა ჰასანქეიფის მელიქმა ხალილ ბეიმ, რომელმაც თავრიზში შაჰ ისმაილის ტყვეობას თავი დააღწია და ოსმალებს დაემორჩილა — მისი შემოგარენიდან დიარბექირი 1515 წლამდე, ჰასანქეიფი კი 1517 წლამდე სეფიანებს ეკუთვნოდა.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["მუში და ბინგოლი (ჩაფაქჩური) სეფიანებიდან ოსმალური მმართველობის ქვეშ გადავიდა", "b0a53b5a"], "d": ["ჩალდირანის შემდეგ აღმოსავლეთ ანატოლიის სეფიანებისგან წართმევისას მუში ჰიჯრით 921/1515 წელს ოსმალური მმართველობის ქვეშ მოექცა; მეზობელი ჩაფაქჩური (ბინგოლი) იმავე პროცესში შეუერთდა ოსმალეთს.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["ქემახის ციხის აღება სეფიანთაგან", "73fd8671"], "d": ["ჩალდირანიდან დაბრუნებისას ზამთარი ამასიაში გაატარა იავუზ სულთან სელიმმა და ევფრატის გადასასვლელის მაკონტროლებელი, გამაგრებული ქემახის ციხის აღება ბიიყლი მეჰმედ-ფაშას დაავალა. ალყის ბოლოს, რომელშიც თავად ფადიშაჰიც მონაწილეობდა, ციხე სეფიანებს ხელიდან გამოსტაცეს და აღმოსავლეთ ანატოლიის კარი გაიღო. ეს დაპყრობა პირველი კონკრეტული ნაბიჯი იყო, რომელმაც ჩალდირანის გამარჯვება მუდმივ ტერიტორიულ შენაძენად აქცია.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["თურნადაღის გამარჯვება — დულკადირის საბეილიქო ოსმალეთს დაექვემდებარა", "fd879145"], "d": ["ოსმალურმა ძალებმა ჩალდირანის ლაშქრობისას ორაზროვანი პოზიციის დამკავებელი დულკადირის ბეი ალაუდევლე ბოზქურთი გიოქსუნსა და ანდირინს შორის, ორდექლის ადგილას, დაამარცხეს; ალაუდევლე ამ ბრძოლაში მოკლეს. საბეილიქო ამ დროს არ შეუერთებიათ: ალაუდევლეს შემდეგ დულკადიროღლუების საბეილიქოს სათავეში იავუზ სულთან სელიმმა შეჰსუვაროღლუ ალი ბეი დააყენა, და მარაშ-ელბისთანის ცენტრის მქონე ქვეყანა ოსმალეთზე დაქვემდებარებულ საბეილიქოდ განაგრძობდა არსებობას. ამგვარად, მამლუქთა საზღვარზე არსებული ბუფერი ოსმალთა კონტროლქვეშ გადავიდა და ორი წლის შემდეგ ეგვიპტის ლაშქრობის გზა გაიხსნა; ანექსია კი ალი ბეის მოკვლის შემდეგ განხორციელდება.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["ამიდის (დიარბექირის) აღება და დიარბექირის საბეგლარბეგოს დაარსება", "a6867d5b"], "d": ["მას შემდეგ, რაც იდრის ბითლისიმ რეგიონის სუნიტი ქურთი ბეები ოსმალეთის მხარეს გადმოიბირა, სეფიანთა ძალებმა ხანგრძლივ ალყას ვერ გაუძლეს, და ამიდის გასაღებები ბიიყლი მეჰმედ-ფაშას ჩააბარეს. ქალაქი ახლად დაარსებული დიარბექირის საბეგლარბეგოს ცენტრად აქციეს. ამგვარად, ზემო მესოპოტამიის ადმინისტრაციული ბირთვი ოსმალთა ხელში გადავიდა.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["ხარფუთის აღება — დიარბექირის გზის გახსნა", "564eb269"], "d": ["ჩალდირანის შემდეგ აღებული დიარბექირის სეფიანთა ალყიდან გადასარჩენად დაძრულმა ყარამანის ბეგლარბეგმა ჰუსრევ-ფაშამ სამდღიანი ალყის ბოლოს აიღო ხარფუთის ციხე, რომლის შემოგარენიც მანამდე ჩერქეზ ჰუსეინ ბეის ეპყრა. ამგვარად, ევფრატის აღმოსავლეთით დიარბექირისკენ მიმავალი გზა უზრუნველყოფილი გახდა.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["კოჩჰისარის (ქიზილთეფეს) ბრძოლა — ყარა ხანის დამარცხება", "9ea9e843"], "d": ["ბიიყლი მეჰმედ-ფაშას სარდლობით ოსმალურმა ჯარმა კოჩჰისარის მახლობლად, დედე გარყინის ველის ქორუქის ადგილას, მთელი დღის განმავლობაში გაგრძელებულ საველე ბრძოლაში დაამარცხა სეფიანთა მმართველი ყარა ხანი; ყარა ხანის მოკვეთილი თავი ფადიშაჰის ბანაკში გაიგზავნა. შემდეგ ოსმალური ძალები ქალაქ მარდინში შევიდნენ, მაგრამ რამდენიმე დღის შემდეგ დატოვეს იგი; სეფიანთა მცველების ხელში მყოფი მარდინის ციხის ჩაბარება მხოლოდ ერთი წლის შემდეგ გახდა შესაძლებელი. ამ გამარჯვებამ იავუზის სამხრეთ საზღვარი უზრუნველყო და ეგვიპტის ლაშქრობაზე გადასვლა შესაძლებელი გახადა. იმავე თარიღს შემოერთებული სხვა ადგილები: პალუ, ჩემიშგეზექი, სივერექი.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["იავუზ სულთან სელიმის გამგზავრება სტამბოლიდან ეგვიპტის ლაშქრობისთვის", "ac258b4b"], "d": ["იავუზ სულთან სელიმი სტამბოლიდან გაემგზავრა, ერთი შეხედვით სეფიანთა წინააღმდეგ ახალი აღმოსავლური ლაშქრობის მოსამზადებლად, და აქშეჰირის გავლით სამხრეთისკენ გაემართა. მამლუქთა სულთნის ყანსუჰ ალ-ღაურის კავშირი შაჰ ისმაილთან და ოსმალეთის აღმოსავლეთ ფრთისთვის მისი მუქარა მალე მიზნის შეცვლას გამოიწვევს. ეს ლაშქრობა ორ წელიწადს გაგრძელდება და იმ დიდი ოპერაციის დასაწყისია, რომელიც ოსმალეთს ახლო აღმოსავლეთის იმპერიად გადააქცევს.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["ზებიდის აღება: ოსმალო მეზღვაურთა პირველი შესვლა წითელ ზღვაში", "38740e0c"], "d": ["ინდოეთის ოკეანეში პორტუგალიის ზეწოლის პირისპირ, მამლუქთა სულთნის ყანსუჰ ალ-ღაურის თხოვნით წითელ ზღვაში გაგზავნილმა ოსმალური წარმოშობის მეზღვაურებმა, ჰუსეინ ბეიმ და სელმან რეისმა, თავიანთი ფლოტით ზებიდი აიღეს. ეს ოპერაცია, რომელიც ჯერ კიდევ მამლუქთა სამსახურში ხორციელდებოდა, ოსმალური საზღვაო ძალის პირველი ფაქტობრივი ყოფნაა წითელი ზღვა-ინდოეთის ხაზზე. ერთი წლის შემდეგ, როცა ეგვიპტე ოსმალეთს გადაეცემა, იგივე ესკადრა პირდაპირ სტამბოლს დაექვემდებარება.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["ლაშქრობის მიზნად მამლუქებისა და ალეპოს ოფიციალური გამოცხადება", "689e310d"], "d": ["როდესაც ყანსუჰ ალ-ღაურიმ სეფიანებთან შეთანხმებით თავისი ჯარი ალეპოსკენ დაძრა, იავუზ სულთან სელიმმა ლაშქრობის მიზნად აშკარად მამლუქთა სულთანი და ალეპო გამოაცხადა. ამგვარად, ორ სუნიტურ სახელმწიფოს შორის წლების განმავლობაში მიმდინარე ფარული მეტოქეობა ღია ომად გადაიქცა. ამ გამოცხადებამ დაიწყო მარჯ-დაბიყამდე მიმავალი ოთხკვირიანი უკუთვლა.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["ადენის ალყის მარცხი: წითელ ზღვაში პორტუგალიის წინააღმდეგ პირველი მცდელობა", "8ffd46f2"], "d": ["სელმან რეისმა და ჰუსეინ ბეიმ რვადღიანი ალყა მოაწყვეს ადენის, წითელი ზღვიდან ინდოეთის ოკეანეში გასასვლელი კარის, ასაღებად, მაგრამ ქალაქის ძლიერი სიმაგრეების წინაშე იძულებული გახდნენ უკან დაეხიათ. ადენის ვერაღება პორტუგალიის წინააღმდეგ გასატარებელ სამხრეთის სტრატეგიას მრავალი წლით შეაფერხებს. ეს მცდელობა ოსმალეთის ოკეანის პოლიტიკის პირველი გამოცდაა.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["რამაზანიდების საბეილიქოს ოსმალეთთან დაკავშირება", "cfaa3754"], "d": ["მარჯ-დაბიყის გამარჯვების შემდეგ განხორციელებული დანიშვნებისას ადანის ცენტრის რამაზანიდების საბეილიქო მაჰმუდ ბეის მიეცა და ოსმალთა ბატონობაში მოექცა. მამლუქთა ქვეშევრდომობიდან გამოსული საბეილიქო მოსპობის ნაცვლად „ოჯაღლიკის“ სტატუსით ოჯახს დაუტოვეს; რამაზანიდები ჩუქუროვას მმართველობას ოსმალო სანჯაყბეის სტატუსით აგრძელებდნენ. ეს პრივილეგირებული წყობა 1608 წლამდე გაგრძელდა, როცა ფირ მანსურმა საბეილიქო დატოვა. იმავე თარიღს შემოერთებული სხვა ადგილები: მალათია, ტარსუსი, მოსული, აინთაბი.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["ალეპოს, რაქასა და დეირ-ეზ-ზორის შესვლა ოსმალთა ბატონობის ქვეშ", "2088eb6a"], "d": ["მარჯ-დაბიყიდან ოთხი დღის შემდეგ იავუზ სულთან სელიმი წინააღმდეგობის გარეშე შევიდა ალეპოში, და ქალაქის მეჩეთებში ხუტბა მისი სახელით წაიკითხეს. სირიის სავაჭრო და ადმინისტრაციულ დედაქალაქად მიჩნეული ალეპოს ასე სწრაფი დაცემა აჩვენებს, რომ რეგიონში მამლუქთა ხელისუფლება დაშლილი იყო. ქალაქის აღებამ ერთბაშად გახსნა გზა დამასკოსკენ და იქიდან ეგვიპტისკენ. იმავე თარიღს შემოერთებული სხვა ადგილები: ანტიოქია, რაქა, დეირ-ეზ-ზორი.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["შეხვედრა აბასიან ხალიფა ალ-მუთავაქილ III-სთან ალეპოს გიოქმეიდანში", "22979f42"], "d": ["მარჯ-დაბიყში მამლუქთა ჯართან ერთად ტყვედ ჩავარდნილი კაიროს აბასიანი ხალიფა ალ-მუთავაქილ III ალეპოში, გიოქმეიდანში, ფადიშაჰის წინაშე წარადგინეს, და იავუზ სულთან სელიმმა მას დიდი პატივისცემა გამოუხატა. 1261 წლიდან მამლუქი სულთნების ჩრდილში სიმბოლურ თანამდებობად არსებული კაიროს ხალიფატი ამ შეხვედრით ფაქტობრივად ოსმალეთის მფარველობაში გადავიდა. მოგვიანებით ხალიფას ფადიშაჰთან ერთად სტამბოლში წაიყვანენ.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["ტრიპოლისა და ჰამას ოსმალურ მმართველობაში შესვლა", "a1e19a79"], "d": ["ალეპოსა და ჰამას შემდეგ სირიის სანაპიროზე მდებარე ტრიპოლიც (ლიბანი) წინააღმდეგობის გარეშე ოსმალურ მმართველობაში გადავიდა. აღმოსავლეთ ხმელთაშუა ზღვის ერთ-ერთი ყველაზე ხალხმრავალი პორტის მქონე ქალაქი დამასკოს ზღვაზე გამავალი კარი და აბრეშუმითა და შაქრით ვაჭრობის ცენტრი იყო. მისი აღებით ბილად აშ-შამის სანაპირო ზოლმა მთლიანად ხელი შეიცვალა.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["დამასკოს შესვლა ოსმალთა ბატონობის ქვეშ", "2b844d91"], "d": ["ალეპოს შემდეგ ჰამისა და ჰომსის დანებებით გზა გაეხსნა იავუზ სულთან სელიმს, რომელმაც 27 სექტემბერს დამასკოს მისადგომებს მიაღწია; ქალაქში მაშინვე არ შევიდა, არამედ გარეთ, მასტაბას ადგილას, კარავი გაშალა და ჩასვლიდან მეთორმეტე დღეს დიდი ცერემონიით შევიდა. დამასკოში საკმაოდ დიდხანს დარჩა, სირიის ადმინისტრაციული წესრიგი ჩამოაყალიბა და მუჰიდინ იბნ ალ-არაბის საფლავი ააგებინა. ამგვარად, ბილად აშ-შამი მთლიანად გამოვიდა მამლუქთა მმართველობიდან. იმავე თარიღს შემოერთებული სხვა ადგილები: ბეირუთი.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["თუმან-ბეის მამლუქთა სულთნად გამოცხადება კაიროში", "6020d90d"], "d": ["მარჯ-დაბიყში დაღუპული ყანსუჰ ალ-ღაურის შემდეგ მამლუქმა ამირებმა ტახტზე აიყვანეს თუმან-ბეი, რომელიც სახელმწიფოს უკანასკნელი სულთანი გახდება. ჩერქეზული წარმოშობის ახალმა სულთანმა ჩაიბარა სახელმწიფო, რომელმაც სირია დაკარგა, ხაზინა გამოეფიტა და ცეცხლსასროლი იარაღი არ გააჩნდა. მიუხედავად ამისა, ის კაიროს მისადგომებთან თავდაცვის ხაზს შექმნის და ოსმალთა წინსვლის წინააღმდეგ უკანასკნელ წინააღმდეგობას მოაწყობს.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["ღაზის (ხან-იუნისის) ბრძოლა: ჯანბირდი ალ-ღაზალის დამარცხება", "9f1eb8cb"], "d": ["იავუზ სულთან სელიმმა ღაზისკენ ოთხიათასიანი ავანგარდით დიდი ვეზირი ხადიმ სინან-ფაშა გაგზავნა. თუმან-ბეის მიერ დამასკოს ნაიბად დანიშნული ჯანბირდი ალ-ღაზალი ცდილობდა ოსმალთა ავანგარდი ღაზა-ხან-იუნისის ხაზზე შეეჩერებინა, მაგრამ მძიმე მარცხი განიცადა და ეგვიპტეში გაიქცა. პალესტინაში მამლუქთა უკანასკნელი ბუფერული ძალის დაშლით სინას უდაბნოსკენ მიმავალი გზა სრულად გაიხსნა.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["იორდანეს აღმოსავლეთი: ამანის ოსმალურ მმართველობაში შესვლა", "9db62667"], "d": ["ღაზის ბრძოლის შემდეგ ეგვიპტის ლაშქრობისთვის მომზადებული ოსმალური ძალების სამხრეთით ჩასვლისას იორდანეს აღმოსავლეთით მდებარე ამანიც ოსმალურ მმართველობაში შევიდა. პალესტინის სანაპირო და შიდა ქალაქებმა (იაფა, ნაბლუსი, საიდა, აკრა, იერუსალიმი) კი მარჯ-დაბიყის შემდეგ, 1516 წლის შემოდგომაზე, უკვე შეიცვალეს ხელი. ეს ქალაქები ოთხი საუკუნის განმავლობაში დამასკოს ეიალეთის სანჯაყებად იმართებოდა.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["იავუზ სულთან სელიმის ჩასვლა იერუსალიმში", "66d7bfad"], "d": ["მარჯ-დაბიყის შემდეგ ოსმალურ მმართველობას წინააღმდეგობის გარეშე გადაცემულ იერუსალიმში ღაზის ბრძოლის შემდეგ იავუზ სულთან სელიმი სახელმწიფო წარჩინებულებთან და ჯართან ერთად ჩავიდა. ფადიშაჰმა მოინახულა კლდის გუმბათი და ალ-აქსას მეჩეთი და ქალაქის წმინდა სტატუსი დაადასტურა. იერუსალიმი ამ დღიდან 1917 წლის დეკემბრამდე ზუსტად ოთხი საუკუნე ოსმალთა მმართველობაში დარჩება.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["იავუზ სულთან სელიმის შესვლა ღაზაში და სვლა სინას უდაბნოსკენ", "2106bfc7"], "d": ["ხან-იუნისში ჯანბირდი ალ-ღაზალის დამარცხების (1516 წლის 21 დეკემბერი) შემდეგ ღაზა ავანგარდის ხელში იყო. ფადიშაჰი 1517 წლის 2 იანვარს ღაზაში შევიდა და აქ ავანგარდის მეთაურ სინან-ფაშას შეხვდა, ჯარმა კი ეგვიპტეში გადასასვლელად ბოლო მზადება ჩაატარა. ღაზიდან სალიჰიამდე გადაჭიმულ უწყლო კატიას (სინას) უდაბნოში რვა გადასვლა უნდა გაევლოთ, წყალი კი აქლემებით უნდა გადაეტანათ. ეს გადასვლა ლაშქრობის ყველაზე სარისკო და ლოგისტიკურად ყველაზე რთული ეტაპია.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["სუეცის აღება — წითელ ზღვაზე გამავალი კარი", "05f3324e"], "d": ["რიდანიას გამარჯვების შემდეგ ოსმალური ნაწილების კაიროში შესვლით წითელი ზღვის ჩრდილო ბოლოში მდებარე სუეციც ოსმალურ მმართველობაში გადავიდა. გემთსაშენი და პორტი, საიდანაც მამლუქები ინდოეთის ოკეანეში ფლოტს აგზავნიდნენ, პორტუგალიის წინააღმდეგ წარმართული სამხრეთის პოლიტიკის ბაზად იქცა. სუეცი იმ ხაზის ჩრდილო შესართავია, სადაც სამი საუკუნის შემდეგ არხი გაიჭრებოდა.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["ოსმალური ნაწილების პირველი შესვლა კაიროში", "0a3f4f4d"], "d": ["რიდანიის გამარჯვების მეორე დღეს ოსმალურ ჯარებს კაიროში შესვლის ნება დართეს, და 24 იანვარს ნაწილები ქალაქში დაბანაკდნენ. თუმცა ეს შესვლა ქალაქის სრულ კონტროლს არ ნიშნავდა; თუმან-ბეი ზემო ეგვიპტეში გავიდა, მამლუქთა წინააღმდეგობა კი ჯერ არ იყო გატეხილი. კაიროს დაპყრობა ერთ დღეში კი არა, კვირების განმავლობაში გაწელილ სისხლიან პროცესში დასრულდება.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["თუმან-ბეის თავდასხმა კაიროზე და სამდღიანი ქუჩის ბრძოლები", "b83b6ce6"], "d": ["ზემო ეგვიპტეში გასული თუმან-ბეი, თან დაახლოებით შვიდი ათასი კაცით, 27-28 იანვრის ღამეს მოულოდნელად შეიჭრა კაიროში, ქალაქის შიგნით წინააღმდეგობა წამოიწყო და ოსმალური ნაწილები უკიდურესად რთულ მდგომარეობაში ჩააგდო. სამი დღის განმავლობაში გაგრძელებულ სასტიკ ქუჩის შეტაკებებში მამლუქებმა ქალაქის დიდი ნაწილი დროებით ხელში შეინარჩუნეს. წინააღმდეგობის გატეხა მხოლოდ ოსმალური არტილერიისა და დამხმარე ძალების ჩართვის შემდეგ გახდა შესაძლებელი.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["ჯანბირდი ალ-ღაზალის ოსმალთა სამსახურში შესვლა", "a94ea459"], "d": ["რიდანიის შემდეგ სალიჰიაში უკანდახეულმა ყოფილმა მამლუქმა ამირმა ჯანბირდი ალ-ღაზალიმ ფადიშაჰს მიმართა და შეწყალება სთხოვა. იავუზ სულთან სელიმმა, რადგან ფიქრობდა, რომ ის ეგვიპტესა და სირიაში წესრიგის დამყარებაში გამოადგებოდა, იგი სამსახურში მიიღო. ეს არჩევანი ოსმალეთის იმ პოლიტიკის პირველი დიდი მაგალითია, რომელიც მამლუქთა კადრების მოშორების ნაცვლად მათ სისტემაში ჩართვას გულისხმობდა.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["იავუზ სულთან სელიმის საზეიმო შესვლა კაიროში და ხუტბის წაკითხვა", "6d98080c"], "d": ["ქუჩის შეტაკებების ჩახშობის შემდეგ ფადიშაჰი 1517 წლის 15 თებერვალს ძალზე ბრწყინვალე ცერემონიით შევიდა კაიროში, და მეჩეთებში ხუტბა მისი სახელით წაიკითხეს. კაიროში ხუტბის ოსმალო სულთნის სახელით წაკითხვა იმის გამოცხადებაა, რომ 1250 წლიდან არსებული მამლუქთა ბატონობა სამართლებრივად დასრულდა. ეს თარიღი ეგვიპტის ფაქტობრივი დაპყრობის სიმბოლური დასრულების მომენტად მიიჩნევა.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["მამლუქთა უკანასკნელი სულთნის, თუმან-ბეის, შეპყრობა თერუჯაში", "7058e6ad"], "d": ["კაიროს დატოვების შემდეგ ნილოსის დელტაში დამალული თუმან-ბეი მისმა შემფარებელმა ბედუინებმა გასცეს, და ის თერუჯას მხარეში შეიპყრეს. მისმა შეპყრობამ მამლუქთა წინააღმდეგობის ორგანიზებული ცენტრი მოშალა. ამის შემდეგ უკანასკნელი სულთანი თოთხმეტი დღე ოსმალთა ხელში იქნება.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["თუმან-ბეის ჩამოხრჩობა ბაბ ზუვეილასთან და მამლუქთა სახელმწიფოს დასასრული", "ad9820be"], "d": ["შეპყრობიდან თოთხმეტი დღის შემდეგ თუმან-ბეი კაიროს სახელგანთქმულ ჭიშკარზე, ბაბ ზუვეილაზე, ჩამოახრჩვეს; მისი ცხედარი მოგვიანებით მისი ბიძის აგებულ მედრესეში დაკრძალეს. ამგვარად, 1250 წლიდან ეგვიპტესა და სირიაზე გაბატონებული მამლუქთა სახელმწიფო ოფიციალურად ჩაბარდა ისტორიას. წინააღმდეგობის გატეხვით ზემო ეგვიპტის (საიდის) ისეთი ქალაქებიც, როგორიცაა ასიუტი და ასუანი, ოსმალთა მმართველობას დაექვემდებარა.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["პორტუგალიური ფლოტის თავდასხმა ჯიდაზე და სელმან რეისის თავდაცვა", "52322cf5"], "d": ["დაახლოებით ოცდაათი გალერისა და გალეონისგან შემდგარი პორტუგალიური ფლოტი ჯიდას დაესხა თავს; სელმან რეისმა ქალაქის თავდაცვას უხელმძღვანელა, მტერს ხმელეთზე გადმოსხმა არ დაანება და რამდენიმე პორტუგალიური ხომალდი ჩაძირა. ამ თავდაცვამ აღკვეთა მექის ნავსადგურის და, შესაბამისად, ჰაჯის გზის ქრისტიანული სახელმწიფოს ხელში გადასვლა. რამდენიმე თვის შემდეგ ჯიდა ჰიჯაზის ერთგულების ფიცით ოფიციალურად შევა ოსმალთა მმართველობაში.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["ალექსანდრიის ჩაბარება ფლოტისთვის — ეგვიპტის დაპყრობის დასრულება", "386878fe"], "d": ["რიდანიიდან ზუსტად ოთხი თვის, თუმან-ბეის ჩამოხრჩობიდან კი ოცდათექვსმეტი დღის შემდეგ, ჯაფერ ბეის მეთაურობით ოსმალური ფლოტის ნავსადგურში მისვლით ალექსანდრია ოსმალთა მმართველობაში გადავიდა; დელტის ისეთი ნავსადგურებიც, როგორიცაა როზეტა (რაშიდი) და დამიეტა, იმავე პროცესში შემოერთდა. ის, რომ ხმელთაშუა ზღვისკენ გახსნილი ეგვიპტის ეს დიდი ნავსადგური კაიროს დაცემიდან თვეების შემდეგ და ხმელეთიდან კი არა, ზღვიდან ჩაიბარეს, ნათლად აჩვენებს, რომ დაპყრობა ერთი ბრძოლით კი არა, რეგიონების მიხედვით ეტაპობრივად დასრულდა. ამის შემდეგ ალექსანდრია სტამბოლისა და კაიროს დამაკავშირებელ სასიცოცხლო ნავსადგურად იქცევა. იმავე თარიღს შემოერთებული სხვა ადგილები: რაშიდი (როზეტა).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["ჰიჯაზის უბრძოლველი შემოერთება: მექის შარიფის ძის, აბუ ნუმეის, ერთგულების ფიცი", "c13b98c7"], "d": ["იავუზ სულთან სელიმი თავდაპირველად მექისა და მისი შემოგარენის დასაპყრობად ჯარის გაგზავნას ფიქრობდა, მაგრამ როცა მექის ამირმა შარიფ ბარაქათმა მორჩილება აცნობა, ამ განზრახვაზე ხელი აიღო. ბარაქათის თორმეტი წლის ვაჟი აბუ ნუმეი მამის საჩუქრებითა და მექის გასაღებებით კაიროში ჩავიდა და ფადიშაჰმა აუდიენციაზე მიიღო. ამგვარად, ჰიჯაზი ოსმალეთს შეუერთდა არა რიდანიის ავტომატური შედეგის სახით, არამედ ხუთთვენახევრის შემდეგ, ერთი ტყვიის გასროლის გარეშე, მშვიდობიანად და ერთგულების ფიცის გზით. იმავე თარიღს შემოერთებული სხვა ადგილები: ტაიფი. იმავე თარიღს ხელიდან გასული სხვა დასახლებები: ჰურმა (ტაიფის აღმოსავლეთით), რაბიღი, ბადრი.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["„ჰადიმ ალ-ჰარამაინის“ (ორი წმინდა ქალაქის მსახურის) ტიტულის მიღება და ხუტბა მედინაში", "63b32b59"], "d": ["მექის დელეგაციის მეორე აუდიენციის შემდეგ იავუზ სულთან სელიმმა ორი წმინდა ქალაქის (ჰარამაინის) მფარველობა ოფიციალურად იტვირთა და „ჰადიმუ ალ-ჰარამაინ აშ-შარიფაინ“-ის ტიტულის გამოყენება დაიწყო. შარიფ ბარაქათმა მისთვის გაგზავნილი საპატიო ხალათი ჩაიცვა და ხუტბა ფადიშაჰის სახელით წააკითხვინა; მედინის დელეგაციაც რომ სტამბოლში ჩავიდა, ბარაქათის ამირობა ბერათით დამტკიცდა. ფადიშაჰმა ორი წმინდა ქალაქის მოსახლეობას ორასი ათასი ოქროს მონეტა და უხვი სურსათი გაუგზავნა და ამით ყოველწლიურად გასამეორებელ სურრეს ტრადიციას დაუდო საფუძველი. იმავე თარიღს შემოერთებული სხვა ადგილები: იანბუ, თაბუქი.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["სელმან რეისის ოსმალთა სამსახურში შესვლა და წითელი ზღვის პოლიტიკის გადაბარება", "771da99a"], "d": ["ჯიდის პორტუგალიელებისგან დამცველი სელმან რეისი კაიროში ჩავიდა და იავუზ სულთან სელიმის წინაშე წარდგა; ერთხანს დააკავეს, მაგრამ 1519 წელს სტამბოლში გამოიძახეს, და მან პორტუგალიური საფრთხის წინააღმდეგ ოცდაათი გალერისა და რამდენიმე კალიოტის მომზადება იკისრა. ეს შეხვედრა იმის დასაწყისია, რომ წითელი ზღვისა და ინდოეთის ოკეანის პოლიტიკა მამლუქთა მემკვიდრეობიდან გადაიღეს და პირდაპირ სტამბოლს დაუქვემდებარეს. ოსმალეთი ამიერიდან, ხმელთაშუა ზღვის სახელმწიფოს გარდა, ოკეანის პოლიტიკის გამტარებელი ძალაც იყო.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["იავუზ სულთან სელიმის გამგზავრება კაიროდან და ჰაირ ბეის ბეგლარბეგობა", "8cd4fb23"], "d": ["ეგვიპტეში დაახლოებით რვა თვე დარჩენილმა და ადმინისტრაციული, ფინანსური და სამხედრო წესრიგის დამამყარებელმა იავუზ სულთან სელიმმა კაირო დატოვა; ალეპოს ყოფილმა ნაიბმა ჰაირ ბეიმ, რომელმაც მარჯ-დაბიყში მარცხენა ფრთის გაყვანით მამლუქთა მარცხი დააჩქარა, როგორც ეგვიპტის პირველმა ოსმალმა ბეგლარბეგმა, ყალათ ალ-ჯაბალის ციხიდან დაიწყო მმართველობა. მამლუქური წარმოშობის მმართველის არჩევა გააზრებული გარდამავალი პოლიტიკა იყო, რომ ახალი მმართველობა ადგილობრივ მოსახლეობას უცხოდ არ მოსჩვენებოდა. უკან დაბრუნებისას ფადიშაჰმა თან სტამბოლში წაიყვანა უკანასკნელი აბასიანი ხალიფა ალ-მუთავაქილ III და ეგვიპტის გამორჩეული ხელოვანები და მეცნიერები.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["კაიროს აბასიანთა ხალიფატის დასასრული — „გადაცემის ცერემონიის“ გადმოცემა", "1d357640"], "d": ["როცა იავუზ სულთან სელიმმა ეგვიპტე დაიპყრო, მარჯ-დაბიყში ტყვედ ჩავარდნილი უკანასკნელი ხალიფა ალ-მუთავაქილ ალა-ალლაჰ III თან წაიყვანა სტამბოლში; ამგვარად დასრულდა კაიროს აბასიანთა ხალიფატი, რომელიც 1261 წლიდან მამლუქი სულთნების ჩრდილში უუფლებოდ არსებობდა. ამის საპირისპიროდ, ცნობილი გადმოცემა იმის შესახებ, თითქოს ხალიფატი აია-სოფიაში ოფიციალური ცერემონიით გადაეცა იავუზს, პირველად XVIII საუკუნის ბოლოს დ’ოსონის ნაშრომში გვხვდება და იავუზის ეპოქის არც ერთ წყაროში არ არის. TDV-ის ისლამის ენციკლოპედია, რადგან ცერემონიის დამადასტურებელი ორიგინალური წყარო არ არსებობს, გადმოცემას გამოგონილად მიიჩნევს; თუმცა იმასაც აღნიშნავს, რომ შარიათის თვალსაზრისით ხალიფატის გადასასვლელად ასეთი გადაცემის ცერემონია საჭირო არ იყო.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["ერზურუმი ოსმალთა მმართველობას შეუერთდა — აღმოსავლეთ ანატოლიაში სეფიანთა გავლენა გატყდა", "78d1be02"], "d": ["მიუხედავად იმისა, რომ ჩალდირანის გამარჯვების (1514) შემდეგ რეგიონში ოსმალური გავლენა გაიზარდა, ერზურუმის სრული დაპყრობა ირანული გავლენის გატეხვამდე დაყოვნდა; ქალაქი ოსმალთა მმართველობას მხოლოდ ეგვიპტის ლაშქრობის შემდეგ, 1518-19 წლებში, შეუერთდა. ერზურუმი 1502 წელს, როცა შაჰ ისმაილმა აყ-ყოიუნლუს საბეილიქოს ბოლო მოუღო, სეფიანთა ბატონობის ქვეშ მოექცა; ამგვარად დასრულდა ეს თექვსმეტწლიანი პერიოდი. 1534 წელს, ორი ერაყის (ირაყეინის) ლაშქრობისას, ერზურუმის საბეგლარბეგო დაარსდება. 1518-1519 წლებს შორის ერზურუმის მხარესთან ერთად აშკალეც ოსმალთა მმართველობას შეუერთდა (დღე დაუდასტურებელია).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["ჯელალების აჯანყებების დასაწყისი: ბოზოქელი შეიხ ჯელალის ამბოხი", "99bd8a99"], "d": ["ბოზოქის მხარეში ვინმე შეიხ ჯელალმა თავი მაჰდად გამოაცხადა და თოქათის მიდამოებში აჯანყდა; ამბოხი ჩაახშეს, მაგრამ მისი სახელი ერთი საუკუნის განმავლობაში ანატოლიაში ყველა ყაჩაღური და ამბოხებული მოძრაობის სახელად იქცა. ჯელალობა XVI საუკუნის ბოლოს თიმარის სისტემის რღვევასა და დემოგრაფიულ წნეხთან შერწყმით იმპერიის ყველაზე ხანგრძლივ შიდა უსაფრთხოების პრობლემად გადაიქცა. აჯანყებებმა ანატოლიაში მასობრივი მიგრაციები გამოიწვია, რომელსაც „დიდი გაქცევა“ ეწოდა.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["ალჟირის შეერთება ოსმალეთის სახელმწიფოსთან", "b8eba4c1"], "d": ["ჩრდილოეთ აფრიკაში ესპანურ ზეწოლას წინააღმდეგობის გამწევმა ჰაირედინ რეისმა, რათა პოზიციები შეენარჩუნებინა, სტამბოლს მიმართა და ალჟირი ფადიშაჰს შესთავაზა, ხუტბა კი იავუზ სულთან სელიმის სახელით წაიკითხეს. ამგვარად, ალჟირი ოფიციალურად შეუერთდა ოსმალეთის მიწებს, ჰაირედინს კი ბეგლარბეგის ტიტულით ჯარი და ქვემეხები გაუგზავნეს. ამ შეერთებამ საფუძველი ჩაუყარა ოსმალთა საზღვაო ბატონობას დასავლეთ ხმელთაშუა ზღვაში, რომელიც საუკუნეები გაგრძელდებოდა. იმავე თარიღს შემოერთებული სხვა ადგილები: კონსტანტინა, შერშელი (Cherchell), მედეა (ტიტერი), სეტიფი.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["იავუზ სულთან სელიმის გარდაცვალება ჩორლუში", "9fe83744"], "d": ["სელიმ I-მა, რომელმაც რვა წელიწადში სახელმწიფოს ტერიტორია ორჯერ და მეტად გაზარდა, 1520 წლის 18 ივლისს ახალი ლაშქრობისთვის სტამბოლი დატოვა; ზურგზე გაჩენილი დიდი სიმსივნის გამო ჩორლუს იქით ვეღარ წავიდა. ექიმების ჩარევის მიუხედავად, ავადმყოფობა დამძიმდა და ორთვიანი უიმედო მკურნალობის შემდეგ აქ გარდაიცვალა ჰიჯრის 926 წლის 8-9 შავალს (1520 წლის 21-22 სექტემბერი). ჩალდირანით, მარჯ-დაბიყითა და რიდანიით მან ირანი შეაჩერა, მამლუქთა სახელმწიფო გააუქმა, ხალიფატი და ორი წმინდა ქალაქის მფარველობა ოსმალეთს მოუტანა. მას მხოლოდ ერთი ვაჟი დარჩა: სულეიმანი.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["კუნძულ იკარიის (ნიქარიას) ოსმალურ მმართველობაში შესვლა", "6afa972b"], "d": ["სამოსსა და ქიოსს შორის მდებარე იკარია 1481 წლიდან 1521 წლამდე როდოსის სენ-ჟანის რაინდების მმართველობაში იყო; კუნძულზე პირველი ოსმალური პერიოდი 1522 წელს დაიწყო და 1822 წლამდე გაგრძელდა. ამ პერიოდში გადასახადების აკრეფასა და გადახდაზე პასუხისმგებელი ქაიმაყამი იყო; ეგეოსის სხვა კუნძულების მსგავსად, ადგილობრივი უხუცესთა საბჭო (დიმოგერონტია) არსებობას აგრძელებდა და დროდადრო ოსმალურ მმართველობასთან კონფლიქტში შედიოდა.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["დულკადირის ქვეყნის ანექსია — მარაშის ცენტრის მქონე დულკადირის ეიალეთი", "595c3c30"], "d": ["1515 წლის თურნადაღის მარცხის შემდეგ ოსმალეთზე დაქვემდებარებულ საბეილიქოდ არსებული დულკადირის ქვეყანა, შეჰსუვაროღლუ ალი ბეის ართუქოვაში შვილებთან ერთად მკვლელობის შემდეგ, პირდაპირ ოსმალეთის მიწებს შეუერთდა და მარაშის ცენტრის მქონე ეიალეთად აქცია. საბეილიქოს ბოზოქის მხარე ცალკე სანჯაყად დაექვემდებარა ოსმალურ მმართველობას. ამგვარად, დაიხურა მარაშის, ელბისთანის, გიოქსუნის, გიურუნის, ზამანთისა და დარენდეს დაახლოებით ორსაუკუნოვანი დულკადირული ეპოქა; მამლუქთა საზღვარზე არსებული ბუფერული საბეილიქო სრულად გაქრა.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["კნინის აღება", "a46d3117"], "d": ["ბოსნიის სანჯაყბეგ გაზი ჰუსრევ ბეის ჰიჯრის 927-928 (1521-1522) წლების თავდასხმებით, პირველ რიგში კნინი, სკრადინი და ოსტროვიცა, ვენეციური ციხეების მთელი წყება ოსმალურ მმართველობაში გადავიდა; საზღვარი მეორე მთათა ქედის იქით გადაიწია. დაპყრობათა ამ ჯაჭვმა საფუძველი ჩაუყარა დალმაციის სანჯაყს, რომელიც თხუთმეტი წლის შემდეგ კლისის აღებით დასრულდებოდა.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["რაინდების უკანდახევა: ბოდრუმის, კოსისა და დოდეკანესის გადაცემა", "ea01666e"], "d": ["როდოსის დანებების პირობების თანახმად სენ-ჟანის რაინდებმა დაცალეს არა მხოლოდ კუნძულის ცენტრი, არამედ ყველა პოზიცია, რომელიც ორასი წლის განმავლობაში ეპყრათ. ანატოლიის სანაპიროზე მდებარე ბოდრუმის (სენ-პიერის) ციხე და კოსის, კალიმნოსისა და ლეროსის კუნძულები ამგვარად შეტაკების გარეშე ოსმალურ მმართველობაზე გადავიდა. როდოსის დაცემიდან ორი კვირის შემდეგ დასრულებული ამ გადაცემით ეგეოსის სამხრეთ-აღმოსავლეთ კუთხეში ლათინთა ყოფნა სრულად დასრულდა.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["მოღალატე აჰმედ-ფაშას აჯანყება ეგვიპტეში", "b18bb805"], "d": ["დიდ ვეზირობას მოლოდინში მყოფმა და ეგვიპტის მმართველად გაგზავნილმა აჰმედ-ფაშამ კაიროში თავი „ალ-მელიქ ალ-მანსურ სულთან აჰმედად“ გამოაცხადა და დამოუკიდებლობა გამოაქვეყნა. აჯანყება მალე ჩაახშეს და ფაშა მოკლეს, მაგრამ მოვლენამ აჩვენა, რამდენად მყიფე იყო ცენტრალური კონტროლი იმპერიის უმდიდრეს ეიალეთში. ამის შემდეგ იბრაჰიმ-ფაშა ეგვიპტეში ჩავიდა და ეიალეთის მმართველობის ხელახლა მომწესრიგებელი ცნობილი ეგვიპტის კანუნნამე შეადგენინა.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["ჩრდილოეთ ბოსნიის ანექსია: იაიცე და ბანია-ლუკა", "8ec86cfa"], "d": ["მოჰაჩის შემდეგ უნგრული თავდაცვითი ხაზის ჩამოშლისას ბოსნიის სანჯაყბეგი გაზი ჰუსრევ ბეი ვრბასის ხეობაში გაემართა და უნგრეთის სამეფოს ხელში დარჩენილი უკანასკნელი ბოსნიური ციხეები აიღო. იაიცეს და ბანია-ლუკის დაცემით ბოსნიის ეიალეთი ჩრდილოეთით მდინარე სავას მიადგა და ხორვატიის ფრონტი გაჩნდა. ბანია-ლუკა მალე ეიალეთის მეორე ცენტრად იქცა.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["ბუდის აღება და ზაპოიაისთვის გადაცემა", "fba4f89b"], "d": ["ვენის ლაშქრობის გზაზე ოსმალურმა ჯარმა ალყა შემოარტყა და დაიბრუნა ფერდინანდის ხელში ჩავარდნილი ბუდა და ქალაქი ოსმალთა მფარველობაში მყოფ უნგრეთის მეფე იანოშ ზაპოიაის გადასცა. ამგვარად, უნგრეთში ჰაბსბურგ-ოსმალურ მეტოქეობაში ბუფერული ვასალური სამეფოს მოდელი შეიქმნა. ეს წესრიგი 1541 წლამდე გაგრძელდება, ზაპოიაის გარდაცვალების შემდეგ კი ბუდა პირდაპირ ოსმალურ ეიალეთად იქცევა.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["კანუნი გერმანიის ლაშქრობაში გაემართა — გამოწვევა კარლ V-ს", "7c3d7055"], "d": ["ვენის ალყის უშედეგოდ დასრულებისა და ფერდინანდის მიერ ბუდისთვის ხელახალი ალყის შემორტყმის შემდეგ ფადიშაჰი სტამბოლიდან დაიძრა, ამჯერად იმპერატორ კარლ V-ის პირდაპირ საველე ბრძოლაში გამოსაწვევად. ჯარს აგვისტოში პატარა გიუნსის ციხის წინააღმდეგობა შეაყოვნებს, და რადგან იმპერატორი ბრძოლაში არ გამოვა, ლაშქრობა თავდასხმებით შემოიფარგლება. ლაშქრობამ საფუძველი მოამზადა ჰაბსბურგებთან მომდევნო წელს დადებულ პირველ ზავს.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["გერმანიის ლაშქრობა და გიუნსის (კესეგის) ალყა", "8aec937a"], "d": ["კარლ V-ის საველე ბრძოლაში ძალით გამოყვანის მიზნით კანუნი თავისი ჯარით ავსტრიაზე გაემართა; პატარა გიუნსის ციხემ ოცდახუთი დღე გაუწია წინააღმდეგობა და ჯარის წინსვლა შეაფერხა. რადგან იმპერატორი ბრძოლაში არ გამოვიდა, აკინჯებმა ვენის შემოგარენი დაარბიეს და სეზონის წინ წაწევის გამო უკან დაბრუნდნენ. ლაშქრობამ ტერიტორიული შენაძენი არ მოიტანა, მაგრამ ჰაბსბურგები მოლაპარაკების მაგიდასთან დასვა და მომდევნო წლის ზავის საფუძველი მოამზადა.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["სტამბოლის ზავი — პირველი ზავი ჰაბსბურგებთან", "b085767a"], "d": ["ფერდინანდის ელჩ კორნელიუსის მიღების შემდეგ ფადიშაჰი ცეცხლის შეწყვეტაზე დათანხმდა და ოსმალეთსა და ავსტრიას შორის პირველი ოფიციალური სამშვიდობო ტექსტი გაჩნდა. ზავით ფერდინანდმა მის ხელში მყოფი უნგრული მიწების სანაცვლოდ ყოველწლიური ხარკის გადახდა იკისრა, ავსტრიის ერცჰერცოგი კი პროტოკოლში დიდი ვეზირის ტოლად ჩაითვალა. ეს უთანასწორო სტატუსი XVI საუკუნეში ოსმალური დიპლომატიის უპირატესობის პრეტენზიის აშკარა გამოხატულება იყო.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["ყარსის აღება და ჩრდილო-აღმოსავლეთის საზღვრის გახსნა", "742e3101"], "d": ["ორი ერაყის ლაშქრობის ავანგარდული კოლონა ერზურუმიდან აღმოსავლეთისკენ რომ გაემართა, ქართული საათაბაგოს ხელში მყოფი და თემურის დროიდან დანგრეული ყარსის ციხე წინააღმდეგობის გარეშე ჩაიბარეს. ქალაქი, რადგან არაქსის რკალსა და ჩილდირს შორის გადასასვლელს აკონტროლებდა, ირანისკენ გახსნილი ჩრდილოეთი კარის გასაღებად ითვლებოდა. ეს შენაძენი ოცდაათი წლის შემდეგ დასაარსებელი ყარსის საბეგლარბეგოსა და კავკასიის ხაზის პირველი რგოლი გახდა.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["თავრიზში პირველი შესვლა — ორი ერაყის ლაშქრობის გახსნა", "cf7ed4e3"], "d": ["სერდარ-ი ექრემის წოდებით წინ მოძრავი იბრაჰიმ-ფაშა, რადგან შაჰ თამაზი საველე ბრძოლას ერიდებოდა და შიდა მხარეებში იხევდა, სეფიანთა დედაქალაქ თავრიზში წინააღმდეგობის გარეშე შევიდა. კანუნიც სექტემბერში ჩავიდა ქალაქში; მაგრამ ზამთრის დადგომისა და მომარაგების ხაზის ძალზე გაგრძელების გამო ჯარი ბაღდადის მიმართულებით გაემართა და თავრიზი დიდხანს ვერ შეინარჩუნეს. ჩალდირანის შემდეგ მეორედ აღებული ქალაქი ადგილი გახდა, სადაც ოსმალებმა ისწავლეს, რომ აღმოსავლეთში აღება ადვილია, შენარჩუნება კი რთული.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["ბარბაროსის მიერ ტუნისის აღება", "d8754216"], "d": ["კაპუდან-ფაშა ბარბაროს ჰაირედინ-ფაშამ, თავისი ფლოტით იტალიის სანაპიროების დარბევის შემდეგ, ტუნისს მიაშურა, ჰაფსიანთა მმართველი მულაი ჰასანი განდევნა და ქალაქში შევიდა. ტუნისის აღებამ, რომელიც სიცილიის სრუტეს აკონტროლებდა, დასავლეთ ხმელთაშუა ზღვაში ძალთა ბალანსი ერთბაშად ოსმალთა სასარგებლოდ შეცვალა. თუმცა ეს ბატონობა დიდხანს არ გაგრძელდება: კარლ V მომდევნო წელს დიდი ფლოტით უპასუხებს.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["ტუნისის დაკარგვა კარლ V-ის სასარგებლოდ", "a691f0f8"], "d": ["კარლ V-მ გენუისა და პაპის ფლოტებით გამაგრებული დიდი ლაშქრობით ჰალკ ალ-უადის აღების შემდეგ ტუნისი დაიპყრო და მულაი ჰასანი ესპანეთის მფარველობის ქვეშ ტახტზე აღადგინა. ქალაქში ესპანური გარნიზონი ჩააყენეს და ცენტრალურ ხმელთაშუა ზღვაში ოსმალთა წინსვლა დროებით შეაჩერეს. ტუნისის საბოლოო დაპყრობა მხოლოდ ორმოცი წლის შემდეგ, 1574 წელს, გახდება შესაძლებელი.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["გაზი ჰუსრევ ბეის სავას ნაპირების ოპერაცია: ბოსნიის ბროდი და იასენოვაცი", "3740ec83"], "d": ["იაიცესა და ბანია-ლუკის 1528 წელს აღების შემდეგ მდინარე სავას გასწვრივ მდებარე ციხეები ერთხანს კიდევ ჰაბსბურგთა გვირგვინზე დაქვემდებარებულ ხორვატულ-სლავონურ საზღვარზე დარჩა. 1536 წელს მესამედ ბოსნიის სანჯაყბეგად დანიშნულმა გაზი ჰუსრევ ბეიმ იმავე წელს პოჟეგა და მისი შემოგარენი აიღო და სავას ნაპირას მდებარე ბროდისა და იასენოვაცის ციხეებიც ოსმალურ მმართველობას შეუერთა. ამგვარად, ბოსნიის ჩრდილოეთი საზღვარი სავას მიადგა; მხარის დაპყრობა ორი წლის შემდეგ დუბიცის აღებით დასრულდა.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["მაკბულ იბრაჰიმ-ფაშას სიკვდილით დასჯა", "348aa7b8"], "d": ["ცამეტი წლის განმავლობაში დიდი ვეზირი, კანუნის უახლოესი მეგობარი და სახელმწიფოს ფაქტობრივი მეორე პირი იბრაჰიმ-ფაშა იფტარზე მიწვეულ სასახლეში, ყოველგვარი საბაბის დასახელების გარეშე, დახრჩობით სიკვდილით დასაჯეს. მის სიკვდილში გავლენიანად მიიჩნევა ორი ერაყის ლაშქრობაში მისი საქციელი, „სერასქერ სულთნის“ ტიტულის გამოყენება და სასახლის შიდა ძალთა ბალანსი. ეს სიკვდილით დასჯა გარდამტეხი მომენტია, რომელიც აჩვენებს, რომ ოსმალეთის ცენტრალურ მმართველობაში დიდ ვეზირებს აბსოლუტური უსაფრთხოება არ გააჩნდათ.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["კლისის ციხის აღება და დალმაციის სანჯაყის დაარსება", "6ffd4ebf"], "d": ["გაზი ჰუსრევ ბეის ქეთხუდამ, ხორვატული წარმოშობის გამუსლიმებულმა მურად ბეიმ, სპლიტის უშუალოდ ჩრდილოეთით მდებარე სტრატეგიული კლისის ციხე ვენეციას წაართვა. დაპყრობისთანავე კლისი მისი შემოგარენის მომცველი ახალი სანჯაყისა და კაზის ცენტრად აქციეს; ამ სანჯაყის საზღვრებმა დიდწილად ოსმალური ხორვატიის ჩარჩო მოხაზა. კნინიდან თხუთმეტი წლის შემდეგ მომხდარმა ამ დაპყრობამ დალმაციის შიდა ნაწილის ადმინისტრაციული ჩონჩხი დაასრულა.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["კორფუს ალყა და ომი ვენეციასთან", "11af95bd"], "d": ["აპულიის ლაშქრობის შემდეგ ოსმალურმა ჯარმა კორფუზე ჯარისკაცები გადასხა და კუნძულის ძლიერ ვენეციურ ციხეს ალყა შემოარტყა. ციხის ციცაბო აგებულების, მძიმე დანაკარგებისა და სეზონური პირობების გამო 6 სექტემბერს ბლოკადა მოხსნეს და უკან დაიხიეს. მიუხედავად იმისა, რომ ალყა უშედეგო გამოდგა, ვენეციასთან გაჩაღებული ომი ეგეოსისა და ადრიატიკის მრავალი კუნძულის ოსმალეთთან შეერთებით და მომდევნო წელს პრევეზის გამარჯვებით დასრულდა.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["ბარბაროსის ეგეოსის ლაშქრობა: ვენეციის პირდაპირ მართული კუნძულების აღება", "1b32ed96"], "d": ["კორფუს ალყიდან დაბრუნებულმა ფლოტმა, ვენეციისთვის ომის გამოცხადებით ისარგებლა და ეგეოსში საჰერცოგოს კი არა, პირდაპირ ვენეციაზე დაქვემდებარებული კუნძულები სათითაოდ ჩაიბარა. ეგინა სასტიკი წინააღმდეგობის შემდეგ აიღეს, ქვერინების ოჯახის ხელში მყოფი ასტიპალეა და კარპათოსი და კასოსი დანებდნენ, მონასტრის მმართველობაში მყოფი პატმოსიც ოსმალთა მფარველობაზე დათანხმდა. ნაქსოსის საჰერცოგო კი ხარკის გადამხდელად აქციეს და ადგილზე დატოვეს; მისი ანექსია 1566 წელს მოუწევდა ლოდინი.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["ბარბაროსის ჩრდილოეთ ეგეოსის ლაშქრობა: სკიროსისა და ჩრდილოეთი სპორადების აღება", "20ab688e"], "d": ["პრევეზისკენ მიმავალ გზაზე ფლოტმა სათითაოდ ჩაიბარა სტამბოლის აღების შემდეგ ვენეციისთვის შეფარებული ჩრდილოეთ ეგეოსის კუნძულები. ამგვარად, ოსმალურ მმართველობაში შევიდა ევბეის ჩრდილოეთით მდებარე სკიროსი და სალონიკის ყურის შესასვლელის მაკონტროლებელი სკიათოსი, სკოპელოსი და ალონისოსი. ამ კუნძულებმა დახურა ჩრდილოეთ ეგეოსის უკანასკნელი ხარვეზი, რომელიც, მიუხედავად ევბეის 1470 წელს აღებისა, კიდევ სამოცდარვა წელი ვენეციის ხელში რჩებოდა.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["ადენის აღება და იემენის სანაპიროს ანექსია", "e7d46d8f"], "d": ["ინდოეთის ლაშქრობისთვის სუეციდან გასული ფლოტი, რადგან წითელი ზღვის უზრუნველყოფის გარეშე ოკეანეში გასვლა შეუძლებელი იყო, ჯერ იემენის სანაპიროსკენ გაემართა. ხადიმ სულეიმან-ფაშა 1538 წლის 3 აგვისტოს ადენის ნავსადგურში შევიდა; პორტუგალიელებისკენ მიდრეკილი ტაჰირიანი მმართველი ამირ ბ. დაუდი კაპიტნის კართან მოიყვანეს და სიკვდილით დასაჯეს, ქალაქში კი 500-კაციანი გარნიზონი დატოვეს. იმავე ლაშქრობისას მოხა და სრუტეზე გაბატონებული ქამარანისა და ფარასანის კუნძულებიც ჩაიბარეს და იემენის საბეგლარბეგოს საფუძველი ჩაიყარა. ამგვარად, ოსმალეთის სახელმწიფო პირველად ფლობდა ბაბ ალ-მანდაბის მთელ ჩრდილოეთ სანაპიროს; სანა და შიდა მხარეები კი კიდევ ცხრა წელი უნდა დალოდებოდნენ.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["მოლდოვის ლაშქრობა და ბუჯაკის (ბენდერის) მხარის ანექსია", "90a88a56"], "d": ["ოსმალეთის წინაშე ვალდებულებების შეუსრულებელი მოლდოვის ვოევოდა პეტრუ რარეშის წინააღმდეგ მოწყობილ ლაშქრობაში სუჩავა აიღეს, ქალაქი იასი კი ყირიმის ხან საჰიბ გირაიმ გაძარცვა. ფადიშაჰმა სავოევოდო კალიასებრ სტეფანეს გადასცა და ბენდერი ბუჯაკის (სამხრეთ ბესარაბიის) მხარესთან ერთად პირდაპირ ოსმალეთის მიწებს შეუერთა. ეს ანექსია ერთ-ერთი რგოლი გახდა იმ ჯაჭვისა, რომელმაც შავი ზღვის ჩრდილო-დასავლეთი სანაპიროები ოსმალურ შიდა ზღვად აქცია. მოლდოვა ისედაც ოსმალეთზე დაქვემდებარებული სავოევოდო იყო; ამ ლაშქრობამ მიწა უცხო სახელმწიფოს კი არ წაართვა, არამედ მხოლოდ ბენდერისა და ბუჯაკის შიდა მმართველობა ვოევოდას ჩამოართვა და პირდაპირ ფადიშაჰს დაუქვემდებარა; სავოევოდოს დანარჩენმა ნაწილმა დაქვემდებარებული სტატუსი შეინარჩუნა. იგივე სტრუქტურა 1484 წელს ქილიასა და აკერმანში, 1713 წელს კი ხოტინშიც განმეორდა: სასაზღვრო ციხეები უშუალო დაქვემდებარებაში, შიდა მიწები კი ვასალური.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["ნაფპლიონის (ანაბოლუს) ხელშეკრულებით ჩაბარება", "104d0937"], "d": ["პრევეზის შემდეგ სამი წელი გაგრძელებული ვენეციასთან ომი რესპუბლიკის მიერ მორეაში მისი უკანასკნელი ორი ციხის დათმობაზე დათანხმებით დასრულდა. ალყით ვერაღებული ნაფპლიონი და მონემვასია, სამას ათასი დუკატის საომარ კონტრიბუციასთან ერთად, მოლაპარაკების მაგიდასთან გადასცეს ოსმალეთს. ამგვარად, მორეის ნახევარკუნძული ისე გაერთიანდა, რომ ვენეციის არც ერთი ნაფეხური აღარ დარჩა.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["სეგედის ოსმალურ მმართველობაში შესვლა და სეგედის ლივას შექმნა", "019aa000"], "d": ["1541 წელს ბუდაში ოსმალური მმართველობის სრულად დამყარების შემდეგ სეგედის წარჩინებულებმა ფერდინანდ I-ის ბატონობა აღიარეს და შეიარაღებული თავდაცვისთვის მოემზადნენ. ბუდის ბეგლარბეგმა ქუჩუქ ბალი-ფაშამ 1543 წლის დასაწყისში ქალაქის მმართველები თავისთან მოახმობინა და ღალატის ბრალდებით სიკვდილით დაასჯევინა, შემდეგ კი ქალაქის დასაკავებლად ნაწილი გაგზავნა. ამ დროს სეგედის ლივა შეიქმნა და მის პირველ სანჯაყბეგად ბალი-ფაშას ვაჟი დერვიშ ბეი დანიშნეს; ლივა თავდაპირველად დუნაი-ტისის შუამდინარეთში ვრცელდებოდა.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["ვალპოს, შიკლოშისა და პეჩის აღება", "2ca030a3"], "d": ["ბუდის ანექსიიდან ორი წლის შემდეგ წამოწყებული უნგრეთის ლაშქრობის პირველი მიზანი ახალი ეიალეთის დრავასა და დუნაის შორის მდებარე სამხრეთ ფრთის უზრუნველყოფა იყო. ვალპოსა და შიკლოშის ციხეების აღების შემდეგ ბარანიის ცენტრი პეჩი დანებდა. ქალაქი ოსმალური უნგრეთის ყველაზე ხალხმრავალ და ყველაზე მეტად აშენებულ ცენტრად იქცეოდა და ისტორიკოსი იბრაჰიმ ფეჩუილი სახელს აქედან მიიღებდა.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["ესტერგომისა და სეკეშფეჰერვარის (ისტოლნი ბელგრადის) აღება", "efca9e05"], "d": ["უნგრეთის ლაშქრობაში, რომელშიც კანუნი თავად გაემართა, ორკვირანახევრიანი ალყის შემდეგ უნგრეთის სამეფოს რელიგიური ცენტრი და არქიეპისკოპოსის ქალაქი ესტერგომი ოსმალთა მმართველობაში შევიდა. შემდეგ უნგრელი მეფეების კურთხევის ქალაქი სეკეშფეჰერვარიც აიღეს და ბუდის ეიალეთის თავდაცვითი სარტყელი დაასრულეს. ესტერგომი 1595 წლამდე, როგორც დუნაის ხაზის საკვანძო ციხე, ოსმალთა ხელში დარჩებოდა.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["ბუდის ჩრდილოეთი და დასავლეთი თავდაცვითი სარტყელი: ვაცი, ჰატვანი და შიმონტორნია", "733ee5ce"], "d": ["ესტერგომისა და სეკეშფეჰერვარის აღების შემდეგ ბუდის ბეგლარბეგი დედაქალაქის გარშემო ციხეების რგოლის დასასრულებლად ფადიშაჰის ლაშქრობის გარეშე ამოქმედდა. დუნაის მუხლზე მდებარე ვაცი, ალფოლდის კარი ჰატვანი და შიოს ხაზზე მდებარე შიმონტორნია სათითაოდ ჩაიბარეს. ამ ჩუმი წლის მონაპოვრებმა ბუდა სასაზღვრო ქალაქიდან ას ორმოცი წელი გამძლე ეიალეთის ცენტრად აქცია.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["ბასრის ანექსია და სპარსეთის ყურეში გასვლა", "02f87c11"], "d": ["ბაღდადის აღებისას (1534) ბასრის მმართველმა რაშიდ ბ. მეგამისმა კანუნის მორჩილება აცნობა და 1538 წელს ქალაქის გასაღებები გაუგზავნა. მისი შემცვლელი შეიხ იაჰია ოსმალებს დაუპირისპირდა, ამიტომ ბაღდადის ბეგლარბეგი აიას-ფაშა ხმელეთით, მოსულის სანჯაყბეგი კი 120 ხომალდით ევფრატის გასწვრივ გაემართნენ; აიას-ფაშა 1545 წლის 26 დეკემბერს ბასრაში შევიდა და ქალაქი საბეგლარბეგოს ცენტრად იქცა. შატ ალ-არაბის შესართავთან მდებარე ეს ნავსადგური იყო კარი, რომლითაც ოსმალეთი გავიდა პორტუგალიის მიერ ჰორმუზიდან კონტროლირებად ყურეში; 1555 წლის ამასიის ზავით ეს მდგომარეობა ირანმაც აღიარა.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["სანასა და იემენის შიდა მხარეების აღება", "d31ded85"], "d": ["ტაიზის შემდეგ სანაც აიღეს და მთელი ქვეყანა საბეგლარბეგოს დაუქვემდებარეს. თუმცა ციცაბო გეოგრაფიისა და მაზჰაბური განსხვავების გამო ეს ბატონობა არასოდეს ყოფილა მშვიდი; იემენი ოსმალებისთვის ჯარისკაცების მუდმივად გადამყლაპავ ფრონტად იქცა.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["ტაიზის აღება", "d4509df9"], "d": ["იემენში, სადაც ცხრა წლის წინ მხოლოდ სანაპირო ზოლით დაკმაყოფილდნენ, ზეიდიტი იმამების მთიან შიდა მხარეში თანდათან გაძლიერების გამო ოზდემირ-ფაშას ძალებმა მთიანეთზე ასვლით ტაიზი დაიკავეს.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["სტამბოლის ზავი — ჰაბსბურგებთან ხუთწლიანი ზავი", "41f81773"], "d": ["ოსმალეთსა და ჰაბსბურგებს შორის ხუთი წლის ვადით ზავი დაიდო; ფერდინანდმა მის ხელში მყოფი უნგრული მიწებისთვის ყოველწლიურად 30.000 დუკატის გადახდა იკისრა. ზავმა სამართლებრივად დააფიქსირა უნგრეთის სამად გაყოფილი ფაქტობრივი მდგომარეობა. დასავლეთის ფრონტის ასე დაცვამ კანუნის ირანის წინააღმდეგ ახალი ლაშქრობების მოწყობის საშუალება მისცა.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["მეორე ირანული ლაშქრობა და თავრიზის ხელახალი აღება", "e82365df"], "d": ["შაჰ თამაზის წინააღმდეგ აჯანყებულმა და სტამბოლში შეფარებულმა მისმა ძმამ ელკას მირზამ წააქეზა ლაშქრობა, რომლის დროსაც ჯარი მეორედ შევიდა თავრიზში. რადგან სეფიანები კვლავ საველე ბრძოლაში არ ჩაებნენ და მიწის გადაწვით უკან იხევდნენ, ქალაქში მხოლოდ რამდენიმე კვირა შეძლეს დარჩენა. ლაშქრობამ საბოლოოდ დაადასტურა, რომ თავრიზის შენარჩუნება შეუძლებელი იყო, და ოსმალური სტრატეგია მუდმივი სასაზღვრო ხაზის შექმნისკენ, ანუ ვანის გამაგრებისკენ, მიმართა.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["ვანის აღება და აღმოსავლეთის საზღვრის დაფიქსირება", "fc8f930b"], "d": ["თავრიზიდან დაბრუნებისას ალყაში მოქცეული ვანის ციხე, ტბის აღმოსავლეთ სანაპიროზე, კლდეზე აღმართული მდებარეობით, რეგიონის უდავო საკეტი იყო და ხანმოკლე ალყის შემდეგ დანებდა. ქალაქი დაუყოვნებლივ საბეგლარბეგოს ცენტრად აქციეს; ერჯიშის, ადილჯევაზისა და ჰაქიარის სანჯაყები მას დაუქვემდებარეს. თავრიზისგან განსხვავებით ვანი შეინარჩუნეს და ოთხასი წლის განმავლობაში იგი ოსმალთა ყველაზე მოწინავე მუდმივ პოზიციად დარჩა აღმოსავლეთში.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["ლაჰსასა და ქატიფის ანექსია — ყურის არაბეთის სანაპირო", "f6701e60"], "d": ["ბასრის აღების შემდეგ ყურის დასავლეთ სანაპიროზე პორტუგალიის წინა ფორპოსტად ქცეული ქატიფი აიღეს და შიდა მხარის ლაჰსას ოაზისებთან ერთად ახალი საბეგლარბეგო დაარსეს. ბაჰრეინისა და ჰორმუზისკენ მიმართული ოპერაციების ამოსავალი წერტილი აქ იყო. ამგვარად, ოსმალეთის სახელმწიფო ერთდროულად როგორც წითელი ზღვის, ისე სპარსეთის ყურის სანაპიროებზე გახდა გადამწყვეტი ხმის მქონე არაბეთის ნახევარკუნძულზე.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["შეჰრიზორის ხელიდან გასვლა — არდალანის ბეი სუჰრაბი სეფიანებისკენ გადაიხარა", "5600efc9"], "d": ["ორი ერაყის ლაშქრობისას (1535) ოსმალური მმართველობის აღიარებული შეჰრიზორის მხარე ზალმის ციხეში მჯდომი არდალანის ამირის ბიგე ბეის მმართველობის ქვეშ იყო. 1550 წელს ბიგე ბეის გარდაცვალების შემდეგ ზალმის ციხის ხელში ჩამგდები და საბეილიქოზე გაბატონებული მისი ძმა სუჰრაბი სეფიანებისკენ გადაიხარა და ოსმალებისადმი მორჩილებას გამოეყო; შეჰრიზორის მხარე ამგვარად ოსმალური გავლენიდან გამოვიდა. მხარე მხოლოდ ნახიჭევანის ლაშქრობისას, 1554 წელს, ზალმის ციხის ალყით აღების შემდეგ დაიბრუნეს.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["არდაჰანისა და ჩილდირის აუზის აღება", "14c9eb76"], "d": ["ერზურუმის ბეგლარბეგმა სეფიანებთან მიმდინარე ომის დროს ქართველი ათაბაგების მტკვრის რკალში მდებარე მიწებისკენ გაილაშქრა და არდაჰანი და ჩილდირის შემოგარენი ოსმალთა მმართველობას დაუქვემდებარა. ამგვარად, ყარს-არდაჰანის ხაზი გაერთიანდა და ჩრდილო-აღმოსავლეთში საქართველოსკენ გახსნილი მთიანეთი კონტროლქვეშ მოექცა. მხარის საბოლოო ადმინისტრაციული წყობა ოცდაშვიდი წლის შემდეგ დაარსებული ჩილდირის ეიალეთით დასრულდებოდა.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["სოქოლუ მეჰმედ-ფაშამ დუნაი გადალახა — ტრანსილვანიის ომის დაწყება", "38fde931"], "d": ["ტრანსილვანიის პატარა მეფის იანოშ ჟიგმონდის მეურვის, ბერ მარტინუცის მიერ გამოწვეული არეულობებისა და ტრანსილვანიის მიერ ბანატის ციხეების ფერდინანდისთვის დათმობის გამო ახალი ლაშქრობა საჭიროდ ჩაითვალა; სარდლობა რუმელიის ბეგლარბეგ სოქოლუ მეჰმედ-ფაშას მიეცა. ჯარმა, მარტინუცის დროის გაყვანის მცდელობების მიუხედავად, დუნაი გადალახა და ბეჩე, ბეჩქერეკი, ჩანადი და ლიპა აიღო; მაგრამ ტიმიშოარას ალყა 16 ნოემბერს სიცივის გამო მოხსნეს. ამგვარად, უნგრეთში ახალი ოსმალეთ-ჰაბსბურგების ომი გაჩაღდა.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["ქალაქი ლიპოვა (ლიპა) კასტალდოს ავსტრიული ჯარის ხელში გადავიდა — ციხე 5 დეკემბერს დანებდა", "a0e1ff0d"], "d": ["ლიპოვას, რომელიც სოქოლუ მეჰმედ-ფაშამ 1551 წლის ოქტომბერში აიღო, გენერალ კასტალდოს ჯარმა 4 ნოემბერს ალყა შემოარტყა; ორი დღის შემდეგ ქალაქი ავსტრიელების ხელში გადავიდა. ულამა-ფაშამ 5000-კაციანი გარნიზონით ციხე კიდევ ცხრა დღე დაიცვა და 1551 წლის 5 დეკემბერს შეთანხმებით გავიდა. 1552 წელს ტემეშვარის დაცემამდე ლიპოვა ჰაბსბურგების ხელში დარჩა.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["ტიმიშოარიდან გაგზავნილი ძალების მიერ სამხრეთ ბანატის პალანკების დაკავება — ვერშეცი, ჰარამი, კევე", "edca0921"], "d": ["ტიმიშოარას ოსმალურ ჯარზე ჩაბარების შემდეგ ალყის ჯარისგან გამოყოფილი ნაწილები ბანატის პატარა პალანკებისკენ გაემართნენ; ბანლაკის თხრობით, ვერშეცის, ფაჩეტის, მეჰადიის, ჩაკოვარის, ჰარამვარისა და კევეს პალანკები ამ ძალებმა დაიკავეს. ამგვარად, დუნაის ნაპირას მდებარე ჰარამიც ოსმალთა ხელში გადავიდა.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["სოლნოკის აღება და ეგერის ალყის მარცხი", "a7156e8f"], "d": ["ტიმიშოარას აღების შემდეგ გაერთიანებულმა ორმა ოსმალურმა ჯარმა ტისაზე მდებარე სოლნოკი თითქმის უბრძოლველად აიღო, რადგან დაქირავებულმა მცველებმა ციხე მიატოვეს. შემდეგ ალყაში მოქცეული ეგერის ციხე კი იშტვან დობოს სარდლობით ორიათასიანი გარნიზონის ოცდათვრამეტდღიანი წინააღმდეგობის წინაშე ვერ აიღეს და ზამთრის დადგომისას ჯარი უკან გაბრუნდა. იმავე ლაშქრობაში ერთი ციხის ადვილად დაცემა და მეორის გამაგრება იყო პირველი აშკარა ნიშანი იმისა, რომ უნგრეთში საზღვარი ოსმალთა სასარგებლოდ თავისით აღარ მიიწევდა.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["ოსმალურ-ფრანგული კავშირი — ფრანგული ფლოტის ოსმალთა დაქვემდებარებაში გადასვლა", "a8e01b22"], "d": ["1553 წლის 1 თებერვლის ხელშეკრულებით საფრანგეთის ფლოტი ოსმალური ფლოტის დაქვემდებარებაში გადაეცა; გათვალისწინებული იყო ესპანეთის წინააღმდეგ დასავლეთ ხმელთაშუა ზღვაში ერთობლივი ოპერაციები. ხელშეკრულების შემდეგ თურგუთ რეისი 1553 წლის 15 ივნისს ორმოცდახუთი გალერით საფრანგეთის დასახმარებლად გაემართა ლაშქრობაში. ეს იყო პირველი ოფიციალური სამოკავშირეო ხელშეკრულება, რომელმაც 1536 წლის კაპიტულაციების სავაჭრო საფუძველი სამხედრო თანამშრომლობად აქცია.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["შაჰზადე მუსტაფას სიკვდილით დასჯა კონიის ერეღლიში", "dec36858"], "d": ["ნახიჭევანის ლაშქრობისთვის შეკრებილ ჯარში გასაწევრიანებლად მამის კარავში შესული შაჰზადე მუსტაფა, წინაშე წარდგომის წინ, ჯალათებს გადაეყარა და დახრჩობით მოკლეს. ჯარში დიდი სიყვარულით სარგებლობდა ეს ტახტის მემკვიდრეობის კანდიდატი, და მისმა მკვლელობამ იანიჩარებში ღრმა რისხვა გამოიწვია; რუსთემ-ფაშა დიდ ვეზირობიდან გადააყენეს. მოვლენა, როგორც ოსმალური შაჰზადეების პოლიტიკის ერთ-ერთი ყველაზე სადავო გარდამტეხი მომენტი, ლიტერატურასა და ხალხის მეხსიერებაში შევიდა.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["იბრიმი და ნუბიის საზღვრის სამხრეთისკენ გადატანა", "c57d5d77"], "d": ["ეგვიპტის საბეგლარბეგოს სამხრეთი საზღვარი ნილოსზე კლდოვან კონცხზე აღმართული იბრიმის ციხის ოზდემირ ბეის ხელით გამაგრებითა და ქვემო ნუბიის ოსმალურ ეგვიპტესთან სრული შეერთებით მეორე ჩანჩქერის იქით გადაიტანეს. (იბრიმში ოსმალური ადმინისტრაციული ორგანიზაცია ეგვიპტის დაპყრობის შემდეგ შეიქმნა; რუკაზე იბრიმი 1517 წლიდან ოსმალურად ნაჩვენებია. ეს წელი მიახლოებითია, წყარო წელს არ ასახელებს.) ციხე ნუბიიდან მომავალი თავდასხმების წინააღმდეგ ზღუდე და, ასევე, სენარისკენ მიმავალი ოქროსა და მონების გზის საკონტროლო პუნქტი იყო. აქ დაბანაკებული ბოსნიელი მცველთა ნაწილი ისე დამკვიდრდა, რომ მათი შთამომავლები სამასი წლის შემდეგაც ციხეში იმყოფებოდნენ. იბრიმის ოსმალურ მმართველობაში შესვლის დროზე წყაროები ორ განსხვავებულ თხრობას გვაწვდის: TDV-ის სუდანის სტატია ქვემო ნუბიის ოსმალურ ეგვიპტესთან შეერთებას XVI საუკუნის შუა ხანებში ოზდემირ-ფაშას ოპერაციას უკავშირებს, ნუბიის სტატია კი წერს, რომ ჰალფას ხეობამდე მხარე და იბრიმის ადმინისტრაციული ორგანიზაცია 1517 წლის დაპყრობის შემდეგ დაუყოვნებლივ შეიქმნა. იბრიმის სანჯაყი 1573 წლის 26 ივლისს ჰაბეშის ეიალეთს დაუქვემდებარეს.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["ბეჯაიას (Bougie) აღება ესპანელებისგან", "49691cda"], "d": ["ორმოცდასამი წელი ესპანეთის ხელში მყოფი და ალჟირსა და კონსტანტინას შორის სანაპიროს ორად გამყოფი ბეჯაია ხმელეთიდან და ზღვიდან ალყის შემდეგ დანებდა. ციხის დაცემით ალჟირის ოჯაღის სანაპირო ორანამდე შეუწყვეტელი გახდა. ესპანეთში ამ დანაკარგმა ისეთი დიდი აღშფოთება გამოიწვია, რომ ციხის ჩამბარებელი მეთაური ალონსო დე პერალტა სამშობლოში სიკვდილით დასაჯეს.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["ზეილას ჰაბეშის ეიალეთში შესვლა", "7bbf369a"], "d": ["ჰაბეშის ეიალეთის სამხრეთ კიდეზე, ადენის ყურის აფრიკულ სანაპიროზე მდებარე ზეილას ნავსადგური ოსმალურ მმართველობას დაუქვემდებარეს. ადალის სასულთნოს ზღვაზე გასასვლელი ეს ქალაქი ბაბ ალ-მანდაბის გარეთ გასული ხომალდებისთვის უკანასკნელი მომარაგების პუნქტი იყო. ზეილას შეერთებით ოსმალეთის სახელმწიფოს აფრიკული საზღვარი უკიდურეს სამხრეთ წერტილს მიაღწია.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["კონიის შაჰზადეთა ბრძოლა", "1c8de387"], "d": ["ტახტისთვის ბრძოლაში ჩაბმული შაჰზადე ბაიაზიდი დაახლოებით 30.000-კაციანი ძალით კონიის მისადგომებთან მივიდა და ორდღიან შეტაკებაში ძმას, შაჰზადე სელიმს, დაუმარცხდა. დამარცხებულმა ბაიაზიდმა ამასიის გავლით ირანში, შაჰ თამაზთან, შეაფარა თავი. ბრძოლამ კანუნის ბოლო წლებში ტახტის მემკვიდრეობის კრიზისი საგარეო პოლიტიკის პრობლემად აქცია.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["ჯერბის საზღვაო გამარჯვება", "c7b905c1"], "d": ["ფიალე-ფაშას სარდლობით ოსმალურმა ფლოტმა ტრიპოლის დასაბრუნებლად შეკრებილი ესპანურ-გენუურ-მალტური მოკავშირე ესკადრა ჯერბის სანაპიროებთან ორად გაყოფის მანევრით დაფანტა. მოკავშირეებმა ფლოტის დიდი ნაწილი დაკარგეს, კუნძულის ციხეც მალე დაეცა. ჯერბა პრევეზის შემდეგ ხმელთაშუა ზღვაში ოსმალთა უპირატესობის განმამტკიცებელ მეორე დიდ საზღვაო გამარჯვებად მიიჩნევა.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["შაჰზადე ბაიაზიდის სიკვდილით დასჯა ყაზვინში", "a759de14"], "d": ["ირანში შეფარებული შაჰზადე ბაიაზიდი ხანგრძლივი მოლაპარაკებების შემდეგ შაჰ თამაზმა ოსმალურ დელეგაციას გადასცა და ოთხ ვაჟთან ერთად დახრჩობით მოკლეს. გადაცემის სანაცვლოდ სეფიანებმა მნიშვნელოვანი მატერიალური დათმობები და საზღვრის გარანტია მიიღეს. ამ სიკვდილით დასჯით სელიმ II-ის გამეფების გზაზე ბოლო დაბრკოლება მოიხსნა და ამასიის ზავის სამშვიდობო წესრიგი შენარჩუნდა.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["ქიოსის აღება გენუელებისგან", "a4559b96"], "d": ["ორასი წლის განმავლობაში გენუის ჯუსტინიანების ოჯახის სავაჭრო კოლონიის სახით მართული და ოსმალებისთვის ხარკის გადამხდელი ქიოსი, ხარკის დაგვიანებისა და მტრის ხომალდებისთვის ნავსადგურის მიცემის საბაბით, ფიალე-ფაშამ ერთი ტყვიის გასროლის გარეშე ჩაიბარა. ქიოსთან და ფსარასთან ერთად ეგეოსის აღმოსავლეთ სანაპიროზე გენუის უკანასკნელი ყოფნაც მოისპო. ქიოსელთა მასტიკის წარმოება და პრივილეგიები შენარჩუნდა და კუნძული თეთრი ზღვის არქიპელაგის (Cezâyir-i Bahr-i Sefîd) ეიალეთს დაუქვემდებარეს.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["ნაქსოსის საჰერცოგოს ანექსია — მთელი კიკლადები", "68f0ec0b"], "d": ["1207 წლიდან არსებული და 1537 წლიდან ოსმალებისთვის ხარკის გადამხდელი ლათინური ნაქსოსის საჰერცოგო უკანასკნელი ჰერცოგის ჯაკომო კრისპოს მიერ თავისი ხალხის ჩაგვრის შესახებ შემოსული საჩივრების საბაბით გააუქმეს. ნაქსოსი, პაროსი, მილოსი, ანდროსი, სიროსი, მიკონოსი, იოსი, ანაფე და მათ გარშემო მყოფი კიკლადების ყველა კუნძული ერთი გადაწყვეტილებით პირდაპირ ოსმალურ მმართველობაში აიყვანეს. კანუნიმ კუნძულების მმართველობა ერთხანს იოსებ ნასის გადასცა; ამგვარად, ეგეოსის შუაგულში სამსაუკუნენახევრიანი ლათინური ბატონობა დასრულდა.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["იემენის აჯანყება და ქოჯა სინან-ფაშას იემენის ლაშქრობა", "c8218d8e"], "d": ["ზეიდიტი იმამი მუთაჰარი, გადასახადების ძალით აკრეფის საბაბით, აჯანყდა და ოსმალური მმართველობა იემენის დიდი ნაწილიდან განდევნა. სტამბოლიდან გაგზავნილმა ქოჯა სინან-ფაშამ 1568-1570 წლებში წარმოებული ოპერაციებით, ხანგრძლივი ალყის შემდეგ ქევქებანი აიღო და რეგიონში ოსმალთა ბატონობა აღადგინა. ლაშქრობას სასიცოცხლო მნიშვნელობა ჰქონდა წითელი ზღვის სამხრეთი კარისა და ინდოეთის ოკეანის სავაჭრო გზის კონტროლის შესანარჩუნებლად.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["თავდაცვითი კავშირი აჩეს სასულთნოსთან და დახმარება ინდოეთის ოკეანეში", "8e835f24"], "d": ["პორტუგალიის თავდასხმების გამო კანუნისგან დახმარების მთხოვნელმა აჩეს ელჩებმა, ფადიშაჰის სიგეტვარში გარდაცვალების შემდეგ, ერთგულება სელიმ II-ს გამოუცხადეს და მასთან თავდაცვითი ხელშეკრულება დაიდო. ფადიშაჰმა ბრძანა, ალექსანდრიიდან ქვემეხები, თოფები, საბრძოლო მასალა და ოსტატები გაეგზავნათ; ინდოეთის წყლებში გასაგზავნად ჩვიდმეტი საბრძოლო ხომალდი მოამზადეს. იემენის აჯანყების გაფართოებამ ესკადრის გასვლა შეაფერხა, მაგრამ აჩეში მისულმა ოსმალმა მეზარბაზნეებმა და ოსტატებმა რეგიონში მუდმივი კვალი დატოვეს.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["კვიპროსის დესანტი: ლიმასოლის აღება", "9074ccc9"], "d": ["კუნძულზე გადმოსულმა ოსმალურმა ჯარმა დიდი წინააღმდეგობის გარეშე აიღო ლიმასოლი და მომდევნო დღეს ლარნაკისკენ გაემართა. ადგილობრივი მოსახლეობის ვენეციური მმართველობით უკმაყოფილებისა და ოსმალური ძალებისთვის დახმარების წყალობით ლარნაკაშიც სერიოზული წინააღმდეგობა არ შეხვდათ; ტუზლას ნავსადგური ჯარისა და აღჭურვილობის გადმოსხმის ბაზად აქციეს. ვენეციას თავდაცვა ნიქოზიასა და ფამაგუსტაში ჰქონდა თავმოყრილი; პაფოსის მმართველმა სერდარს მორჩილება მხოლოდ ნიქოზიის დაცემის შემდეგ აცნობა.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["ნიქოზიის აღება", "413d866b"], "d": ["1570 წლის 25 ივლისს დაწყებული და ორმოცდახუთდღიანი ალყის შემდეგ კვიპროსის ვენეციური მმართველობის დედაქალაქი ნიქოზია ოსმალურ ჯარს დანებდა. კუნძულის ცენტრის დაცემამ ვენეციური წინააღმდეგობა ფამაგუსტის ციხეში მომწყვდია. დაპყრობამ დასავლეთში დიდი გამოძახილი გამოიწვია და დააჩქარა პროცესი, რომელიც პაპის ინიციატივით წმინდა ლიგის ფლოტის შექმნამდე მიდიოდა.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["კირენიის ჩაბარება — კვიპროსის ჩრდილოეთ სანაპირო", "39fdeea5"], "d": ["9 სექტემბერს ნიქოზიის ხმლით ამოწყვეტით დაცემამ კვიპროსის ჩრდილოეთში წინააღმდეგობა გატეხა. ხუთთითა (ბეშფარმაქის) მთების უკან მდებარე კირენიის ციხემ, დედაქალაქის ბედის გაგების შემდეგ, რვა დღის შემდეგ პირობით დანებდა და მის გარნიზონს კუნძულიდან გასვლის ნება დართეს და გაუშვეს. კუნძულზე ვენეციური დროშა მხოლოდ ფამაგუსტაში დარჩა; იგიც კიდევ თერთმეტი თვე გაძლებდა.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["ფლოტის ხელახალი აშენება ლეპანტოს შემდეგ", "db51fe44"], "d": ["ლეპანტოს მარცხის შემდეგ კაპუდან-ფაშად დანიშნული ქილიჩ ალი-ფაშას პირველი საქმე მძიმედ დაზარალებული ფლოტის ხელახლა შექმნა იყო; გემთსაშენები 1571-1572 წლების მთელი ზამთრის განმავლობაში შეუსვენებლად მუშაობდა. 1572 წლის ივნისში დაახლოებით 250 გალერისა და 300 მოხალისე რეისის გალერისგან შემდგარი ახალი ესკადრა ხმელთაშუა ზღვაში გავიდა. ამ სწრაფმა გამოჯანმრთელებამ აჩვენა, რომ ლეპანტომ ოსმალური საზღვაო ძალა საბოლოოდ ვერ გატეხა.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["სტამბოლის ზავი ვენეციასთან — კვიპროსის აღიარება", "4d08ef50"], "d": ["წმინდა ლიგის დაშლის შემდეგ მარტო დარჩენილმა ვენეციამ ოსმალეთთან ცალკე ზავი დადო, ოფიციალურად აღიარა, რომ კვიპროსი ოსმალეთს ეკუთვნის, და საომარი კონტრიბუციის გადახდაზე დათანხმდა. ზავმა ნათლად აჩვენა, რომ ლეპანტოს გამარჯვებამ ქრისტიანულ სამყაროს პოლიტიკური სარგებელი ვერ მოუტანა. ამის შემდეგ ვენეცია სამოცდაათი წლის განმავლობაში მოერიდება ოსმალეთთან პირდაპირ ომში ჩართვას.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["სელიმ II-ის გარდაცვალება", "c289f5ee"], "d": ["სელიმ II დაცემის შემდეგ დაახლოებით ორი თვე დივანზე ვეღარ გამოვიდა და გარდაიცვალა. მისი სიკვდილი თორმეტი დღე საიდუმლოდ ინახებოდა სასახლეში, სანამ მანისაში მყოფი უფროსი ვაჟი მურადი სტამბოლში ჩავიდოდა. სიკვდილის დღეზე წყაროები განსხვავდება: სელანიქი 15 დეკემბერს ასახელებს; გერლახი, მეჰმედ ბინ მეჰმედი და ჯენაბი კი 13 დეკემბერს.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["სელიმ II-ის გარდაცვალების გამოცხადება და მურად III-ის ტახტზე ასვლა", "84334d70"], "d": ["სელიმ II-ის გარდაცვალება და მანისიდან ჩამოყვანილი მურად III-ის ტახტზე ასვლა 1574 წლის 22 დეკემბერს ოფიციალურად გამოცხადდა. ახალი ფადიშაჰი ოცდაერთი წელი დარჩება ტახტზე; მისი მმართველობა დამახსოვრდება აღმოსავლეთში ირანთან ხანგრძლივი ომებით, დასავლეთში გრძელი ომის წინა პერიოდით და ქვეყნის შიგნით აკჩეს (ვერცხლის მონეტის) გაუფასურებით. სოქოლუ მეჰმედ-ფაშას 1579 წელს გარდაცვალებამდე სახელმწიფო მმართველობაში ძველი წესრიგი გრძელდებოდა.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["ალ-კასრ ალ-ქაბირის (ვადი ალ-მახაზინის) ბრძოლა — ოსმალთა მხარდაჭერის მქონე აბდ ალ-მალიქმა პორტუგალიური ჯარი გაანადგურა", "21280dac"], "d": ["ოსმალთა მხარდაჭერით მაროკოს ტახტზე ასულმა აბდ ალ-მალიქმა პორტუგალიის მეფე სებასტიანის დიდი ჯარი ვადი ალ-მახაზინთან გაანადგურა; რადგან ბრძოლაში ერთდროულად სამი მმართველი დაიღუპა, დასავლურ წყაროებში მას „სამი მეფის ბრძოლას“ უწოდებენ. პორტუგალიის სამხედრო ძალა დაინგრა და ქვეყანა მალე ესპანეთის ხელში გადავიდა. აბდ ალ-მალიქიც ბრძოლაში დაიღუპა; მისმა მემკვიდრე ძმამ აჰმად ალ-მანსურმა გამარჯვება დელეგაციის საშუალებით სტამბოლს შეატყობინა. ორ სახელმწიფოს შორის ურთიერთობა ხარკის ან ვასალობის კი არა, ელჩებისა და საჩუქრების გაცვლის დონეზე დარჩა და მალე საჩუქრების საკითხის გამო დაიძაბა.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["დარუბანდის მოსახლეობის ლალა მუსტაფა-ფაშასთვის ერთგულების გამოცხადება — რკინის კარი ოსმალთა მმართველობაში", "9c55aeff"], "d": ["შირვანის ლაშქრობისას დარუბანდის მოსახლეობიდან შვიდკაციანი დელეგაცია ერეშში მყოფ სერდარ ლალა მუსტაფა-ფაშასთან მივიდა და ერთგულება გამოუცხადა. კავკასიის კედელსა და კასპიის ზღვას შორის ვიწრო გადასასვლელის ჩამკეტმა დარუბანდმა (რკინის კარმა), როგორც ჩრდილოეთიდან მომავალი სახმელეთო გზების სავალდებულო გასასვლელმა, შირვანის შენარჩუნებაში საკვანძო როლი ითამაშა. ოსმალთა ბატონობა აქ 1607 წლამდე გაგრძელდა.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["შირვანის დაპყრობა: შამახიის აღება", "9afae4c1"], "d": ["ჩილდირის გამარჯვების შემდეგ კავკასიაში გასული ჯარი სეფიანთა კასპიისპირეთის უმდიდრეს ეიალეთ შირვანში შევიდა და ცენტრალური ქალაქი შამახია აიღო. ოზდემიროღლუ ოსმან-ფაშას აქ ბეგლარბეგად დანიშვნით აბრეშუმის გზის ჩრდილოეთი ფრთა ოსმალთა კონტროლქვეშ მოექცა. შირვანი თორმეტი წლის განმავლობაში გაგრძელებული აღმოსავლური ომის ყველაზე ხშირად ხელიდან ხელში გადამსვლელ და ყველაზე ძვირად დამჯდარ ფრონტად იქცეოდა.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["ბაქოს აღება — კასპიის სანაპიროზე გასვლა", "eb5adab8"], "d": ["შირვანის ოპერაციის უკანასკნელი რგოლის სახით კასპიის ზღვის დასავლეთ სანაპიროზე მდებარე ბაქოს ნავსადგური აიღეს. ქალაქის შემოგარენის ნავთობის ჭები იმ დროსაც კი ცნობილი შემოსავლის წყარო იყო, ნავსადგური კი კასპიით მომავალი ირანული აბრეშუმის გასასვლელი პუნქტი იყო. ამგვარად, ოსმალეთის სახელმწიფო თავის ისტორიაში პირველად და ერთადერთხელ გახდა კასპიის ზღვის სანაპიროს მფლობელი.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["ერევნის (რევანის) აღება და ციხის აშენება", "7f623b7b"], "d": ["ყარსში ერევანში წასვლისა და იქ ციხის აშენების ბრძანების მიღების შემდეგ ფერჰად-ფაშა ერევანისკენ გაემართა და ქალაქი ჰიჯრის 991 წლის რამადანის დასაწყისში (1583 წლის სექტემბრის შუა რიცხვებში) ოსმალთა კონტროლქვეშ აიყვანეს. არაქსის ხეობის ჩრდილოეთი კარის მაკონტროლებელ ერევანში ახალი და დიდი ციხე აშენდა; ქალაქი საბეგლარბეგოს ცენტრად აქციეს. ყარსსა და თავრიზს შორის საჯარო გზის შუაში მდგარი ერევანი აღმოსავლეთი ფრონტის ლოგისტიკური ხერხემალი იყო. ციხე ისე მტკიცედ ააშენეს, რომ მომდევნო ორი საუკუნის განმავლობაში ოსმალურ-ირანული ომების უცვლელ სამიზნედ იქცა.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["ყარაბაღისა და განჯის ანექსია", "29abaead"], "d": ["ათწლიანი აღმოსავლური ომის უკანასკნელი შენაძენის სახით ფერჰად-ფაშამ 1588 წელს განჯისკენ გაილაშქრა და 1 სექტემბერს ქალაქში შევიდა; მტკვარსა და არაქსს შორის მდებარე ყარაბაღის მხარე და მისი ცენტრი განჯა ოსმალურ მმართველობაში გადავიდა. ამგვარად, შირვანი, ერევანი და ყარაბაღი გაერთიანდა და კავკასიაში შეუწყვეტელი ოსმალური ხაზი შეიქმნა. 1590 წელს ხელმოწერილი ფერჰად-ფაშას ზავი ამ საზღვარს დააფიქსირებდა, მაგრამ შენაძენის შენარჩუნება მხოლოდ ოცი წელი შეძლეს.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["ბიჰაჩის აღება", "651a7275"], "d": ["ბოსნიის ბეგლარბეგმა თელი ჰასან-ფაშამ, 1591 წლის ნოემბერში ბიჰაჩის წინა ციხის, რიპაჩის, აღების შემდეგ, 1592 წელს თავად ქალაქი და ციხეც აიღო; ათდღიანი ალყის შემდეგ მეთაური ლამბერგი დანებდა. ამ დაპყრობამ ბოსნიის საზღვარი მდინარე უნის გასწვრივ წინ წასწია და ბოლო დიდი ოსმალური შენაძენი გახდა გრძელი ომის წინა პერიოდში, რომელიც ერთი წლის შემდეგ, კულპასთან თელი ჰასან-ფაშას შაჰიდად დაღუპვით, აფეთქდებოდა.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["ოსმალეთ-ავსტრიის „გრძელი ომის“ დაწყება", "bd22c392"], "d": ["ბოსნიის ბეგლარბეგ თელი ჰასან-ფაშას კულპასთან (სისაკთან) დამარცხებისა და შაჰიდად დაღუპვის შემდეგ ოსმალეთის სახელმწიფომ ავსტრიას ომი გამოუცხადა და დაიწყო გრძელი ომი, რომელიც ცამეტი წელი გაგრძელდებოდა. ამ ომმა, რომელშიც ცეცხლსასროლი იარაღით შეიარაღებული ქვეითი ჯარი გადამწყვეტი იყო, ოსმალური ჯარის წყობაში სეკბანებისა და მეთოფე ჯარისკაცების დაქირავება დააჩქარა და თიმარიანი სიპაჰების დაქვეითება გააღრმავა. ომი 1606 წელს ჟიტვატოროკის ზავით დასრულდებოდა.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["ქოჯა სინან-ფაშა ავსტრიის ლაშქრობაში გაემართა — გრძელი ომის პირველი ლაშქრობა", "d4a2f46d"], "d": ["ბოსნიის ბეგლარბეგ ჰასან-ფაშას სისაკთან დამარცხებისა და შაჰიდად დაღუპვის შემდეგ დიდმა ვეზირმა ქოჯა სინან-ფაშამ ბრწყინვალე სიტყვებითა და დაპირებებით ფადიშაჰი ომზე დაიყოლია და 12.000 იანიჩარითა და სხვა ნაწილებით გზას გაუდგა. ამგვარად გაიხსნა ცამეტწლიანი ოსმალეთ-ავსტრიის ომის პირველი ლაშქრობა.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["იანიქქალეს (დიორის) აღება", "14b75207"], "d": ["დიდმა ვეზირმა ქოჯა სინან-ფაშამ თვეზე მეტხანს გაგრძელებული ალყის შემდეგ ვენის გზის საკეტად მიჩნეული იანიქქალე ჩაიბარა. ციხის დაცემამ ევროპაში დიდი პანიკა გამოიწვია და გრძელ ომში ოსმალების ყველაზე ბრწყინვალე შენაძენი გახდა. თუმცა ციხის შენარჩუნება მხოლოდ ოთხი წელი შეძლეს.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["მურად III-ის გარდაცვალება", "1b62e886"], "d": ["ოცდაერთწლიანი მმართველობის შემდეგ მურად III გარდაიცვალა იმ დღეებში, როცა ვლახეთის ჯარმა იბრაილი გადაწვა და სილისტრამდე მიაღწია, და აია-სოფიას სასაფლაოზე დაკრძალეს. მანისიდან გამოძახებული მისი ვაჟი მეჰმედ III ათი დღის შემდეგ სტამბოლში ჩავიდა და ტახტზე ავიდა (1595 წლის 27 იანვარი).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["ესტერგომის დაკარგვა ავსტრიის სასარგებლოდ", "f420d333"], "d": ["კარლ ფონ მანსფელდის ხელმძღვანელობით წარმოებულ ალყაში საკმარისი დახმარების ვერმიმღებმა ესტერგომის მცველებმა ციხე ერცჰერცოგ მათიასს ჩააბარეს. ორმოცდათორმეტწლიანი ოსმალთა ბატონობის დასრულებით დუნაის ხაზის თავდაცვითი ჯაჭვი გატყდა და ბუდა პირდაპირი საფრთხის ქვეშ აღმოჩნდა. ციხის დაბრუნება მხოლოდ ათი წლის შემდეგ, 1605 წელს, გახდება შესაძლებელი.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["ეგერის ციხის აღება", "3e511629"], "d": ["სამკვირიანი ბრძოლის შემდეგ ძლიერი ეგერის ციხე, რომლის აღებაც ოსმალებმა მანამდე ვერაფრით შეძლეს, მცველების დანებებით დაეცა. ამ დაპყრობამ, რომელშიც ფადიშაჰი პირადად მონაწილეობდა, გარკვეულწილად აღადგინა დაკარგული ესტერგომით შერყეული სულისკვეთება, და დაარსდა ეგერის ეიალეთი. ორი კვირის შემდეგ მოპოვებულ ხაჩოვას გამარჯვებასთან ერთად 1596 წელი გრძელ ომში ოსმალების ყველაზე წარმატებული წელი გახდა.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["იანიქქალეს (დიორის) დაკარგვა", "b4ccc679"], "d": ["მიკლოშ პალფისა და ადოლფ ფონ შვარცენბერგის სარდლობით ნაწილებმა მოულოდნელი თავდასხმით ციხის კარი ააფეთქეს და იანიქქალე დაიბრუნეს. ციხის დაკარგვამ, რომელიც ოთხი წლის წინ ქოჯა სინან-ფაშამ დიდი ძალისხმევით აიღო, უნგრეთში ოსმალთა წინა ხაზი ჩამოშალა. მიუხედავად იმისა, რომ იმავე წელს ბუდის ალყაში მოქცეული მტრის ძალები უკუაგდეს, ომის ბალანსი თანდათან გამომფიტავ ომად გადაიქცა.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["ყარაიაზიჯი აბდულჰალიმის აჯანყება", "30493b0d"], "d": ["გრძელ ომში ჯარიდან გაქცეული სეკბანებისა და ლევენდების შემკრებმა ყარაიაზიჯი აბდულჰალიმმა ცენტრალურ ანატოლიაში ვრცელი მხარე დაიმორჩილა, ურფის ციხე აიღო (1599 წლის ნოემბერი) და „ჰალიმ შაჰის“ ტიტულით თავი ფადიშაჰად გამოაცხადა, საკუთარი ტუღრათი დამოწმებულ ფირმანებს აგზავნიდა. ჯელალების დიდი ტალღის პირველ ლიდერად მიჩნეული ყარაიაზიჯი 1602 წელს გარდაიცვალა, მისი მოძრაობა კი ძმამ, დელი ჰასანმა, გააგრძელა. აჯანყება „დიდი გაქცევის“ ეპოქის დასაწყისია, როცა ანატოლიელი გლეხობა მასობრივად ტოვებდა მიწას.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["თირიაქი ჰასან-ფაშას მიერ კანიჟის თავდაცვა", "d56a5e6a"], "d": ["ერთი წლის წინ აღებული კანიჟის დასაბრუნებლად ერცჰერცოგმა ფერდინანდმა და მისმა მოკავშირეებმა ციხეს ორ თვეზე მეტხანს შემოარტყეს ალყა; თირიაქი ჰასან-ფაშამ 9000-კაციანი ძალით წინააღმდეგობა გაუწია. მიუხედავად იმისა, რომ გარედან დახმარებას ვერ იღებდა, საერთო იერიშები უკუაგდო და გამოხტომებით მტერი მძიმე დანაკარგებით უკან დახევაზე აიძულა. თავდაცვა ოსმალურ ისტორიოგრაფიაში ეპოსად იქცა და „კანიჟის ალყა“ ცალკე ლიტერატურულ ჟანრად ჩამოყალიბდა.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["მეჰმედ III-ის გარდაცვალება და აჰმედ I-ის ტახტზე ასვლა", "da735fde"], "d": ["20 დეკემბერს მეჰმედ III-ის გარდაცვალების შემდეგ ტახტზე მისი თოთხმეტი წლის ვაჟი აჰმედ I ავიდა. ის, რომ იგი ბავშვობის ასაკში და სანჯაყში გასვლის გარეშე ტახტზე ასული პირველი ფადიშაჰი იყო, აჩვენებს, რომ შაჰზადეების პროვინციაში აღზრდის წესი ფაქტობრივად დასრულდა. აჰმედ I-ის მმართველობისას ძმათა მკვლელობაზე უარი ითქმებოდა და „ექბერიეთის“ (ტახტზე დინასტიის უხუცესი მამაკაცი წევრის ასვლის) პრინციპზე გადავიდოდნენ.", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["ესტერგომის დაბრუნება", "7330f273"], "d": ["დიდმა ვეზირმა ლალა მეჰმედ-ფაშამ ათი წლის წინ დაკარგულ ესტერგომს ალყა შემოარტყა და ოსმალურ მმართველობას კვლავ შეუერთა. იმავე ლაშქრობაში პეშტი და ვაციც გამოიხსნეს და ოსმალებმა უნგრეთში თავიანთი ხაზი გაამაგრეს. ამ წარმატებამ შესაძლებელი გახადა მომდევნო წელს ჟიტვატოროკში მოლაპარაკების მაგიდასთან შედარებით ძლიერი პოზიციით დაჯდომა; ესტერგომი 1683 წლამდე ოსმალთა ხელში დარჩებოდა.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["ორუჩის ველის გამარჯვება და ჯანბოლათოღლუს აჯანყების ჩახშობა", "30f93532"], "d": ["ალეპოში დამოუკიდებელი საბეილიქოს შემქმნელი და ტოსკანასთან კავშირის მძებნელი ჯანბოლათოღლუ ალი-ფაშა დიდმა ვეზირმა ქუიუჯუ მურად-ფაშამ ორუჩის ველზე სასტიკად დაამარცხა. სირიაში ცენტრალური ხელისუფლების აღდგენით ჯელალების ტალღის ყველაზე საშიში ფრთა გატყდა. ქუიუჯუ მურად-ფაშას ორწლიანმა დაუნდობელმა წმენდამ ანატოლიაში, თუნდაც დროებით, წესრიგი დაამყარა.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["ალაჩაიირის გამარჯვება და ქალენდეროღლუს აჯანყების ჩახშობა", "55db0485"], "d": ["მანისისა და ბურსის მხარეებზე ხარკის დამკისრებელი ჯელალების ლიდერი ქალენდეროღლუ ქუიუჯუ მურად-ფაშამ ალაჩაიირში დაამარცხა და იგი იძულებული გახდა ირანში გაქცეულიყო. ამ გამარჯვებით ანატოლიაში ჯელალების დიდი ჯარებიდან უკანასკნელი დაიშალა. ქუიუჯუ მურად-ფაშას მკაცრმა წმენდამ — გადმოცემის თანახმად, მის მიერ დახოცილ მეამბოხეებს სპეციალურად ამოთხრილ ჭებში ყრიდნენ — მოკლევადიან პერსპექტივაში წესრიგი კი დაამყარა, მაგრამ ანატოლიის მოსახლეობისა და წარმოების დანაკარგი ვერ აანაზღაურა.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["ჰოლანდიისთვის პირველი აჰდნამეს გაცემა", "5d9d117e"], "d": ["ნიდერლანდების გაერთიანებული რესპუბლიკის ელჩმა კორნელის ჰაგამ მოახერხა აჰმედ I-ისგან იმავე მოცულობის აჰდნამეს მიღება, რაც საფრანგეთსა და ინგლისს ჰქონდათ მიცემული. ამგვარად, ჰოლანდიამ სტამბოლში საელჩოს, ოსმალურ ნავსადგურებში საკონსულოების გახსნისა და საკუთარი დროშით ვაჭრობის უფლება მოიპოვა. ეს აჰდნამე სიმბოლურად გამოხატავს ხმელთაშუა ზღვის ვაჭრობაში ვენეციის ადგილის დამკავებელი ჩრდილოელი საზღვაო ძალების ოსმალურ ბაზარზე შესვლას.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["აჰმედ I-ის გარდაცვალება და მუსტაფა I-ის ტახტზე ასვლა — ექბერიეთის წესი", "9901c09e"], "d": ["ორმოცდათერთმეტდღიანი კუჭის ავადმყოფობის შემდეგ ოცდარვა წლის აჰმედ I გარდაიცვალა და ტახტზე მისი ვაჟის ნაცვლად ძმა მუსტაფა I აიყვანეს. ამგვარად, მამიდან შვილზე გადამავალი მემკვიდრეობის წესი მიატოვეს და ფაქტობრივად „ექბერიეთის“ სისტემაზე გადავიდნენ, რომლის მიხედვით ტახტზე დინასტიის უხუცესი მამაკაცი წევრი ადიოდა. ოთხმოცდათექვსმეტდღიანი ეს პირველი მმართველობა ასევე შაჰზადეების „გალიაში“ (ქაფესში) აღზრდის ეპოქის დასაწყისია.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["მუსტაფა I-ის გადაყენება და ახალგაზრდა ოსმანის (ოსმან II-ის) ტახტზე ასვლა", "e0f552f2"], "d": ["ფსიქიკური ჯანმრთელობის დარღვევის საბაბით მუსტაფა I ოთხმოცდათექვსმეტი დღის ბოლოს ტახტიდან ჩამოაგდეს და ფადიშაჰი აჰმედ I-ის თოთხმეტი წლის ვაჟი ოსმან II გახდა. ჰასანბეიზადეზე დაფუძნებული გადმოცემის მიხედვით, ამ გადაყენების გადაწყვეტილებაში გავლენიანი იყო ყიზლარ აღა მუსტაფა აღა. ახალგაზრდა ოსმანი, იანიჩართა კორპუსის გაუქმებისა და ახალი ჯარის შექმნის გეგმით, ოსმალური რეფორმის დისკუსიების პირველ რადიკალურ ფიგურად მიიჩნევა. ეს გეგმა ოთხი წლის შემდეგ მას სიცოცხლის ფასად დაუჯდებოდა.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["სარაბის ზავი — ირანთან მშვიდობის განახლება", "e778aca8"], "d": ["ფული შიქესთეს მარცხის შემდეგ ირანთან მიღწეულმა სარაბის ზავმა 1612 წლის ნასუჰ-ფაშას ზავის პირობები დიდწილად დაადასტურა; სეფიანების მიერ გასაგზავნი ყოველწლიური აბრეშუმის რაოდენობა ორასი საპალნიდან ას საპალნემდე შემცირდა. ამგვარად, 1603 წლიდან მიმდინარე აღმოსავლური ომების მეორე ეტაპი დასრულდა. მშვიდობა დიდხანს არ გაგრძელდება: 1623 წელს ბაღდადის ხელიდან გასვლით ომი კვლავ აგიზგიზდება.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["ხოტინის ლაშქრობა და ხოტინის ზავი", "bc4c823c"], "d": ["ოსმან II-ის პირადი მეთაურობით წარმოებული დიდი ჯარის წინააღმდეგ ხოდკევიჩის მიერ ხოტინთან მოწყობილი გამაგრებული ბანაკი ვერ გაარღვიეს და თვეების განმავლობაში განხორციელებულმა იერიშებმა შედეგი არ გამოიღო. 9 ოქტომბერს ხელმოწერილი ზავით საზღვრად მდინარე დნესტრი აღიარეს, პოლონელებმა კი კაზაკების თავდასხმების აღკვეთა იკისრეს. გამარჯვებად წარმოდგენილმა, მაგრამ უშედეგო ლაშქრობამ ახალგაზრდა ფადიშაჰის იანიჩრებისადმი უნდობლობა და კორპუსის ლიკვიდაციის განზრახვა გააძლიერა.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["ჰორმუზის პორტუგალიელებისთვის ჩამორთმევა", "93e5f6cf"], "d": ["სეფიანთა ძალებმა 1515 წლიდან პორტუგალიის ხელში მყოფ ჰორმუზს ალყა შემოარტყეს და უკან დაიბრუნეს; ქეშმი და სანაპიროზე მდებარე გამრუნიც (ბანდარ-აბასი) სეფიანთა მმართველობაში გადავიდა, ხოლო ყურის ვაჭრობამ ახალ ნავსადგურში გადაინაცვლა.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["მუსტაფა I-ის მეორედ გადაყენება და მურად IV-ის ტახტზე ასვლა", "1b3a9e74"], "d": ["ოსმან II-ის მკვლელობის შემდეგ მეორედ ტახტზე აყვანილი მუსტაფა I ერთი წლისა და სამი თვის შემდეგ კვლავ ჩამოაგდეს და თერთმეტი წლის მურად IV ფადიშაჰად გამოაცხადეს. პირველი ცხრა წელი სახელმწიფოს ფაქტობრივად მისი დედა ქოსემ სულთანი და სასახლის დიდებულები მართავდნენ. მურად IV 1632 წლიდან მმართველობას პირადად აიღებდა ხელში და მკაცრი ცენტრალიზაციის პერიოდს დაიწყებდა.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["ბაღდადის დაკარგვა სეფიანების სასარგებლოდ", "db81be0c"], "d": ["ბაღდადში აჯანყებული ბექირ სუბაშის სეფიანებთან წარმოებული მოლაპარაკებების ბოლოს, შიდა ციხის დამცველმა მისმა ვაჟმა დერვიშ მეჰმედმა ქალაქი შაჰ აბასის ძალებს ჩააბარა. ხალიფატის მემკვიდრეობის ერთ-ერთი სიმბოლური ქალაქისა და ერაყის დიდი ნაწილის ხელიდან გასვლამ სტამბოლში დიდი აღშფოთება გამოიწვია. ბაღდადის დაბრუნება თხუთმეტი წლის განმავლობაში ოსმალეთის აღმოსავლური პოლიტიკის ერთადერთი მიზანი იქნებოდა.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["აბაზა მეჰმედ-ფაშას ერზურუმის ცენტრის მქონე აჯანყების ჩახშობა", "e6da2729"], "d": ["ოსმან II-ის მკვლელობის შურისძიების პრეტენზიით იანიჩრების წინააღმდეგ აჯანყებულმა ერზურუმის ბეგლარბეგმა აბაზა მეჰმედ-ფაშამ წლების განმავლობაში აღმოსავლეთ ანატოლია თავის კონტროლქვეშ ჰქონდა და ცენტრს წინააღმდეგობას უწევდა. დიდი ვეზირ ჰუსრევ-ფაშას მიერ ერზურუმის ალყის შემდეგ იძულებული გახდა დანებებულიყო; შეიწყალეს და ბოსნიაში დანიშნეს. აჯანყების დასრულება წინაპირობა იყო იმისთვის, რომ მურად IV-ს ირანის წინააღმდეგ ლაშქრობაში გასვლა შესძლებოდა.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["შეიხულისლამის პირველი სიკვდილით დასჯა: აჰიზადე ჰუსეინ ეფენდი", "a60a58c5"], "d": ["სამხედრო არეულობაში შუამავლობის გაწევისა და ფადიშაჰისთვის სასამართლო წესის შესახებ წერილობითი გაფრთხილების გაგზავნის საბაბით შეიხულისლამი აჰიზადე ჰუსეინ ეფენდი ბიუქჩექმეჯეს მახლობლად სიკვდილით დასაჯეს. ის, რომ იგი სიკვდილით დასჯილი პირველი ოსმალი შეიხულისლამი იყო, არღვევდა ფესვგადგმულ ტრადიციას, რომლის მიხედვით ულემთა წარმომადგენლებისთვის უმძიმესი სასჯელი გადასახლება იყო. მოვლენა მურად IV-ის გამკაცრებული ავტორიტეტისა და სახელმწიფო-ულემთა ბალანსის რღვევის სიმბოლოდ მიიჩნევა.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["მურად IV-ის მიერ ერევნის აღება", "b65a9b73"], "d": ["1635 წლის 28 მარტს სტამბოლიდან გასულმა მურად IV-მ 28-29 ივლისს ერევანს ალყა შემოარტყა და 8 აგვისტოს ციხე ჩაიბარა; შემდეგ დაცარიელებულ თავრიზში შევიდა და ქალაქი ააოხრებინა. ფადიშაჰმა გამარჯვების სახსოვრად თოფქაფის სასახლეში ერევნის კოშკი (რევან ქიოშქი) ააგებინა. ეს ლაშქრობა ოცდაათწლიანი შესვენების შემდეგ პირველი დიდი აღმოსავლური ოპერაცია იყო, რომელშიც ფადიშაჰი პირადად მეთაურობდა ჯარს.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["ერევნის დაკარგვა სეფიანების სასარგებლოდ", "fbb8dd25"], "d": ["ოსმალური ჯარის უკან გაბრუნების შემდეგ შაჰ სეფის ძალებმა ერევანს ალყა შემოარტყეს და რვა თვის განმავლობაში დაიბრუნეს. ციხის ასე სწრაფად ხელიდან გასვლამ აჩვენა, რამდენად რთული იყო ლოგისტიკურად მუდმივი ბატონობა კავკასიაში. ერევანი 1639 წლის ყასრ-ი შირინის ზავითაც ირანს დარჩებოდა და ოსმალეთი აზერბაიჯანზე პრეტენზიაზე ხელს აიღებდა.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["ბაღდადის ხელახალი აღება", "4d2f27f3"], "d": ["1638 წლის 8 მაისს სტამბოლიდან გასულმა მურად IV-მ ორმოცდღიანი სასტიკი ალყის შემდეგ თხუთმეტი წელი სეფიანების ხელში მყოფი ბაღდადი დაიბრუნა; ალყისას ვეზირი თაიარ მეჰმედ-ფაშა შაჰიდად დაიღუპა. ქალაქის აღებით ერაყში ოსმალური მმართველობა აღდგა და ფადიშაჰმა „ბაღდადის დამპყრობლის“ ტიტული მიიღო. დაპყრობა მომდევნო წლის ყასრ-ი შირინის ზავით განმტკიცდა და დღევანდელი თურქეთ-ირანის საზღვრის საფუძველი ჩაიყარა.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["მურად IV-ის გარდაცვალება და სულთან იბრაჰიმის ტახტზე ასვლა", "e2ca1ca0"], "d": ["ოცდაშვიდი წლის (ჰიჯრის წელთაღრიცხვით ოცდარვა) ასაკში გარდაცვლილი მურად IV-ის შემდეგ ტახტზე დინასტიის ერთადერთი ცოცხლად დარჩენილი მამაკაცი წევრი, ძმა იბრაჰიმი ავიდა. წლების განმავლობაში გალიაში (ქაფესში) მცხოვრები ახალი ფადიშაჰის მმართველობისას სასახლის ხარჯებმა და სასახლის შიდა გავლენისთვის ბრძოლებმა სახელმწიფო წესრიგი შეარყია. რვა წლის შემდეგ მისი გადაყენებითა და მკვლელობით ოსმალეთის ისტორიაში ფადიშაჰის მეორე მკვლელობა მოხდებოდა.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["აზოვის ციხის დაბრუნება კაზაკებისგან", "e5fcf160"], "d": ["1637 წელს დონელი კაზაკების მიერ აღებული აზოვის ციხე სულთანზადე მეჰმედ-ფაშასა და ყირიმის ხან მეჰმედ IV გირაის ერთობლივი ოპერაციის წინაშე დაიცალა; კაზაკებმა ციხეს ცეცხლი წაუკიდეს და უკან დაიხიეს. შავი ზღვის ჩრდილოეთი კარის დაბრუნებამ დახურა საშიში პერიოდი, როცა კაზაკების თავდასხმები სტამბოლის სრუტემდე აღწევდა. ციხე 1696 წელს ამჯერად რუსეთის მეფე პეტრე I-ს ჩაუვარდებოდა ხელში.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["კრეტის ლაშქრობის დაწყება და ჰანიის აღება", "a1b0c77f"], "d": ["საბაბად იმის გამოყენებით, რომ მალტელმა კორსარებმა ოსმალური ჰაჯის ხომალდი დააზიანეს და კრეტაზე შეაფარეს თავი, ვენეციას ომი გამოუცხადეს და იუსუფ-ფაშას სარდლობით ფლოტმა კუნძულზე ჯარი გადასხა. ორმოცდათოთხმეტდღიანი ალყის შემდეგ ჰანიის ციხე აიღეს და კრეტაზე პირველი მუდმივი ოსმალური ბაზა შეიქმნა. ამგვარად დაიწყო ოსმალეთის ისტორიის ყველაზე ხანგრძლივი ომი; კუნძულის სრულად დაპყრობა მხოლოდ ოცდაოთხი წლის შემდეგ, 1669 წელს, გახდა შესაძლებელი.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["რეთიმნოს აღება — კრეტის ორად გაყოფა", "8f2c4353"], "d": ["ჰანიის აღებიდან ერთი წლის შემდეგ კუნძულის ცენტრალური ნაწილის რეთიმნოს ციხეც დაეცა და კრეტის დასავლეთი ნახევარი მთლიანად ოსმალურ მმართველობაში შევიდა. ვენეციის ხელში მხოლოდ დედაქალაქი კანდია და აღმოსავლეთი კიდე დარჩა; კუნძული ოცდასამი წელი ორად გაყოფილი ცხოვრობდა. რეთიმნოს აღება კანდიის ალყის დამწყები ნაბიჯი გახდა — ისტორიის ყველაზე ხანგრძლივი ალყა აქ დაიწყო.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["კლისის დაკარგვა ვენეციის სასარგებლოდ", "5473c22c"], "d": ["კრეტის (კანდიის) ომის დალმაციის ფრონტზე ვენეციელი მეთაურის ლეონარდო ფოსკოლოს კონტრშეტევამ 1537 წლიდან სანჯაყის ცენტრად მყოფი კლისიც მოიცვა; ციხე ვენეციას გადაეცა. ოსმალების მთელი ძალისხმევის კრეტაზე კონცენტრაციამ დალმაციის საზღვარზე ამ დანაკარგის ანაზღაურება შეუძლებელი გახადა — კლისი ოსმალურ მმართველობას აღარასოდეს დაუბრუნდებოდა; სანჯაყის ცენტრი ლივნოში გადაიტანეს.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["კანდიის ალყის დაწყება", "13016b10"], "d": ["ჰანიისა და რეთიმნოს აღების შემდეგ ოსმალურმა ჯარმა კუნძულზე ვენეციის უკანასკნელ დიდ საყრდენს, კანდიას, ალყა შემოარტყა. ეს ბლოკადა, რომელიც ოცდაერთი წელი გაგრძელდებოდა, მსოფლიო სამხედრო ისტორიაში ერთ-ერთ ყველაზე ხანგრძლივ ალყად ჩაიწერა. ალყის განმავლობაში ვენეციური ფლოტის მცდელობები დარდანელის სრუტის ჩასაკეტად ომს ეგეოსის ზღვის შუაგულში გადაიტანდა.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["უფროსი ვალიდე ქოსემ სულთნის მკვლელობა", "9d763f79"], "d": ["დაახლოებით სამოცდაორი წლის ქოსემ სულთანი ჰარემის ერთ ოთახში იპოვეს და მოკლეს მეჰმედ IV-ის დედის, თურჰან სულთნის, ბრძანებით მოქმედმა ბაშლალა უზუნ სულეიმან აღამ და მისმა ხალხმა. სამი ფადიშაჰის ეპოქაში სახელმწიფო პოლიტიკის წარმმართველი ამ ძლიერი დინასტიური ქალის სიკვდილი ე.წ. „ქალთა სულთანობის“ პერიოდის ფაქტობრივ დასასრულად მიიჩნევა. გამოთავისუფლებულმა ძალაუფლებამ გზა გაუხსნა იმას, რომ ხუთი წლის შემდეგ ქოფრულუ მეჰმედ-ფაშა საგანგებო უფლებამოსილებებით დიდი ვეზირი გამხდარიყო.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["დარდანელის მარცხი და ბოზჯაადისა და ლემნოსის დაკარგვა", "e01a1f7e"], "d": ["ვენეციელი ადმირალის მოჩენიგოს მიერ 1656 წლის ივნისში დარდანელის სრუტის წინ მოპოვებულმა დიდმა საზღვაო გამარჯვებამ ოსმალური ფლოტი თითქმის მთლიანად გაანადგურა; შემდეგ ბოზჯაადა, ლემნოსი და სამოთრაკე ოკუპირებული იქნა. სრუტის ვენეციურ ბლოკადაში მოქცევით სტამბოლში სურსათის ფასები გაიზარდა და დედაქალაქზე თავდასხმის შიში გავრცელდა. ეს კატასტროფა უშუალო მიზეზი გახდა იმისა, რომ 1656 წლის სექტემბერში ქოფრულუ მეჰმედ-ფაშა პირობითად და საგანგებო უფლებამოსილებებით დიდ ვეზირად დანიშნეს.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["დარდანელის გამარჯვება და ბოზჯაადის დაბრუნება", "603da863"], "d": ["ქოფრულუ მეჰმედ-ფაშას მიერ მობილიზებულმა ფლოტმა 1657 წლის 19 ივლისს სრუტის წინ ვენეციური ესკადრა დაამარცხა; შემდეგ ქურდ-ფაშას სარდლობით ძალებმა 25 აგვისტოს ბოზჯაადა დაიბრუნეს, ხოლო 30 აგვისტოს ვენეციელებმა კუნძული მთლიანად დაცალეს. ნოემბერში ლემნოსიც გამოიხსნეს, დარდანელის ბლოკადა გაარღვიეს და სტამბოლის სურსათის მომარაგების გზა კვლავ გაიხსნა. ქოფრულუმ პირადად გადავიდა კუნძულზე და სიმაგრეები შეაკეთებინა; ეს წარმატება ქოფრულუების ეპოქის პირველი დიდი სამხედრო შენაძენია.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["ინეუს (იანოვას) აღება და ტრანსილვანიის ლაშქრობა", "d1089616"], "d": ["უნებართვოდ პოლონეთში ლაშქრობით ოსმალური მფარველობის გამთელავი ტრანსილვანიის მთავრის დიორდ II რაკოცის დასასჯელად ლაშქრობაში გასულმა ქოფრულუ მეჰმედ-ფაშამ ბელგრადის გავლით გაილაშქრა და სტრატეგიული ინეუს ციხე აიღო. ტრანსილვანიაში ახალი მთავარი დანიშნეს და ვასალური კავშირი მკაცრად შეახსენეს. ეს ლაშქრობა ცენტრალურ ევროპაში ოსმალური ავტორიტეტის აღდგენის მცდელობის პირველი რგოლი იყო. ტრანსილვანია ისედაც ოსმალეთზე დაქვემდებარებული სამთავრო იყო; ინეუს აღება უცხო სახელმწიფოსგან დაპყრობა კი არ იყო, არამედ ვასალური ტრანსილვანიის ამ ციხის სამთავროს მმართველობიდან გამოყოფა და პირდაპირ ოსმალურ სანჯაყზე მიბმა; სამთავროს დანარჩენი ნაწილი ვასალურ სტატუსში დარჩა.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["აბაზა ჰასან-ფაშას აჯანყების ჩახშობა", "4ba74321"], "d": ["ქოფრულუ მეჰმედ-ფაშას მკაცრი წმენდების წინააღმდეგ ანატოლიის ბეგლარბეგებისა და სეკბანთა აღების მხარდაჭერით აბაზა ჰასან-ფაშამ დიდი ვეზირის გადაყენება მოითხოვა და დიდი აჯანყება წამოიწყო. აჯანყება ალეპოში ჩაახშეს და მეთაურები მოაშორეს; ეს პროვინციული ფაშების ცენტრის წინააღმდეგ ბოლო ერთობლივი წინააღმდეგობა იყო. ამგვარად, ქოფრულუს ავტორიტეტი უდავო გახდა და დიდი ვეზირის თანამდებობა კვლავ სახელმწიფოს ნამდვილი აღმასრულებელი ცენტრის დონემდე ამაღლდა.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["ორადეას (ვარადის) აღება", "0e6ad300"], "d": ["ოსმალეთისთვის ომის გამომცხადებელი ტრანსილვანიის მთავრის დიორდ II რაკოცის წინააღმდეგ მოწყობილი ლაშქრობის ფარგლებში ვარადის ციხე და ქალაქი აიღეს. ტრანსილვანიის ერთ-ერთი საკვანძო ციხის დაცემით რეგიონში ახალი ოსმალური ეიალეთი (ვარადის ეიალეთი) დაარსდა. დაპყრობამ ჰაბსბურგები განგაშში ჩააგდო და სამი წლის შემდეგ დაწყებული ოსმალეთ-ავსტრიის ომის ერთ-ერთი უშუალო მიზეზი გახდა. იმავე თარიღს შემოერთებული სხვა ადგილები: ვარადი. აქაც მიწა უცხო სახელმწიფოს არ წაართვეს: ტრანსილვანია ისედაც დაქვემდებარებული ოსმალური სამთავრო იყო; ვარადის ეიალეთად ქცევამ მხოლოდ ამ ქალაქის მმართველობა ვასალურ სამთავროს ჩამოართვა და პირდაპირ ფადიშაჰს დაუქვემდებარა, ისევე როგორც ორი წლის წინ ინეუში.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["სენტგოტარდის (სენ-გოთარდის) ბრძოლა", "61ebc1f2"], "d": ["მდინარე რააბის გადამლახველი ოსმალური ძალები მონტეკუკოლის სარდლობით მოკავშირე ევროპულმა ჯარმა შეაჩერა და მძიმე დანაკარგები მიაყენა. ბრძოლა სამხედრო ისტორიაში გარდამტეხ მომენტად მიიჩნევა, რადგან პირველად ნათლად აჩვენა დისციპლინირებული ცეცხლსასროლი ქვეითის თოფის სროლის უპირატესობა ოსმალური ცხენოსანი იერიშის წინაშე. მარცხის მიუხედავად, ოსმალებმა ცხრა დღის შემდეგ ხელმოწერილ ვაშვარის ზავში ხელსაყრელი პირობების მიღება მოახერხეს.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["ვაშვარის ზავი", "089c978c"], "d": ["სენტგოტარდის მარცხის მიუხედავად დადებულმა ზავმა გაითვალისწინა, რომ უივარი და ვარადი ოსმალეთს რჩებოდა, ტრანსილვანია ოსმალური მფარველობის ქვეშ ნეიტრალური დარჩებოდა, ავსტრია კი 200.000 ყურუშ „საჩუქარს“ გადაიხდიდა. ეს ოცწლიანი ზავი იშვიათი მაგალითია იმისა, როცა ომში წაგებულმა მხარემ მოლაპარაკების მაგიდასთან გაიმარჯვა. ზავით ჰაბსბურგულ საზოგადოებაში გაჩენილი უკმაყოფილება შუა უნგრეთის მოძრაობას და, არაპირდაპირ, 1683 წლის ვენის ლაშქრობას გამოკვებავდა.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["ალჟირში დეის მმართველობის დაწყება", "e99faa51"], "d": ["ალჟირის ოჯაღმა და რეისთა ტაიფამ (მეკობრე კაპიტნებმა) უკანასკნელი აღა გადააყენეს და ჰაჯი მეჰმედი სიცოცხლის ბოლომდე დეიდ აირჩიეს. ამ თარიღის შემდეგ ალჟირს მართავდა არა სტამბოლის დანიშნული ბეგლარბეგი, არამედ ადგილობრივი ოჯაღის საკუთარი წრიდან არჩეული დეი; ოსმალური კავშირი შეიზღუდა ხუთბაში ფადიშაჰის სახელის წაკითხვით, დროშითა და ლაშქრობაში მონაწილეობის ვალდებულებით. ამგვარად ალჟირი ეიალეთიდან ოჯაღლიკად გადაიქცა — იგივე ცვლილება ტუნისმა 1705 წელს ჰუსეინიდებთან, ტრიპოლიტანიამ კი 1711 წელს ყარამანლებთან განიცადა.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["პოლონეთის ლაშქრობა დაიწყო — მეჰმედ IV და ფაზილ აჰმედ-ფაშა ჯარის სათავეში", "75e15a39"], "d": ["ოსმალთა მფარველობაში შესული უკრაინის ჰეტმანის პეტრო დოროშენკოს წინააღმდეგ პოლონეთის შეტევები რომ არ შეწყდა, სტამბოლმა პოლონეთის მეფეს თავდასხმებზე ხელის აღება მოსთხოვა; დადებითი პასუხის მიუღებლობის შემდეგ პოლონეთის წინააღმდეგ ლაშქრობის გადაწყვეტილება მიიღეს. დიდი ვეზირი ფაზილ აჰმედ-ფაშა ჯართან ერთად, რომელშიც ფადიშაჰიც იყო, 1672 წლის 4 ივნისს პოლონეთისკენ დაიძრა. ლაშქრობა კამენეცის აღებითა და ბუჩაჩის ზავით დასრულდებოდა.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["კამენეცის აღება და პოდოლიის ეიალეთის დაარსება", "c3f4f6d0"], "d": ["ცხრადღიანი ალყის შემდეგ აღმოსავლეთში პოლონეთის უძლიერეს ციხედ მიჩნეული კამენეცი ჩაბარდა; მეჰმედ IV-მ 2 სექტემბერს საკათედრო ტაძრიდან გადაკეთებულ მეჩეთში პირველი პარასკევის ლოცვა აღასრულა. ციხე ცენტრად აქციეს, პოდოლიის ეიალეთი დაარსდა და ოსმალურმა დროშამ დღევანდელი უკრაინის ტერიტორიაზე ყველაზე ჩრდილო წერტილს მიაღწია. კამენეცი 1699 წლის კარლოვიცის ზავამდე იმპერიის ჩრდილო-დასავლეთ კიდედ დარჩებოდა.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["ყარა მუსტაფა-ფაშამ უმანი პოლონეთისგან ჩაიბარა", "0d3543a0"], "d": ["პოლონეთის წინააღმდეგ გაგზავნილმა ყარა მუსტაფა-ფაშამ პოლონეთის ხელში მყოფი ციხეებიდან უმანი ჩაიბარა; ქალაქი კარლოვიცამდე ოსმალური მმართველობის ქვეშ დარჩა.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["ჩიგირინის ციხის აღება", "a17cedd0"], "d": ["წინა წელს მელექ იბრაჰიმ-ფაშას უშედეგო ოპერაციის შემდეგ დიდმა ვეზირმა მერზიფონელმა ყარა მუსტაფა-ფაშამ პირადად ისარდლა, გამაგრებულ ჩიგირინის ციხეს ალყა შემოარტყა (19/21 ივლისი) და 21 აგვისტოს აიღო. უკრაინის კაზაკთა საჰეტმანოზე ოსმალეთ-რუსეთის მეტოქეობის სიმბოლო ამ ციხის დაცემამ რუსეთი ზავისკენ აიძულა. ეს წარმატება მერზიფონელის იმ თავდაჯერების ერთ-ერთი წყარო გახდა, რომელიც ვენისკენ მიმართავდა მას.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["ბახჩისარაის ზავი — პირველი ოფიციალური ზავი რუსეთთან", "df82bc0b"], "d": ["ჩიგირინის ლაშქრობების შემდეგ ყირიმის ხანის შუამავლობით წარმოებული მოლაპარაკებების ბოლოს, საზღვრად მდინარე დნეპრი (ოზუ) აღიარეს და ოსმალეთის სახელმწიფოსა და რუსეთს შორის ოცწლიანი ზავი დაიდო. რადგან ეს ორ სახელმწიფოს შორის პირველი ყოვლისმომცველი ხელშეკრულება იყო, ის ოსმალურ-რუსული ურთიერთობების საწყის დოკუმენტად მიიჩნევა. ზავის წყალობით აღმოსავლეთის ფრონტი დაიცვეს და ჯარის ცენტრალური ევროპისკენ მიმართვა შესაძლებელი გახდა.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["ტეკელი იმრესთვის შუა უნგრეთის მეფობის ბერათის გადაცემა", "3cd8d51d"], "d": ["ჰაბსბურგული ზეწოლის წინააღმდეგ აჯანყებული პროტესტანტი უნგრელი დიდგვაროვანი ტეკელი იმრე 1682 წლის აპრილიდან „შუა უნგრეთის არჩეულ მეფედ“ ითვლებოდა, ხოლო 16 სექტემბერს ბუდის ბეგლარბეგმა იბრაჰიმ-ფაშამ მას სამთავრო ნიშნები გადასცა. ამგვარად, ოსმალთა მფარველობაში ახალი ვასალური უნგრული სახელმწიფო შეიქმნა. ამ ჩარევამ ავსტრიასთან ომი გარდაუვალი გახადა და დაიწყო ჯაჭვი, რომელიც მომდევნო წელს ვენის მეორე ალყამდე მიდიოდა.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["ლეფკადის (აია-მავრას) დაკარგვა ვენეციის სასარგებლოდ", "e6905fee"], "d": ["წმინდა ლიგაში გაწევრიანებული ვენეციის ფლოტმა, ქალაქის ზარბაზნებით დაბომბვის შემდეგ, იონიის ზღვაში მდებარე ლეფკადის კუნძული დაიპყრო. იმავე წელს პრევეზის დაცემით ადრიატიკის შესასვლელში ოსმალური კონტროლი გატყდა. ეს დანაკარგები იმ ოპერაციის საწყისი ნაბიჯები იყო, რომლითაც მოროზინი სამ წელიწადში მთელ მორეას დაიპყრობდა.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["კორონის დაკარგვა ვენეციის სასარგებლოდ", "2ed762bc"], "d": ["მოროზინის სარდლობით ვენეციურმა ძალებმა მორეის ნახევარკუნძულის სამხრეთ-დასავლეთ კიდეზე კორონის ციხე აიღეს; ქალაქი ამის შემდეგ ოცდაათი წელი ვენეციური მმართველობის ქვეშ დარჩებოდა. კორონის დაცემა მორეის დასაპყრობად მიმართული ვენეციური ოპერაციის პირველი დიდი შენაძენი იყო. ციხის დაბრუნება მხოლოდ 1715 წელს სილაჰდარ ალი-ფაშას სარდლობით ოსმალურმა ჯარმა შეძლო.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["ათენის დაბრუნება — ვენეციის უკანდახევა", "03393b46"], "d": ["1687 წლის სექტემბერში აკროპოლისის დამბომბავმა და პართენონის ამფეთქებელმა მოროზინიმ, ზამთრის ათენში გატარების შემდეგ, მიხვდა, რომ ქალაქში ვერ გაძლებდა. შავი ჭირის ეპიდემიის, მომარაგების სირთულისა და ოსმალური ძალების შეკრების გამო ვენეციურმა გარნიზონმა ქალაქი დაცალა და მორეაში დაიხია. ამგვარად, ათენი უბრძოლველად კვლავ ოსმალურ მმართველობას დაუბრუნდა, მაგრამ პართენონის ნგრევა ვეღარ აღდგა.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["ლიპოვა (ლიპა) კარაფას დანებდა — ავსტრიის ხელში გადავიდა", "7f0a8d38"], "d": ["ანტონიო კარაფას სამდღიანი ალყის შემდეგ ლიპოვა 1688 წლის 12-22 ივნისს შორის დანებდა და ავსტრიის ხელში გადავიდა. შემდგომში ოსმალებმა ქალაქი უკან დაიბრუნეს, ავსტრიამ 1691 წელს ხელახლა დაიკავა; 1695 წლის ლაშქრობისას ოსმალებმა კონტროლი აღადგინეს. იმავე თარიღით ატლასში ოსმალეთიდან ჰაბსბურგებს გადასული სხვა დასახლებებია: არადი და ვილაგოში (შირია). არადის შესახებ წყარო მხოლოდ წელს ასახელებს (MKL, Arad: 1551-1688 წლებში ოსმალთა ხელში); დღე ლიპოვადანაა აღებული, ვილაგოში არადის ჯაჭვს მისდევს (გაცხადებული მიახლოებითობა). ლუგოშისა (ლუგოჟი) და კარანშებეშის (კარანსებეში) ციხეებიც ივნისის ბოლოს ავსტრიას გადაეცა (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["ვენეციის მიერ ევბეის ალყის მოგერიება", "aae7e6a0"], "d": ["მორეის დაპყრობის შემდეგ ეგეოსისკენ მიმართული მოროზინი სამ თვეზე მეტხანს გაგრძელებული ალყით ცდილობდა ევბეის (ეღრიბოზის) აღებას; მაგრამ 1687-1688 წლების ზამთარში გამაგრებული სიმაგრეებისა და გარნიზონის წინააღმდეგობის წინაშე, მძიმე დანაკარგებით, იძულებული გახდა უკან დაეხია. ამ მარცხმა ეგეოსში ვენეციის წინსვლა შეაჩერა და მოროზინის სამხედრო რეპუტაცია შეარყია. ევბეა კარლოვიცაზეც ოსმალთა ხელში დარჩებოდა.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["კანიჟის ციხის დაკარგვა ავსტრიის სასარგებლოდ", "553b45f3"], "d": ["1690 წლის იანვრიდან 60.000-კაციანი ჰაბსბურგული ჯარის მჭიდრო ბლოკადაში მოქცეულმა კანიჟამ თვეების განმავლობაში დახმარების გარეშე გაუწია წინააღმდეგობა და მისმა უკანასკნელმა მცველმა მუსტაფა-ფაშამ ხელმოწერილი კაპიტულაციის ხელშეკრულებით ციხე ხელიდან გაუშვა. ამგვარად, თირიაქი ჰასან-ფაშას ეპიკური თავდაცვით ცნობილ ციხეში ოთხმოცდაათწლიანი ოსმალთა ბატონობა დასრულდა. კანიჟის დაკარგვა უნგრეთის დასავლეთში ოსმალების უკანასკნელი დიდი საყრდენის ნგრევა იყო.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["სულეიმან II-ის გარდაცვალება", "d2478080"], "d": ["სულეიმან II, რომელიც „ყაფესში“ დაახლოებით ორმოცი წლის გატარების შემდეგ 1687 წელს აიყვანეს ტახტზე, ავადმყოფი, ჯარის მზადებას რომ ადევნებდა თვალს, 1691 წლის 22 ივნისს, პარასკევს, შუადღის ახლოს ედირნეში გარდაიცვალა; მისი სულთნობა სამ წელს, რვა თვესა და ორ დღეს გაგრძელდა. დიდ ვეზირს წინასწარ ჰქონდა გაცემული საჭირო მითითებები, რომ ფადიშაჰის გარდაცვალების შემთხვევაში ტახტზე მისი ძმა აჰმედი აეყვანათ. დაკრძალვის ლოცვა იმავე დღეს ალაი-ქიოშქში აღასრულეს; ნეშტი სტამბოლში ჩაასვენეს და სულთან სულეიმან კანუნის აკლდამაში, მის მარჯვენა მხარეს დაკრძალეს.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["აჰმედ II-ის ტახტზე ასვლა", "52947b14"], "d": ["სულეიმან II-ის გარდაცვალების შემდეგ ორმოცდაცხრა წლის ძმა აჰმედ II ედირნეში ტახტზე ავიდა. მისი მმართველობა წმინდა ლიგის ომების უმძიმეს წლებს დაემთხვა; მისი გამეფებიდან ორი თვის შემდეგ სალანკემენთან დიდი ვეზირი ფაზილ მუსტაფა-ფაშა შაჰიდად დაიღუპა. ამის საპირისპიროდ, მის ეპოქაში დანერგილი მალიქანეს სისტემა ოსმალური ფინანსების გრძელვადიანი სტრუქტურის შემცვლელი ერთ-ერთი უმნიშვნელოვანესი რეფორმა გახდა.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["მეჰმედ IV-ის გარდაცვალება ედირნეში", "17388b7e"], "d": ["1687 წელს ტახტიდან ჩამოგდებული ავჯი მეჰმედი სულეიმან II-ის 1689 წლის უნგრული ლაშქრობის დროს ედირნეში გადმოიყვანეს და ის თავისი მეორე ძმის, აჰმედ II-ის სულთნობის მოწმეც გახდა. ამ საყვარელ ქალაქში გარდაიცვალა. ნეშტი სტამბოლში ჩაასვენეს და დედამისის, ტურჰან სულთანის, იენიჯამის გვერდით მდებარე აკლდამაში დაკრძალეს.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["აჰმედ II-ის გარდაცვალება ედირნეში", "c6306c08"], "d": ["აჰმედ II, რომლის ოთხწლიანი სულთნობა ომში გავიდა, ორმოცდათორმეტი წლისა წყალმანკის (შეშუპების) გამო ედირნეში გარდაიცვალა. ნეშტი სტამბოლში ჩაასვენეს და სულთან სულეიმან კანუნის აკლდამაში დაკრძალეს. მის ადგილას მისი ძმისწული მუსტაფა II ავიდა.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["ბასრის ირანელების მიერ აღება", "a9cdf3a3"], "d": ["როცა ოსმალეთის სახელმწიფო დასავლეთში წმინდა ლიგის ომებით იყო დაკავებული, ბასრა 1690 წლის შავი ჭირის ეპიდემიის შემდეგ ჯერ მუნთაფიყის შეიხ მანიმ, შემდეგ კი ჰუვეიზეს ხან ფარაჯალაჰმა გაძარცვეს. ამ არეულობით ისარგებლეს ირანელებმა, 1696 წელს ქალაქი აიღეს და ბასრაში მცველი დატოვეს.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["სტამბოლის ზავი — აზოვის რუსეთისთვის დათმობა", "79db4724"], "d": ["კარლოვიცაზე რუსეთთან მხოლოდ ორწლიანი ზავის დადება იყო შესაძლებელი; მუდმივი ზავი სტამბოლში წელიწადნახევრიანი მძიმე ვაჭრობის შემდეგ მოეწერა ხელი. ოსმალეთის სახელმწიფომ 1696 წელს დაკარგული აზოვის ციხე და მისი შემოგარენი ოფიციალურად რუსეთს დაუთმო, ყირიმის ხანმა კი მოსკოვისგან მიღებულ ყოველწლიურ ხარკზე უარი თქვა. ამის სანაცვლოდ რუსეთმა სტამბოლში მუდმივი ელჩის ყოლის უფლება მოიპოვა; ამგვარად, შავი ზღვის ჩრდილოეთ სანაპიროზე რუსული ყოფნა სამართლებრივად დადასტურდა.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["დალთაბან მუსტაფა-ფაშას მიერ ყურნასა და ბასრის დაბრუნება", "7adb777d"], "d": ["კარლოვიცის ზავის შემდეგ ბაღდადის ვალად და ბასრის სერასქერად დანიშნული დალთაბან მუსტაფა-ფაშა ალეპოს, რაქას, სივასისა და ყარამანის ძალებით და ბირეჯიქიდან ჩამომავალი სამდინარო ფლოტით სამხრეთისკენ გაემართა. შემოგარენის ტომების შეიხები სათითაოდ დაემორჩილნენ, ირანის ბასრის მცველმა დაუდ ხანმა ქალაქი დატოვა და ყურნა და ბასრა კვლავ ოსმალთა მმართველობაში შევიდა.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["მუსტაფა II-ის გარდაცვალება", "626c394d"], "d": ["მუსტაფა II, რომელმაც ედირნეს ამბოხის შედეგად ტახტი თავის ძმას, აჰმედ III-ს დაუთმო, ტახტიდან ჩამოგდებიდან დაახლოებით ხუთი თვის შემდეგ საყვარელ ედირნეში გარდაიცვალა. მის ავადმყოფობას ბოლო მოვლენებით გამოწვეული მწუხარებაც დაემატა. ზოგიერთი დასავლური წყარო წერს, რომ ხალხში გავრცელებული იყო აზრი, თითქოს ის მოწამლეს.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["ბაღდადში მამლუქური (ქოლემენების) მმართველობის დაწყება", "abe52618"], "d": ["ქართული წარმოშობის ჰასან-ფაშას ბაღდადის მმართველად დანიშვნით ერაყში დაიწყო პერიოდი, როცა ცენტრიდან დანიშნული მმართველების ნაცვლად საკუთარი მონებისგან აღზრდილი მმართველი ფენა ბატონობდა. 1749 წელს სულეიმან-ფაშას მმართველობით სისტემა საბოლოოდ დამკვიდრდა და ბაბიალი იძულებული გახდა, დაენიშნა არა ვისაც სურდა, არამედ გავლენის ხელში ჩამგდები ერთ-ერთი ქოლემენი. ამ ნახევრად ავტონომიურმა სტრუქტურამ, მართალია, ირანის საზღვრის დაცვაში გამოადგა, მაგრამ საუკუნენახევრის განმავლობაში ერაყზე ცენტრალური ხელისუფლების კონტროლი შეასუსტა.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["ტუნისში ჰუსეინიანთა დინასტიის დაარსება", "cb1a98f9"], "d": ["ალჟირული ძალების მიერ ტუნისის შემოსევის შედეგად გაჩენილ ხელისუფლების ვაკუუმში თურქული წარმოშობის სიპაჰების აღა ჰუსეინ ბ. ალიმ ბეილიქი ხელში ჩაიგდო და ოსმალეთის ფადიშაჰისადმი ერთგულების გამოცხადებით ლეგიტიმაცია მოიპოვა. მის მიერ დაარსებული დინასტია ტუნისს 1705-1735 და 1756-1957 წლებში მართავდა; ოჯაღის მმართველობის ადგილი მამიდან შვილზე გადამავალმა ბეილიქის წესრიგმა დაიკავა. ამგვარად, მაღრიბის ოჯაღებში ცენტრზე მიბმული, მაგრამ ფაქტობრივად ავტონომიური დინასტიური სტრუქტურების პირველი ნიმუში გაჩნდა.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["ორანისა და მერს-ელ-ქებირის აღება ესპანელებისგან", "b67ce06a"], "d": ["ალჟირის ოჯაღის ბეგლარბეგის ძალებმა ორი საუკუნის განმავლობაში ესპანური გარნიზონის ხელში მყოფი ორანი და მისი ნავსადგური მერს-ელ-ქებირი ხანგრძლივი ალყის შემდეგ აიღეს. ეს დასავლეთ ხმელთაშუა ზღვაში ოსმალთა მფარველობაში მყოფი მაღრიბის ოჯაღების მიერ ესპანეთის წინააღმდეგ მოპოვებული უდიდესი წარმატება იყო და ალჟირის დასავლეთ ფრთა უზრუნველყო. ქალაქი 1732 წელს კვლავ ესპანურ ოკუპაციაში მოექცეოდა, საბოლოოდ კი 1792 წელს დაიბრუნეს.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["პრუთის ზავი — აზოვისა და ტაგანის დაბრუნება", "bac5d2a1"], "d": ["პრუთის ნაპირას ალყაში მოქცეული რუსული ჯარის დანებების შემდეგ ხელმოწერილმა შვიდმუხლიანმა ზავმა გაითვალისწინა აზოვის ციხის მიწებითა და საბრძოლო მასალით ოსმალებისთვის დაბრუნება. ტაგანის, კამენკისა და იენიქალეს სიმაგრეები უნდა დანგრეულიყო, მხარეები კი ამ მხარეში ახალ ციხეებს არ ააგებდნენ. პეტრე I-ის მიერ ვორონეჟსა და აზოვში თექვსმეტი წლის განმავლობაში შექმნილი ფლოტისა და ბაზების სისტემა ჩამოიშალა; რუსეთის შავ ზღვამდე ჩასვლა დაახლოებით ორმოცდაათი წლით დაყოვნდა.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["ტრიპოლიში ყარამანლის დინასტიის დაარსება", "e1105d4a"], "d": ["ოჯაღის აღების ქიშპით შეწუხებულ ტრიპოლიში (ლიბია) ცხენოსანი ოფიცერი აჰმედ ყარამანლი ხელისუფლებას დაეუფლა და სტამბოლიდან მიღებული ბეგლარბეგის ბერათით თავისი მდგომარეობა ოფიციალურად გააფორმა. აჰმედ-ფაშას, მისი ვაჟის მეჰმედ-ფაშასა და შვილიშვილის იუსუფ-ფაშას ხელით 1711-1835 წლებში არსებული დინასტია გაჩნდა; ჩამოყალიბდა ნახევრად დამოუკიდებელი სტრუქტურა, რომელმაც საკუთარი ფლოტი შექმნა და ევროპულ სახელმწიფოებთან პირდაპირ ხელშეკრულებებს დებდა. ეს პერიოდი მხოლოდ 1835 წელს, ეიალეთის ცენტრზე პირდაპირ მიბმით, დასრულდებოდა.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["რუსეთთან ედირნეს ზავი", "14901a70"], "d": ["პრუთთან მიცემული დაპირებების შეუსრულებლობის გამო კიდევ ორჯერ გამოცხადდა ომი, ბოლოს კი, რუსების მიერ ვალდებულებების მიღების შემდეგ, ედირნეში მუდმივი ზავი დაიდო. ზავმა პრუთის პირობები დაადასტურა; რუსეთი პოლონეთის საქმეებში აღარ ჩაერეოდა, კაზაკთა მიწებიდან გავიდოდა და შვედეთის მეფის, „დემირბაშ“ კარლის, სამშობლოში დაბრუნებას ხელს არ შეუშლიდა. ჩრდილოეთის ფრონტის ასე დახურვამ ოსმალეთის სახელმწიფოს საშუალება მისცა, ყურადღება მორეისა და ვენეციის ფრონტისკენ მიემართა. იმავე თარიღს შემოერთებული სხვა ადგილები: ხოტინი.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["ვენეციისთვის ომის გამოცხადება — მორეის ლაშქრობის მზადება", "d970b122"], "d": ["საბაბად იმის დასახელებით, რომ ვენეცია მხარს უჭერდა მონტენეგროელ მეამბოხეებს, ოსმალურ სავაჭრო ხომალდებს იტაცებდა და კარლოვიცაზე მიღებულ მორეას მძიმე გადასახადებით ჩაგრავდა, დივანში ომის გადაწყვეტილება მიიღეს. დიდი ვეზირ სილაჰდარ დამად ალი-ფაშას მიერ მომზადებული ლაშქრობა მომდევნო წელს ას დღეზე ნაკლებ დროში მთელი მორეის ნახევარკუნძულის დაბრუნებით დასრულდებოდა. თუმცა ეს წარმატება ავსტრიას აამოქმედებდა და 1716 წელს გაცილებით მძიმე ომის კარს გააღებდა.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["ტინოსის (ისტენდილის): ეგეოსში ვენეციის უკანასკნელი კუნძულის ჩაბარება", "4abec891"], "d": ["მორეის ლაშქრობაში გასულმა ფლოტმა გზად ტინოსის, ეგეოსში ვენეციის ხელში დარჩენილი ერთადერთი კუნძულის, წინ ღუზა ჩაუშვა. მიუხედავად იმისა, რომ ნაქსოსის საჰერცოგო 1566 წელს დაეცა, ლათინური მოსახლეობის წყალობით კუნძული კიდევ ას ორმოცდაათი წელი ვენეციურ დროშას ატარებდა და ხანმოკლე ალყის შემდეგ სისხლისღვრის გარეშე დანებდა. ამგვარად, ეგეოსის ზღვაში ვენეციის უკანასკნელი ნაფეხური წაიშალა და ზღვა მთლიანად ოსმალურ შიდა ზღვად იქცა.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["ნაფპლიონის (ანაბოლუს) აღება — მორეის საკვანძო ციხე", "62a5808a"], "d": ["მორეაში ვენეციის დედაქალაქი და უძლიერესი სიმაგრე ნაფპლიონი დაეცა, როცა პალამიდის რედუტი ცხრადღიანი დაბომბვის შემდეგ აიღეს. ციხის ასე სწრაფად აღებამ ნახევარკუნძულის დანარჩენ ნაწილში წინააღმდეგობა გატეხა. კარლოვიცაზე დაკარგული მორეის დაბრუნება ფაქტობრივად აქ დასრულდა. იმავე თარიღს ატლასში ვენეციიდან ოსმალებზე გადასული სხვა დასახლება: არგოსი — ის ნაფპლიონის „უფროსი ცენტრის“ ჯაჭვს მიჰყვება (TDV anabolu; დეკლარირებული მიახლოება).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["მოდონის ჩაბარება", "43faa909"], "d": ["ნაფპლიონის დაცემის შემდეგ მორეის სამხრეთ-დასავლეთ კიდეზე მდებარე მოდონის ციხეს ხმელეთიდან ჯარმა, ზღვიდან კი ფლოტმა ალყა შემოარტყა და მალე დანებდა. ეს ნავსადგური, რომელსაც ვენეცია აღმოსავლეთ ხმელთაშუა ზღვის ლაშქრობებში ორასი წელი იყენებდა, ხომალდებისთვის წყლისა და სურსათის ასაღები სავალდებულო გაჩერების პუნქტი იყო. მისმა დაკარგვამ ეგეოსში ვენეციური ფლოტის მოძრაობის უნარი დაასრულა.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["კორონის ჩაბარება — მორეის ლაშქრობის დასრულება", "e4b9c8a4"], "d": ["მესენიის ყურის შესასვლელის მაკონტროლებელი კორონის ციხის დანებებით მორეის ნახევარკუნძულზე ვენეციური მმართველობა სრულად დასრულდა. კარლოვიცაზე დაკარგული ნახევარკუნძული ლაშქრობის დაწყებიდან მხოლოდ სამი თვის შემდეგ მთლიანად დაბრუნდა. იმავე ლაშქრობის გაგრძელებაში, 1715 წლის სექტემბერში, იონიის ზღვაში მდებარე ლეფკადის (აია-მავრას) კუნძულიც ვენეციას წაართვეს. ამ სისწრაფემ ვენეცია აიძულა, ავსტრია ომში ჩაერთო, და სამი წლის შემდეგ პოჟარევაცისკენ მიმავალი გზა გაიხსნა.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["კუნძულ კითერას (Çuha) აღება", "494de6c6"], "d": ["მორეის სამხრეთ კიდეზე მდებარე კუნძული კითერა ნახევარკუნძულის სრული აღების შემდეგ ფლოტმა ჩაიბარა. იონიისა და ეგეოსის ზღვებს შორის გადასასვლელის დამკვირვებელი კუნძული იყო ის წინა ფორპოსტი, რომელსაც ვენეცია ამ წყლების საკონტროლებლად იყენებდა. მაგრამ ის ხელში შენარჩუნებულ ერთადერთ ოსმალურ კუნძულად არ დარჩენილა: სამი წლის შემდეგ პოჟარევაცში ვენეციას დაუბრუნეს.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["ავსტრიამ და ვენეციამ კავშირი დადეს — 1716-1718 წლების ოსმალეთ-ავსტრიის ომის კარი", "99511ca2"], "d": ["ოსმალების მიერ მორეის ვენეციისგან დაბრუნების შემდეგ ავსტრიამ, კარლოვიცის ზავის დარღვევის საბაბით, ვენეციასთან სამოკავშირეო ხელშეკრულება დადო; პრინც ევგენმა დიდ ვეზირს გაგზავნილ წერილში ვენეციისთვის წართმეული ადგილების დაბრუნება მოითხოვა. დავუთფაშას ბანაკში გამართულ თათბირზე დიდი ვეზირ ალი-ფაშას ზეწოლით ავსტრიას ომი გამოუცხადეს და ამისთვის შეიხულისლამისგან ფეთვა მიიღეს.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["დიდი ვეზირი ალი-ფაშა ავსტრიის ლაშქრობაში გაემართა", "2fbdce42"], "d": ["ავსტრიისთვის ომის გამოცხადების შემდეგ სერდარ-ი ექრემმა ალი-ფაშამ 100.000-ზე მეტი კაცისგან შემდგარი ჯარით ავსტრიის ლაშქრობაში გაილაშქრა; ფლოტი კი იმავე ზაფხულს კორფუსკენ გაემართა. ჯარი ბელგრადიდან ვარადინისკენ წავიდოდა და აგვისტოს დასაწყისში მარცხისას დიდი ვეზირი შაჰიდად დაიღუპებოდა.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["ვარადინის (პეტროვარადინის) მარცხი — დამად ალი-ფაშას დაღუპვა", "265c1d81"], "d": ["ბელგრადის გავლით დუნაის გადამლახველი ოსმალური ჯარი პრინც ევგენის სარდლობით ავსტრიულ ძალებს ვარადინის მისადგომებთან შეხვდა; მიუხედავად იმისა, რომ პირველ შეტევაზე იანიჩართა იერიშმა მტრის სანგრები შეავიწროვა, ცხენოსანი ფრთის ნგრევით რიგები დაიშალა. დიდი ვეზირი სილაჰდარ დამად ალი-ფაშა შუბლში მოხვედრილი ტყვიით შაჰიდად დაიღუპა; ბანაკი და მთელი საარტილერიო ტექნიკა მტრის ხელში გადავიდა. ეს მარცხი, რომელსაც ოსმალური ქრონიკები „ვარადინის წელს“ უწოდებენ, ტიმიშოარასა და მომდევნო წელს ბელგრადის დაკარგვამდე მიმავალი ჯაჭვის პირველი რგოლი იყო.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["კორფუს ალყის მარცხით დასრულება", "b2aa7011"], "d": ["მორეის სერასქერი ყარა მუსტაფა-ფაშა ხმელეთიდან, კაპუდან-ფაშა ჯანიმ ხოჯა მეჰმედ-ფაშა კი ფლოტით ზღვიდან დაეძგერა კორფუს; კუნძული ადრიატიკაში ვენეციის საკვანძო ბაზა იყო. თუმცა ციხის უკიდურესად ძლიერმა სიმაგრეებმა, ვენეციური ფლოტის მოყვანილმა გამაგრებამ და დუნაის ფრონტიდან მოსულმა მარცხის ამბებმა ალყის მოხსნა გამოიწვია. კორფუს ვერაღებამ მორეის ხელახალი დაპყრობით ამაღლებული განწყობა ჩააქრო და ომის სიმძიმის ცენტრი უნგრეთზე გადაინაცვლა.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["ტიმიშოარას (თემეშვარის) დაკარგვა ავსტრიის სასარგებლოდ", "27fe1365"], "d": ["ვარადინის მარცხის შემდეგ პრინცი ევგენი პირდაპირ ტიმიშოარასკენ გაემართა და ციხე ორმოც დღეზე მეტხანს გაგრძელებული ალყის ბოლოს კაპიტულაციით ჩაბარდა. ამგვარად ხელიდან გავიდა ქალაქი, რომელიც 1552 წელს კანუნის ეპოქაში აიღეს და 164 წლის განმავლობაში, როგორც საბეგლარბეგოს ცენტრი, უნგრეთის თავდაცვის აღმოსავლეთ ბურჯად ითვლებოდა. ტიმიშოარას დაცემით მთელი ბანატის მხარე ავსტრიაზე გადავიდა და ოსმალური საზღვარი დუნაის სამხრეთით გადაიწია. იმავე თარიღს ატლასში ოსმალებიდან ჰაბსბურგებზე გადასული სხვა დასახლებები: ჩაკოვარი (Csákóvár), ფაჩეტი (Facset) და კარანშებეში (Caransebeş) — ტიმიშოარას ეიალეთის გადაცემასთან ერთად (TDV timisvar; ადგილობრივ დონეზე დღე წყაროში არ არის, „უფროსი ცენტრის“ ჯაჭვი, დეკლარირებული მიახლოება).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["ჰარამის (იენი-პალანკის) ციხის ავსტრიისთვის ჩაბარება — ბანატის დუნაის ნაპირი ხელიდან გავიდა", "38ee4c6d"], "d": ["ტიმიშოარას დაცემის შემდეგ ბანატის დანარჩენი ნაწილის აღება დავალებული ავსტრიელი ცხენოსანი გენერალი მერსი 14 ნოემბერს დუნაის ნაპირას მდებარე ჰარამს (იენი-პალანკას) შეუტია; 16 ნოემბერს ციხესთან მისვლისას 200-კაციანმა ოსმალურმა გარნიზონმა თეთრი დროშა აღმართა და თავისუფლად გასვლის პირობით დანებდა. ამგვარად, 1552 წლიდან ოსმალთა ხელში მყოფი სამხრეთ ბანატის დუნაის ხაზიც ავსტრიაზე გადავიდა. იმავე თარიღს ატლასში ოსმალებიდან ჰაბსბურგებზე გადასული სხვა დასახლება: ვერშეცი — ის ჰარამის „უფროსი ცენტრის“ ჯაჭვს მიჰყვება (Bánlaky 0019/1703; დეკლარირებული მიახლოება).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["პოჟარევაცის ზავი — მორეა მოიგეს, ბელგრადი და ბანატი დაკარგეს", "d46aa216"], "d": ["მორეა ვენეციისგან დაბრუნებული იყო, მაგრამ ომში ჩართული ავსტრია პეტროვარადინსა და ბელგრადში მოპოვებული გამარჯვებებით მოლაპარაკების მაგიდასთან უპირატესი მივიდა. ინგლისისა და ჰოლანდიის შუამავლობით ხელმოწერილმა ზავმა მორეა ოსმალებს დაუტოვა, სამაგიეროდ ბელგრადთან ერთად ჩრდილოეთ სერბეთი, ბანატი და მცირე ვლახეთი ავსტრიას დაუთმეს; TDV-ის გამოთქმით, „ჩრდილოეთ ბოსნია მთლიანად ავსტრიას დაეთმო“ — სავას გასწვრივ მდებარე ისეთი ციხეები, როგორიცაა ბოსნიის დუბიცა და ბოსნიის ბროდი, რუკაზე ამ დღიდან ავსტრიაზე გადადის (ზუსტი საზღვარი კომისრებმა სათითაოდ გაავლეს, TDV ამ ციხეებს სახელებით არ ჩამოთვლის); ვენეციამ კი იონიის სანაპიროზე ისეთი პოზიციები შეინარჩუნა, როგორიცაა პრევეზა და კითერა. იმავე დღეს ხელმოწერილი სავაჭრო აჰდნამეთი ავსტრიული საქონლის საბაჟო გადასახადი ხუთი პროცენტიდან სამამდე შემცირდა. ზავმა ცენტრალურ ევროპაში ოსმალეთის სახელმწიფოს უკანდახევა დააფიქსირა, მაგრამ მის მიერ გახსნილმა ოცდაშვიდწლიანმა მშვიდობამ ტიტების ეპოქის (1718-1730) საფუძველი შექმნა: ნევშეჰირლი დამად იბრაჰიმ-ფაშას მმართველობისას პირველი ოსმალური სტამბა (1727, იბრაჰიმ მუთეფერიქა), სათარგმნო კომისიები, ყვავილის აცრის დაკვირვებები და სასახლის ახალი კულტურული ცხოვრება ამ სამშვიდობო წლების ნაყოფია. იმავე დღეს ატლასში ხელიდან ხელში გადასული სხვა დასახლებები: კრაიოვა (Craiova), რიმნიკი (Râmnicu Vâlcea) და ტურნუ-სევერინი (მცირე ვლახეთი/ოლტენია, ოსმალებიდან ავსტრიაზე) და ლეფკადა (აია-მავრა) (ოსმალებიდან ვენეციაზე; TDV ayamavra: 1718 წელს პოჟარევაცის ზავით კუნძული ვენეციას დაეთმო). მცირე ვლახეთში ასევე თარგუ-ჯიუ ავსტრიაზე; ვონიცა (Voniçe, TDV pasarofca-antlasmasi) და კუნძული კითერა (TDV cuka-adasi: პოჟარევაცის მე-3 მუხლი) ვენეციაზე გადადის.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["აღმოსავლური ლაშქრობა: თბილისის აღება და ირანთან ომის დაწყება", "78343dc2"], "d": ["ავღანელთა შემოსევით სეფიანთა სახელმწიფოს ნგრევისა და რუსეთის კასპიის სანაპიროებამდე ჩამოსვლის გამო, ოსმალეთის სახელმწიფომ აღმოსავლეთში ჯარი გაგზავნა, რათა გაჩენილი სიცარიელე სრულად რუსული გავლენის ქვეშ არ დარჩენილიყო. თბილისი აიღეს და საქართველო ოსმალთა მმართველობას დაუქვემდებარეს; შემდეგ წინსვლა განჯის, ერევნისა და ნახიჭევანის მიმართულებით გაგრძელდა. ტიტების ეპოქის მშვიდობიანი იმიჯის უკან წარმოებული ეს ლაშქრობა იყო იმ ხანგრძლივი აღმოსავლური თავგადასავლის დასაწყისი, რომელიც ცამეტი წელი გაგრძელდებოდა და ბოლოს ყველა აღებული ადგილის დაბრუნებით დასრულდებოდა.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723 წლის ირანული ლაშქრობა: შესვლა შირვანსა და საქართველოში", "c81189fc"], "d": ["ავღანელთა შემოსევით სეფიანთა სახელმწიფოს ნგრევის გამო, რუსეთის კასპიის სანაპიროებამდე ჩამოსვლის თავიდან ასაცილებლად აღმოსავლეთისკენ ლაშქრობა გაიხსნა. ერზურუმის ჯარი საქართველოს გავლით თბილისში, შირვანის ფრთა კი შამახიაში შევიდა და ას ოცდაათი წლის წინ დაკარგული მიწები დაიბრუნა. ეს ლაშქრობა კავკასიაში ოსმალთა უკანასკნელი დიდი წინსვლა გახდა.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["ქერმანშაჰის აღება — ზაგროსის კარი", "ad14799f"], "d": ["ბაღდადის ჯარმა ზაგროსის გადასასვლელები გადალახა და ირანის დასავლეთ კარად მიჩნეული ქერმანშაჰი აიღო. ქალაქი ბაღდადიდან ისპაჰანისკენ მიმავალი ქარავნისა და ჯარის გზაზე მდებარეობდა და მისი აღება ერაყის ეიალეთის აღმოსავლეთ უსაფრთხოებას უზრუნველყოფდა. ამ წინსვლამ დაშლილ სეფიანთა ქვეყანაში ოსმალებსა და რუსეთს შორის გაყოფის რბოლა დაიწყო.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["სტამბოლის გაყოფის ხელშეკრულება — ირანის გაყოფა რუსეთთან", "fce8eec2"], "d": ["დამხობილი სეფიანთა ქვეყნის საკითხზე ოსმალებისა და რუსეთის დაპირისპირების თავიდან ასაცილებლად ფრანგი ელჩის შუამავლობით გაყოფის ხელშეკრულება დაიდო. კასპიის ზღვის დასავლეთი და სამხრეთი სანაპიროები რუსეთს, საქართველო, შირვანი, აზერბაიჯანი და დასავლეთ ირანის ქალაქები კი ოსმალეთის სახელმწიფოს დარჩა. ქაღალდზე დიდ შენაძენად გამოჩენილი ეს გაყოფა მალე, ნადირ შაჰის აღზევებით, ფაქტობრივად ძალადაკარგული გახდებოდა. ხელშეკრულების მიხედვით, შირვანის ისეთი ნაყოფიერი მიწები, როგორიცაა შაბრანი და მუშქური, რუსეთის მხარეს დარჩა (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["ნახიჭევანის აღება", "bdf14d0a"], "d": ["არაქსის გასწვრივ წინ მიმავალმა ოსმალურმა ძალებმა ნახიჭევანი და ორდუბადი აიღეს; ჯულფაც ნახიჭევანის ლივას შეუერთდა. ქალაქი, ირანის ჩრდილო-დასავლეთი კარის სახით, ახლად დაარსებულ ერევნის ეიალეთს დაუქვემდებარეს. ამგვარად, ოსმალური საზღვარი კანუნის ეპოქის ყველაზე აღმოსავლურ ხაზს კვლავ მიაღწია.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["ჰამადანის დაპყრობა", "e1339a97"], "d": ["ქერმანშაჰიდან აღმოსავლეთისკენ მიმავალმა ჯარმა ირანის პლატოს დასავლეთ ზღურბლზე მდებარე ჰამადანი ხანგრძლივი ალყის შემდეგ აიღო. ქალაქი ისპაჰანის გზაზე უკანასკნელი დიდი გაჩერება იყო; ეს გზა ორი ერაყის ლაშქრობის შემდეგ ოსმალური ჯარებისთვის ყველაზე აღმოსავლური მისაღწევი მიმართულება იყო. იმავე წელს რუსეთთან ხელმოწერილმა სტამბოლის ხელშეკრულებამ დაშლილი ირანის ოსმალებსა და რუსეთს შორის გაყოფა ქაღალდზე გადაიტანა.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["ერევნის ხელახალი აღება", "88acabef"], "d": ["ოთხმოცდაათდღიანი მძიმე ალყის შემდეგ არაქსის ხეობის საკვანძო ციხე ერევანი კვლავ ოსმალურ მმართველობაში შევიდა. 1583 წელს აშენებული და 1604 წელს დაკარგული ციხე ამჯერად უფრო ძლიერი გარნიზონით გაამაგრეს. ალყის ხანგრძლივობა იმის მაჩვენებელი იყო, რომ ოსმალური ჯარი უკვე ადვილად ვეღარ მიიწევდა. კარპის (უჩქილისე), შარურის, მაკუსა და შურაგელის ნაჰიეებიც ერევნის ეიალეთს დაუქვემდებარეს.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["თავრიზის აღება — აზერბაიჯანის დაკავება", "e502a4f7"], "d": ["ერთი წლის წინ წარუმატებელი მცდელობის შემდეგ კვლავ ალყაში მოქცეული თავრიზი ქუჩა-ქუჩა გაგრძელებული მძიმე ბრძოლის შემდეგ ოსმალურ ჯარს დანებდა. თავრიზის ეიალეთზე დაქვემდებარებული მერენდი, მარაღა და სოვუყბულაყი (მაჰაბადი) ასევე ოსმალთა მმართველობაში შევიდა. იმავე წელს ლორი, განჯა, არდებილი და ხორემაბადიც აიღეს და სტამბოლის გაყოფის ხელშეკრულებით ოსმალთა წილად მოხვედრილი მხარეები ფაქტობრივად ოკუპირებული იქნა. აღმოსავლეთში მიღწეული ეს სივრცე ფერჰად-ფაშას ზავის ხანის შემდეგ ყველაზე წინ წაწეული საზღვარი იყო; მაგრამ მისი შენარჩუნება ჯარსა და ხაზინას მძიმე ტვირთად დააწვა.", "e0953563"]}
});
